public class Person {
    private String name;
    private int age;
    private String gender;
    private ArrayList<String> hobbies;

    public Person(String name, int age, String gender, ArrayList<String> hobbies) {
        validateName(name);
        validateAge(age);
        validateGender(gender);
        this.name = name;
        this.age = age;
        this.gender = gender;
        // Validate and create copy of hobbies array
        this.hobbies = new ArrayList<>();
        if (hobbies != null) {
            for (String hobby : hobbies) {
                addHobby(hobby);  // reuse addHobby for validation and duplicate-checking
            }
        }
    }

    // Utility methods for validations
    private void validateName(String name) {
        if (name == null || name.trim().isEmpty() || name.length() > 100) {
            throw new IllegalArgumentException("Name must be non-empty and no more than 100 characters.");
        }
    }

    private void validateAge(int age) {
        if (age < 0 || age > 150) {
            throw new IllegalArgumentException("Age must be between 0 and 150 (inclusive).");
        }
    }

    private void validateGender(String gender) {
        if (!("male".equalsIgnoreCase(gender) || "female".equalsIgnoreCase(gender))) {
            throw new IllegalArgumentException("Gender must be either 'male' or 'female'.");
        }
    }

    private void validateHobby(String hobby) {
        if (hobby == null || hobby.trim().isEmpty() || hobby.length() > 100) {
            throw new IllegalArgumentException("Hobby must be non-empty and no more than 100 characters.");
        }
    }

    public void addHobby(String hobby) {
        validateHobby(hobby);
        if (!this.hobbies.contains(hobby)) {
            this.hobbies.add(hobby);
        }
    }

    public void removeHobby(String hobby) {
        if (!this.hobbies.remove(hobby)) {
            System.out.println("Hobby '" + hobby + "' was not found in the list.");
        }
    }

    public int countHobbies() {
        return this.hobbies.size();
    }

    public void printHobbies() {
        if (this.hobbies.isEmpty()) {
            System.out.println("No hobbies found.");
        } else {
            for (String hobby : hobbies) {
                System.out.println(hobby);
            }
        }
    }

    public ArrayList<String> getHobbies() {
        // Return a copy to prevent external modification
        return new ArrayList<>(this.hobbies);
    }

    public boolean hasHobby(String hobby) {
        return this.hobbies.contains(hobby);
    }

    public String getRandomHobby() {
        if (this.hobbies.isEmpty()) {
            throw new IllegalStateException("No hobbies available.");
        }
        int index = (int) (Math.random() * hobbies.size());
        return hobbies.get(index);
    }

    public void clearHobbies() {
        this.hobbies.clear();
    }

    public void changeName(String newName) {
        validateName(newName);
        this.name = newName;
    }

    public void changeAge(int newAge) {
        validateAge(newAge);
        this.age = newAge;
    }

    // Optional Getters for other fields
    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }

    public String getGender() {
        return gender;
    }

    // Additional toString method for debugging
    @Override
    public String toString() {
        return "Person{name='" + name + "', age=" + age +
               ", gender='" + gender + "', hobbies=" + hobbies + "}";
    }
}
