    # Convert the input list to a set to ensure uniqueness and filter elements greater than 1
    unique_elements = {num for num in lst if num > 1}

    # Sort the unique elements in descending order
    sorted_elements = sorted(unique_elements, reverse=True)

    # Calculate and return the sum of the sorted unique elements
    return sum(sorted_elements)

