Below is one acceptable solution in Python. In our solution we “build‐up” an augmented self–balancing binary search tree (in this case an AVL tree) in which each node remembers the total number of keys in its subtree (including duplicates). Then, once the tree is built, finding the kth smallest element (and hence the median) can be done in O(log n) time. (Note that building the tree from an unsorted list takes O(n log n) time overall, but the “median‐calculation” itself––i.e. the query––runs in O(log n) time.) We also include unit tests in which we cover various edge cases including an empty list and lists with duplicate values.

IMPORTANT: The problem statement forbids using any built–in sorting functions or libraries. (Our AVL implementation is “by hand” and does not use Python’s sort functions.)

Below is the complete code with comments and unit tests:

----------------------------------------------------
#!/usr/bin/env python3

# AVL Tree Node with augmentation: each node stores the number of nodes
# (including duplicates) in its subtree.
class AVLNode:
    def __init__(self, key):
        self.key = key
        self.count = 1  # frequency count for duplicates at this node
        self.left = None
        self.right = None
        self.height = 1  # height of this node in the tree
        self.subtree_size = 1  # total nodes in the subtree (including self)

def get_height(node):
    return node.height if node else 0

def get_subtree_size(node):
    return node.subtree_size if node else 0

def update_node(node):
    # update height and subtree size based on children
    node.height = 1 + max(get_height(node.left), get_height(node.right))
    node.subtree_size = node.count + get_subtree_size(node.left) + get_subtree_size(node.right)

def right_rotate(z):
    y = z.left
    T3 = y.right
    # rotation
    y.right = z
    z.left = T3
    # update heights and subtree sizes
    update_node(z)
    update_node(y)
    return y

def left_rotate(z):
    y = z.right
    T2 = y.left
    # rotation
    y.left = z
    z.right = T2
    # update heights and subtree sizes
    update_node(z)
    update_node(y)
    return y

def get_balance(node):
    if not node:
        return 0
    return get_height(node.left) - get_height(node.right)

def insert(root, key):
    # Standard AVL insertion with duplicate handling:
    if not root:
        return AVLNode(key)
    if key == root.key:
        root.count += 1
    elif key < root.key:
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)

    update_node(root)

    balance = get_balance(root)

    # Left Left
    if balance > 1 and key < root.left.key:
        return right_rotate(root)
    # Right Right
    if balance < -1 and key > root.right.key:
        return left_rotate(root)
    # Left Right
    if balance > 1 and key > root.left.key:
        root.left = left_rotate(root.left)
        return right_rotate(root)
    # Right Left
    if balance < -1 and key < root.right.key:
        root.right = right_rotate(root.right)
        return left_rotate(root)

    return root

def kth_smallest(node, k):
    # returns the kth smallest element (1-indexed)
    # using the information stored in subtree_size and count.
    if not node:
        raise IndexError("k is out of bounds")

    left_size = get_subtree_size(node.left)

    # if kth element is in the left subtree
    if k <= left_size:
        return kth_smallest(node.left, k)
    # if kth element is within the duplicates at this node
    elif k > left_size and k <= left_size + node.count:
        return node.key
    else:
        return kth_smallest(node.right, k - left_size - node.count)

def find_median(lst):
    """
    Calculates the median of a list of integers.
    Returns None for an empty list.
    For an odd count, returns the middle value.
    For an even count, returns the average of the two middle values.
    """
    if not lst:
        return None

    # Build an AVL tree from the list.
    root = None
    for num in lst:
        root = insert(root, num)

    total = get_subtree_size(root)
    if total % 2 == 1:
        # odd: kth element
        k = (total + 1) // 2
        median = kth_smallest(root, k)
        return median
    else:
        # even: average of kth and (k+1)th elements
        k1 = total // 2
        k2 = k1 + 1
        m1 = kth_smallest(root, k1)
        m2 = kth_smallest(root, k2)
        # if both values are integers we return the floating-point median if necessary
        return (m1 + m2) / 2

# -------------------- Unit Tests --------------------
import unittest

class TestFindMedian(unittest.TestCase):
    def test_empty_list(self):
        self.assertIsNone(find_median([]))

    def test_single_element(self):
        self.assertEqual(find_median([4]), 4)
        self.assertEqual(find_median([-2]), -2)

    def test_sorted_odd(self):
        self.assertEqual(find_median([2, 4, 6, 8, 10]), 6)

    def test_sorted_even(self):
        self.assertEqual(find_median([2, 4, 6, 8]), (4+6)/2)

    def test_unsorted(self):
        # Unsorted list with negatives and positives.
        lst = [8, 2, 6, 4, 10]
        self.assertEqual(find_median(lst), 6)

    def test_duplicates(self):
        # List with duplicate numbers.
        lst = [4, 2, 2, 8, 6, 4, 10]
        # Sorted version would be [2, 2, 4, 4, 6, 8, 10] => median is 4.
        self.assertEqual(find_median(lst), 4)

    def test_even_count_duplicates(self):
        # Even count with duplicates.
        lst = [4, 2, 2, 8, 6, 4]
        # Sorted: [2, 2, 4, 4, 6, 8] => median = (4+4)/2 = 4.
        self.assertEqual(find_median(lst), 4)

if __name__ == '__main__':
    # Running the unit tests will run our test cases:
    unittest.main()

----------------------------------------------------

How the code works:

1. The AVL tree is built by inserting each element (handling duplicates by increasing the count in the node). Each node also tracks its subtree size.
2. Once the tree is built, we determine the total number of elements.
3. For odd totals, we find the ((n+1)//2)-th smallest element. For even totals, we find the two middle elements and take their average.
4. The kth_smallest() function uses the augmented subtree sizes to “jump” to the kth element in O(log n) time.
5. Unit tests are provided to ensure that the function works for empty lists, single–element lists, unsorted lists, lists with duplicates and both odd and even counts.

This solution meets the requirement that the median retrieval itself takes O(log n) time, and it does not rely on any built–in sorting functions.

