Below is the modified program where the bubble sort algorithm has been updated to sort integers in descending order. Notice that instead of swapping when arr[j] > arr[j+1] (which would produce ascending order), we swap when arr[j] < arr[j+1] so that larger numbers "bubble" toward the start of the list. Also included are unit tests using Python's unittest module to check various edge cases (such as an empty array and an array with one element) as well as other typical cases.

------------------------------------------------------------
#!/usr/bin/env python3

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            # For descending order, swap if the current element is less than the next element.
            if arr[j] < arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

# Example usage:
if __name__ == "__main__":
    arr = [64, 34, 25, 12, 22, 11, 90]
    sorted_arr = bubble_sort(arr)
    print("Sorted (Descending):", sorted_arr)

# Unit tests
import unittest

class TestBubbleSortDescending(unittest.TestCase):
    def test_empty_array(self):
        self.assertEqual(bubble_sort([]), [])

    def test_single_element(self):
        self.assertEqual(bubble_sort([42]), [42])

    def test_already_sorted_descending(self):
        self.assertEqual(bubble_sort([100, 50, 25, 10]), [100, 50, 25, 10])

    def test_sorted_ascending(self):
        self.assertEqual(bubble_sort([1, 2, 3, 4, 5]), [5, 4, 3, 2, 1])

    def test_random_order(self):
        test_array = [3, 6, 2, 8, 5, 1, 9]
        expected = sorted(test_array, reverse=True)  # descending order
        self.assertEqual(bubble_sort(test_array), expected)

if __name__ == '__main__':
    # Run unit tests if this script is executed
    unittest.main()

