function swapNestedElements(nestedArr, idx1, idx2) {
  // Validate that the first argument is an array.
  if (!Array.isArray(nestedArr)) {
    throw new TypeError("Expected the first argument to be an array.");
  }
  // Validate that the indices are numbers.
  if (typeof idx1 !== 'number' || typeof idx2 !== 'number') {
    throw new TypeError("Indices must be numbers.");
  }
  if (idx1 < 0 || idx2 < 0) {
    throw new RangeError("Indices must be nonnegative.");
  }

