    // We use "if (i in current)" to check if the index is defined (sparse array handling).
    for (let i = 0; i < current.length; i++) {
      if (!(i in current)) continue; // skip sparse elements

      // current element is encountered in the flattened order.
      if (count === idx1) {
        targetPath1 = path.concat(i);
      }
      if (count === idx2) {
        targetPath2 = path.concat(i);
      }
      count++;

      // Early exit if both targets have been found.
      if (targetPath1 && targetPath2 && count > Math.max(idx1, idx2)) {
        // Still check inside loops where needed.
        // We do not immediately exit the DFS function since recursion might be in progress.
      }
      // If the element itself is an array, then traverse into it.
      let element = current[i];
      if (Array.isArray(element)) {
        DFS(element, path.concat(i));
        // Check early exit possibility after returning from recursion:
        if (targetPath1 && targetPath2 && count > Math.max(idx1, idx2)) {
          // Early exit: no need to continue further.
          // (Note: we cannot break out of the outer recursion entirely,
          // but each call will finish going through its loop.)
        }
