def remove_duplicates_preserving_order(arr):
    """
    Remove duplicate elements from a list while preserving the original order.

    Parameters:
        arr (list): The input list of integers, which may contain duplicate values.

    Returns:
        list: A new list that contains only the first occurrence of each element
              from the input list, preserving the original order.

    Raises:
        TypeError: If the input is not a list.
    """
    if not isinstance(arr, list):
        raise TypeError("Input must be a list")

    seen = set()
    result = []
    for item in arr:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


