"use strict";

// A helper function to perform deep equality check between two values.
// It will correctly compare nested arrays (lists) and any other data types.
function deepEqual(a, b) {
  // Check if both are arrays.
  if (Array.isArray(a) && Array.isArray(b)) {
    // If they have different lengths then are not equal.
    if (a.length !== b.length) return false;
    // Compare each element recursively.
    for (let i = 0; i < a.length; i++) {
      // Use recursion to compare each element.
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  } else if (typeof a === "object" && a !== null &&
             typeof b === "object" && b !== null) {
    // If both are objects (but not arrays) compare keys
    let keysA = Object.keys(a);
    let keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (let key of keysA) {
      if (!b.hasOwnProperty(key) || !deepEqual(a[key], b[key])) return false;
    }
    return true;
  } else {
    // For primitives use simple equality.
    return a === b;
  }
}

// The main function that returns the index of the last occurrence
// of target in mylist. Returns -1 if the target is not found.
// The search is done recursively.
function linearSearchLastOccurrence(mylist, target) {
  // Internal recursive helper function.
  // index: current index being inspected.
  // lastOccurrence: the last found index so far.
  function recursiveSearch(index, lastOccurrence) {
    // Base case: we have reached the end of the list.
    if (index >= mylist.length) {
      return lastOccurrence;
    }

    // Check for the current element.
    // Using deepEqual to handle nested arrays.
    if (deepEqual(mylist[index], target)) {
      // Update lastOccurrence to the current index.
      lastOccurrence = index;
    }
    // Recurse to the next index.
    return recursiveSearch(index + 1, lastOccurrence);
  }

  // Start recursion at the beginning (index 0) with lastOccurrence = -1.
  return recursiveSearch(0, -1);
}

