import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def check_numbers(string):
    numbers = string.split()
    for number in numbers:
        parts = number.split('e')
        if len(parts) != 2:
            return False
        mantissa = parts[0]
        exponent = int(parts[1])
        if not mantissa.replace('.', '').isdigit():
            return False
        if not is_prime(exponent):
            return False
    return True

# Example tests
print(check_numbers("3.14e5 1.23e-4 2e10"))  # True
print(check_numbers("1.2e4 -5.6e7 8.9e2 4e-3"))  # False
print(check_numbers("1e0 2e1 3e2 4e3 5e4 6e5"))  # False
```

The `is_prime` function checks if a given number is prime or not. The `check_numbers` function splits the input string into individual numbers, and for each number, it checks if it is in scientific notation with a valid exponent (using the `isdigit` function to check if the mantissa is numeric and `is_prime` function to check if the exponent is prime).

