function validateAndFormatJSONData(data) {
  // Utility functions
  const isPositiveInteger = (value) => Number.isInteger(value) && value > 0;
  const isNonEmptyString = (value) => typeof value === 'string' && value.trim() !== '';

  // 1. Check existence of required top-level fields.
  const requiredFields = ['name', 'age', 'address', 'contact', 'hobbies', 'languages', 'education', 'experience'];
  for (const field of requiredFields) {
    if (!(field in data)) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  // Validate name field (assuming it's a non-empty string)
  if (!isNonEmptyString(data.name)) {
    throw new Error("Field 'name' must be a non-empty string");
  }

  // 2. Validate age - must be positive integer.
  if (!isPositiveInteger(data.age)) {
    throw new Error("Field 'age' must be a positive integer");
  }

  // 3. Validate address object
  if (typeof data.address !== 'object' || data.address === null || Array.isArray(data.address)) {
    throw new Error("Field 'address' must be an object");
  }
  const addressFields = ['street', 'city', 'state', 'country'];
  for (const field of addressFields) {
    if (!(field in data.address)) {
      throw new Error(`Missing required field in address: ${field}`);
    }
    if (!isNonEmptyString(data.address[field])) {
      throw new Error(`Address field '${field}' must be a non-empty string`);
    }
  }

  // 4. Validate contact object.
  if (typeof data.contact !== 'object' || data.contact === null || Array.isArray(data.contact)) {
    throw new Error("Field 'contact' must be an object");
  }
  // Required fields: email, phone
  const contactFields = ['email', 'phone'];
  for (const field of contactFields) {
    if (!(field in data.contact)) {
      throw new Error(`Missing required field in contact: ${field}`);
    }
    if (!isNonEmptyString(data.contact[field])) {
      throw new Error(`Contact field '${field}' must be a non-empty string`);
    }
  }

  // Validate email using a simple regex.
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(data.contact.email)) {
    throw new Error("Field 'email' in contact must be a valid email address");
  }

  // Validate phone number: expected format "+x xxx-xxx-xxxx"
  // Explanation: plus sign, one digit country code, space, then 3 digits, dash, 3 digits, dash, 4 digits.
  const phoneRegex = /^\+\d\s\d{3}-\d{3}-\d{4}$/;
  if (!phoneRegex.test(data.contact.phone)) {
    throw new Error("Field 'phone' in contact must be a valid phone number in the format '+x xxx-xxx-xxxx'");
  }

  // 5. Validate hobbies field: must be an array of strings.
  if (!Array.isArray(data.hobbies)) {
    throw new Error("Field 'hobbies' must be an array");
  }
  for (const hobby of data.hobbies) {
    if (!isNonEmptyString(hobby)) {
      throw new Error("Each item in 'hobbies' must be a non-empty string");
    }
  }

  // 6. Validate languages field: must be an object with boolean values for 'english', 'spanish', 'french'.
  if (typeof data.languages !== 'object' || data.languages === null || Array.isArray(data.languages)) {
    throw new Error("Field 'languages' must be an object");
  }
  const languageFields = ['english', 'spanish', 'french'];
  for (const lang of languageFields) {
    if (!(lang in data.languages)) {
      throw new Error(`Missing required language field: ${lang}`);
    }
    if (typeof data.languages[lang] !== 'boolean') {
      throw new Error(`Language field '${lang}' must be a boolean`);
    }
  }

  // 7. Validate education object.
  if (typeof data.education !== 'object' || data.education === null || Array.isArray(data.education)) {
    throw new Error("Field 'education' must be an object");
  }
  const educationFields = ['degree', 'major', 'university'];
  for (const field of educationFields) {
    if (!(field in data.education)) {
      throw new Error(`Missing required field in education: ${field}`);
    }
    if (!isNonEmptyString(data.education[field])) {
      throw new Error(`Education field '${field}' must be a non-empty string`);
    }
  }

  // 8. Validate experience array.
  if (!Array.isArray(data.experience)) {
    throw new Error("Field 'experience' must be an array");
  }
  for (let i = 0; i < data.experience.length; i++) {
    const exp = data.experience[i];
    if (typeof exp !== 'object' || exp === null || Array.isArray(exp)) {
      throw new Error(`Each experience item must be an object (error at index ${i})`);
    }
    // Must have company, position, and years.
    const expFields = ['company', 'position', 'years'];
    for (const field of expFields) {
      if (!(field in exp)) {
        throw new Error(`Missing required field in experience at index ${i}: ${field}`);
      }
    }
    if (!isNonEmptyString(exp.company)) {
      throw new Error(`Experience at index ${i} 'company' must be a non-empty string`);
    }
    if (!isNonEmptyString(exp.position)) {
      throw new Error(`Experience at index ${i} 'position' must be a non-empty string`);
    }
    if (!isPositiveInteger(exp.years)) {
      throw new Error(`Experience at index ${i} 'years' must be a positive integer`);
    }
  }

  // All validations passed; return a pretty-printed JSON string.
  return JSON.stringify(data, null, 2);
}

