Below is one acceptable solution in C++ that meets all the requirements. In this solution we implement merge sort (an O(n log n) algorithm) without calling any built‐in sorting routines. We allocate an auxiliary array (using extra space O(n) which is allowed) and we take care to “handle duplicate numbers efficiently” (since merge sort naturally deals with duplicates without any extra work). After sorting the list of numbers we compute the square of each (using a 64‐bit type to be safe) and print the number along with its corresponding square.

Below is the complete C++ code:

------------------------------------------------
#include <iostream>
#include <vector>
using namespace std;

// Merge function for merge sort.
// It merges two sorted halves arr[l..m] and arr[m+1..r]
void merge(vector<int>& arr, int l, int m, int r) {
    // create temporary vectors for left and right parts
    int n1 = m - l + 1;
    int n2 = r - m;
    vector<int> L(n1), R(n2);

    for (int i = 0; i < n1; i++)
        L[i] = arr[l + i];
    for (int j = 0; j < n2; j++)
        R[j] = arr[m + 1 + j];

    int i = 0, j = 0, k = l;
    // Merge the temp arrays back into arr[l..r]
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {  // <= ensures duplicates remain in order and handled properly
            arr[k] = L[i];
            i++;
        } else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    // Copy remaining elements of L, if any
    while (i < n1) {
        arr[k] = L[i];
        i++; k++;
    }

    // Copy remaining elements of R, if any
    while (j < n2) {
        arr[k] = R[j];
        j++; k++;
    }
}

// Merge sort function: sorts arr[l..r]
void mergeSort(vector<int>& arr, int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2; // avoid potential overflow
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> numbers(n);

    for (int i = 0; i < n; i++){
        cin >> numbers[i];
    }

    // Sort the numbers using our own merge sort implementation
    mergeSort(numbers, 0, n - 1);

    // After sorting, print the numbers and their corresponding squares.
    // Using long long to hold the square because the numbers can be as large as 10^9.
    for (int i = 0; i < n; i++){
        long long square = 1LL * numbers[i] * numbers[i];
        cout << numbers[i] << " " << square << "\n";
    }

    return 0;
}

------------------------------------------------

Explanation of key points:

1. We implement our own merge sort (which is O(n log n)) in the functions mergeSort and merge.
2. We use ≤ in the merge step so that duplicate numbers are maintained in a stable manner and handled efficiently.
3. The extra memory used for the temporary arrays in merge is O(n), which is within the allowed complexity.
4. Each number’s square is computed using 1LL*number*number to avoid integer overflow.
5. Finally, we print each sorted number along with its square.

This solution meets the time and space constraints and avoids using any built-in sort functions.

