The idea is to:
1. Remove extra leading, trailing, and in-between spaces in place.
2. Reverse the whole string.
3. Reverse each word to restore its original character order.

Here’s the complete code with comments:

------------------------------------------------
#include <iostream>
#include <string>
using namespace std;

// Helper function: reverse a portion of the string in place.
void reversePortion(string &s, int left, int right) {
    while (left < right) {
        swap(s[left++], s[right--]);
    }
}

string reverseWords(string s) {
    int n = s.size();
    // Step 1: Remove leading, trailing, and duplicate spaces.
    // We'll use two pointers: i for reading, j for writing.
    int j = 0;
    for (int i = 0; i < n; ++i) {
        // Skip space characters if it's either the first character written
        // or if the previous written character was also a space.
        if (s[i] != ' ') {
            s[j++] = s[i];
        } else if (j > 0 && s[j - 1] != ' ') {
            s[j++] = ' ';
        }
    }
    // Remove trailing space if any.
    if (j > 0 && s[j - 1] == ' ')
        --j;

    s.resize(j);  // Now s is trimmed and consecutive spaces are collapsed.

    // Step 2: Reverse the entire string.
    reversePortion(s, 0, s.size() - 1);

    // Step 3: Reverse each word in the reversed string.
    int start = 0;
    for (int i = 0; i <= s.size(); i++) {
        // i==s.size() or working on space indicates end of a word.
        if (i == s.size() || s[i] == ' ') {
            reversePortion(s, start, i - 1);
            start = i + 1;
        }
    }

    return s;
}

int main(){
    // Example usage:
    string input = "   Hello    world   from   OpenAI   ";
    string output = reverseWords(input);
    cout << "Input: [" << input << "]" << endl;
    cout << "Output: [" << output << "]" << endl;
    // Expected Output: "OpenAI from world Hello"
    return 0;
}

------------------------------------------------

Explanation:

• In the first loop, we copy characters with two pointers so that:
 – Leading spaces are skipped.
 – Consecutive spaces are collapsed into a single space.
 – A trailing space is removed if present.
 
• Then, we reverse the entire string. For example, after reversing "OpenAI from world Hello" we obtain "olleH dlrow morf IAnepO".

• Finally, we reverse each word (identified by spaces or the end of the string) to put the characters of each word back into the correct order while keeping the word order reversed.

This solution works in linear time relative to the length of the string and uses only a constant amount of extra space.

