# Python Code

def second_occurrence_index(nums, target):
    occurrence_count = 0
    for index, num in enumerate(nums):
        if num == target:
            occurrence_count += 1
            if occurrence_count == 2:
                return index
    return -1

# Unit tests for the function
import unittest

class TestSecondOccurrenceIndex(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(second_occurrence_index([], 3), -1)

    def test_no_occurrence(self):
        self.assertEqual(second_occurrence_index([1, 2, 4, 5], 3), -1)

    def test_one_occurrence(self):
        self.assertEqual(second_occurrence_index([1, 3, 2, 4, 5], 3), -1)

    def test_multiple_occurrences(self):
        self.assertEqual(second_occurrence_index([1, 3, 2, 3, 4, 3], 3), 3)
        self.assertEqual(second_occurrence_index([3, 1, 3, 3, 5], 3), 2)

    def test_target_at_start_and_end(self):
        self.assertEqual(second_occurrence_index([3, 1, 2, 4, 3], 3), 4)

if __name__ == '__main__':
    unittest.main()

