Below is an example Python solution that meets all the requirements. Note that in a real‐world situation you might want to split validations into separate modules/functions or use data‐validation libraries. For clarity, the validations are implemented inline as helper methods. You can adjust the maximum lengths and allowed patterns as needed.

------------------------------------------------------------
#!/usr/bin/env python3
import re
from datetime import datetime
import itertools

class ValidationError(Exception):
    pass

def validate_nonempty_text(text, field_name):
    if not isinstance(text, str) or not text.strip():
        raise ValidationError(f"{field_name} cannot be empty.")
    return text.strip()

def validate_alpha_space(text, field_name, max_length=50):
    text = validate_nonempty_text(text, field_name)
    # Allowed: alphabets and spaces only
    if len(text) > max_length:
        raise ValidationError(f"{field_name} must be at most {max_length} characters long.")
    if not re.fullmatch(r"[A-Za-z\s]+", text):
        raise ValidationError(f"{field_name} must contain only alphabets and spaces.")
    return text

def validate_zip(zip_code, country="US"):
    zip_code = str(zip_code).strip()
    if country.upper() == "US":
        if not re.fullmatch(r"\d{5}", zip_code):
            raise ValidationError("For US addresses, the zip code must be exactly 5 digits.")
    else:
        # A basic check: international zip code can be alphanumeric and spaces; this is a placeholder.
        if not re.fullmatch(r"[A-Za-z\d\s\-]+", zip_code):
            raise ValidationError("Invalid zip code format for international address.")
    return zip_code

def validate_hobby(hobby, max_length=50):
    hobby = validate_nonempty_text(hobby, "Hobby")
    if len(hobby) > max_length:
        raise ValidationError("Hobby must be less than {} characters.".format(max_length))
    # Only allow alphabets and spaces.
    if not re.fullmatch(r"[A-Za-z\s]+", hobby):
        raise ValidationError("Hobby must contain only alphabets and spaces.")
    return hobby

def validate_full_address(full_address, max_length=150):
    # Allows letters, digits, spaces, commas, hyphens
    if len(full_address) > max_length:
        raise ValidationError(f"Full address must be at most {max_length} characters.")
    if not re.fullmatch(r"[A-Za-z0-9,\s\-]+", full_address):
        raise ValidationError("Full address contains invalid characters.")
    return full_address

class Address:
    # A class-level counter to generate unique ids.
    _id_counter = itertools.count(1)

    def __init__(self, street, house_number, city, state, zip_code, country="US"):
        # Validate each component based on the rules.
        # For street, house_number, city, state we ensure they are non-empty, alpha-only (no numbers or special characters) 
        # and no longer than 50 characters.
        self.street = validate_alpha_space(street, "Street")
        self.house_number = validate_alpha_space(house_number, "House number")  # according to the requirement.
        self.city = validate_alpha_space(city, "City")
        self.state = validate_alpha_space(state, "State")
        self.zip_code = validate_zip(zip_code, country)

        self.country = country  # Used in zip validation, etc.
        # Unique id for the address instance.
        self.address_id = next(Address._id_counter)

    def full_address(self):
        # Concatenate the address components with commas
        full_addr = f"{self.house_number} {self.street}, {self.city}, {self.state} {self.zip_code}"
        # Validate full address format and length.
        validate_full_address(full_addr)
        return full_addr

    def __str__(self):
        return f"Address #{self.address_id}: {self.full_address()}"


class Person:
    MAX_HOBBIES = 10
    MAX_ADDRESSES = 5

    def __init__(self, name, age, hobbies=None):
        if hobbies is None:
            hobbies = []
        self.name = validate_nonempty_text(name, "Name")
        self.age = self._validate_age(age)
        self.hobbies = []  # We'll add hobbies after validation.
        for hobby in hobbies:
            self.add_hobby(hobby)  # use the method to add (with validation)
        # Manage multiple addresses in a dictionary by unique id.
        self.addresses = {}

    def _validate_age(self, age):
        if not isinstance(age, int) or age <= 0:
            raise ValidationError("Age must be a positive integer.")
        return age

    def calculate_age_in_months(self):
        # To account for leap years, we use the average year length of 365.2425 days.
        # However since we only have age in years, this essentially equals age * 12.
        months = self.age * 12
        if months <= 0:
            raise ValidationError("Calculated age in months must be a positive integer.")
        return months

    def calculate_birth_year(self):
        current_year = datetime.now().year
        birth_year = current_year - self.age
        # Validate that birth_year is a 4-digit number, e.g., between 1000 and 9999.
        if birth_year < 1000 or birth_year > 9999:
            raise ValidationError("Calculated birth year is not valid as a 4-digit number.")
        return birth_year

    def add_hobby(self, hobby):
        if len(self.hobbies) >= Person.MAX_HOBBIES:
            raise ValidationError(f"A person can have at most {Person.MAX_HOBBIES} hobbies.")
        hobby = validate_hobby(hobby)
        self.hobbies.append(hobby)

    def remove_hobby(self, hobby):
        # Remove hobby if exactly matches one entry (case insensitive).
        found = False
        for h in self.hobbies:
            if h.lower() == hobby.lower():
                self.hobbies.remove(h)
                found = True
                break
        if not found:
            raise ValidationError("Hobby not found.")

    def hobby_exists(self, query):
        # Search for a specific hobby, case insensitive and allowing partial matches.
        query_lower = query.lower()
        for h in self.hobbies:
            if query_lower in h.lower():
                return True
        return False

    # Methods to manage multiple addresses.
    def add_address(self, address):
        if not isinstance(address, Address):
            raise ValidationError("Address must be an instance of Address class.")
        if len(self.addresses) >= Person.MAX_ADDRESSES:
            raise ValidationError(f"A person can have at most {Person.MAX_ADDRESSES} addresses.")
        # Ensure the address id is unique (Address class deals with that).
        self.addresses[address.address_id] = address

    def remove_address(self, address_id):
        if address_id in self.addresses:
            del self.addresses[address_id]
        else:
            raise ValidationError("Address with the given ID does not exist.")

    def get_address(self, address_id):
        if address_id in self.addresses:
            return self.addresses[address_id]
        else:
            raise ValidationError("Address with the given ID does not exist.")

    def display_person_info(self):
        # Format: Capitalize the first letter of the name, hobbies and addresses.
        info_lines = []
        info_lines.append("PERSON INFORMATION")
        info_lines.append("------------------")
        info_lines.append("Name: " + self.name.title())
        info_lines.append("Age: {} years ({} months)".format(self.age, self.calculate_age_in_months()))
        info_lines.append("Birth Year: " + str(self.calculate_birth_year()))
        if self.hobbies:
            formatted_hobbies = [h.title() for h in self.hobbies]
            info_lines.append("Hobbies: " + ", ".join(formatted_hobbies))
        else:
            info_lines.append("Hobbies: None")
        if self.addresses:
            info_lines.append("Addresses:")
            for addr in self.addresses.values():
                info_lines.append("  - " + addr.full_address())
        else:
            info_lines.append("Addresses: None")
        return "\n".join(info_lines)

# -------------------------
# Example usage and testing
if __name__ == "__main__":
    try:
        # Create a person.
        p = Person(name="john doe", age=30, hobbies=["Reading", "Hiking"])
        # Add additional hobby.
        p.add_hobby("Swimming")
        # Check hobby exists (partial & case insensitive search)
        print("Does hobby 'hike' exist?", p.hobby_exists("hike"))

        # Create some addresses.
        addr1 = Address(street="Maple", house_number="Alpha", city="Springfield", state="Illinois", zip_code="62704")
        addr2 = Address(street="Elm", house_number="Beta", city="Chicago", state="Illinois", zip_code="60605")

        # Add addresses.
        p.add_address(addr1)
        p.add_address(addr2)

        # Display person's information.
        print(p.display_person_info())

        # Remove a hobby.
        p.remove_hobby("reading")
        print("\nAfter removing 'reading':")
        print(p.display_person_info())

        # Remove one address.
        p.remove_address(addr1.address_id)
        print("\nAfter removing one address:")
        print(p.display_person_info())

    except ValidationError as ve:
        print("Validation Error:", ve)
    except Exception as e:
        print("Error:", e)

