    assert transform_value({'a': 1, 'b': '', 'c': None, 'd': [1, '', None]}) == {'a': 1, 'b': 0, 'c': 0, 'd': [1, 0, 0]}
    assert transform_value([1, [2, '', [None]], {'a': '', 'b': [3, None, '']}]) == [1, [1, 0, [0]], {'a': 0, 'b': [3, 0, 0]}]
