#!/usr/bin/env python3

import math

def is_prime(n):
    """Check if a number n is prime."""
    if n < 2:
        return False
    # Only need to test up to the square root of n
    sqrt_n = int(math.sqrt(n))
    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            return False
    return True

def is_fibonacci(n):
    """Check if a number n is a Fibonacci number.

    A number is Fibonacci if and only if one of (5*n^2 + 4) or (5*n^2 - 4)
    is a perfect square.
    """
    # Helper function to check perfect square
    def is_perfect_square(x):
        s = int(math.sqrt(x))
        return s * s == x

    return is_perfect_square(5 * n ** 2 + 4) or is_perfect_square(5 * n ** 2 - 4)

def main():
    prime_fibonacci_numbers = []

    for number in range(1, 1001):
        if is_prime(number) and is_fibonacci(number):
            prime_fibonacci_numbers.append(number)

    # Pretty print the results
    print("Prime numbers in the range 1 to 1000 that are also Fibonacci numbers:")
    if prime_fibonacci_numbers:
        print(", ".join(str(num) for num in prime_fibonacci_numbers))
    else:
        print("None found.")

if __name__ == "__main__":
    main()

