This function takes two doubly linked lists that are sorted in descending order, and it merges them into one descending ordered list while skipping duplicate values. (It uses only pointer‐manipulation.)
 
 Node* mergeTwoDescendingLists(Node* list1, Node* list2) {
  // If one list is empty, return the other
  if (!list1) return list2;
  if (!list2) return list1;
 
  Node* head = nullptr; // head of merged list
  Node* tail = nullptr;
 
  // While both lists have nodes…
  while(list1 != nullptr && list2 != nullptr) {
    if(list1->val == list2->val) {
      // Pick one and skip duplicates
      Node* temp = list1;
      // Advance both lists
      list1 = list1->next;
      list2 = list2->next;
      temp->next = temp->prev = nullptr;
      // Append temp to merged list if it is not a duplicate of the tail.
      if(tail == nullptr || tail->val != temp->val) {
        if(tail) {
          tail->next = temp;
          temp->prev = tail;
          tail = temp;
        } else {
          head = tail = temp;
        }
      }
    } else if(list1->val > list2->val) {
      // list1->val is greater so it comes first in descending order
      Node* temp = list1;
