            if isinstance(number, (int, float)) and number < 0:
                raise ValueError("Cannot calculate square root of a negative number.")
            # If the number is complex, use cmath.sqrt to support negative real parts as complex numbers.
            if isinstance(number, complex):
                result = cmath.sqrt(number)
            else:
                result = math.sqrt(number)
            return self._round(result)
        except Exception as e:
            raise ValueError(f"Square root error: {e}")

    def factorial(self, n):
        """
        Calculate the factorial of a number.
        The input must be a non-negative integer.
        """
        # Check whether n is an integer and non-negative.
        if not (isinstance(n, int) or (isinstance(n, float) and n.is_integer())):
            raise ValueError("Factorial is only defined for integers.")
        n = int(n)
        if n < 0:
            raise ValueError("Factorial is not defined for negative integers.")

        result = 1
        for i in range(2, n + 1):
            result *= i
        # Although factorial results are integers, we return a rounded float for consistency.
        return self._round(float(result))

    def power(self, base, exponent):
        """
        Calculate the result of raising 'base' to the power 'exponent'.
        """
        try:
            result = base ** exponent
            return self._round(result)
        except Exception as e:
            raise ValueError(f"Power calculation error: {e}")

