import random
import math

def task_func(LETTERS=[chr(i) for i in range(97, 123)]):
    # Create a dictionary with each key as a letter from the LETTERS list.
    # The value for each key is a list containing between 1 to 10 random integers in range 0 to 100.
    random_lists = {letter: [random.randint(0, 100) for _ in range(random.randint(1, 10))] for letter in LETTERS}

    # Function to calculate population standard deviation for a given list of numbers.
    def population_std(numbers):
        # Calculate the mean of the numbers.
        mean_val = sum(numbers) / len(numbers)
        # Calculate the variance using population std formula (dividing by n).
        variance = sum((x - mean_val) ** 2 for x in numbers) / len(numbers)
        # Return the square root of the variance.
        return math.sqrt(variance)

    # Calculate the population standard deviation for each random list.
    std_dict = {letter: population_std(numbers) for letter, numbers in random_lists.items()}

    return std_dict

# Example usage:
if __name__ == "__main__":
    # Print the dictionary of standard deviations per letter.
    result = task_func()
    for letter, std_dev in result.items():
        print(f"Letter: {letter}, Population Standard Deviation: {std_dev}")

