import os
import glob
import subprocess

def task_func(directory, backup_dir='/path/to/backup'):
    # Check if the specified directory exists
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory '{directory}' does not exist.")

    # Find all '.log' files in the directory
    log_files = glob.glob(os.path.join(directory, "*.log"))

    # If no log files found, return message
    if not log_files:
        return "No logs found to backup"

    # Ensure the backup directory exists, create if it doesn't
    os.makedirs(backup_dir, exist_ok=True)

    # Define the backup file path
    backup_file = os.path.join(backup_dir, "logs_backup.tar.gz")

    # Use 'subprocess' to create the tar.gz archive of log files
    # The tar command format is: tar -czf <archive> <file1> <file2> ...
    try:
        subprocess.run(["tar", "-czf", backup_file] + log_files, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error occurred during backup creation: {e}")

    # After successful backup, delete the original log files
    for log_file in log_files:
        try:
            os.remove(log_file)
        except Exception as e:
            # Handle any exception that occurs during file deletion
            print(f"Warning: Unable to delete '{log_file}'. Error: {e}")

    return backup_file

