import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    """
    Checks if a process with the given process_name is running.

    - If not running, starts it using subprocess.Popen and returns a message.
    - If running, terminates all matching processes, waits for full termination,
      then restarts the process and returns a message.

    Exceptions during termination or starting are caught and returned as error messages.
    """
    # Collect processes whose name exactly matches process_name
    processes = []
    for proc in psutil.process_iter(attrs=['name']):
        try:
            if proc.info['name'] == process_name:
                processes.append(proc)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    # If no matching process is found, start it.
    if not processes:
        try:
            subprocess.Popen([process_name])
            return f"Process not found. Starting {process_name}."
        except Exception as e:
            return f"Error starting {process_name}: {e}"

    # If process(es) found, attempt to terminate them gracefully.
    for proc in processes:
        try:
            proc.terminate()  # request process termination
        except Exception as e:
            print(f"Error terminating process {process_name} (PID {proc.pid}): {e}")

    # Wait for the processes to be terminated
    # psutil.wait_procs returns a tuple (gone, alive)
    gone, alive = psutil.wait_procs(processes, timeout=5)

    # Force kill if there are any still alive
    if alive:
        for proc in alive:
            try:
                proc.kill()  # force kill
            except Exception as e:
                print(f"Error killing process {process_name} (PID {proc.pid}): {e}")
        # Wait again after killing
        psutil.wait_procs(alive, timeout=5)

    # After termination, start the process again.
    try:
        subprocess.Popen([process_name])
        return f"Process found. Restarting {process_name}."
    except Exception as e:
        return f"Error restarting {process_name}: {e}"

