import os
import zipfile

def task_func(directory):
    # Check if the directory exists and is indeed a directory
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"The specified directory does not exist: {directory}")

    # Check if the directory is writable by checking permissions on the directory itself
    if not os.access(directory, os.W_OK):
        raise PermissionError(f"The directory is not writable: {directory}")

    # List the files in the directory excluding subdirectories
    # Exclude the output zip file itself (files.zip) in case it already exists.
    all_files = []
    for item in os.listdir(directory):
        full_path = os.path.join(directory, item)
        # Only include items that are files and are not the target zip file.
        if os.path.isfile(full_path) and item != "files.zip":
            all_files.append(full_path)

    # If there are no files in the directory, return None
    if not all_files:
        return None

    # Prepare the path for the zip file
    output_zip_path = os.path.join(directory, "files.zip")

    # Create the zip file
    # Using 'w' mode to overwrite if the file already exists
    try:
        with zipfile.ZipFile(output_zip_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            for file_path in all_files:
                # Use arcname to add the file without the full path - just the base file name
                arcname = os.path.basename(file_path)
                zipf.write(file_path, arcname=arcname)
    except Exception as e:
        # In case of any issues writing the file, re-raise the exception.
        raise e

    return output_zip_path

