import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    # Sanitize and validate function inputs
    if not isinstance(file_path, str) or not file_path.strip():
        raise ValueError("Invalid file_path provided.")
    if not isinstance(attribute, str) or not attribute.strip():
        raise ValueError("Invalid attribute provided.")

    # Check if the attribute exists in our schema properties, preventing injection of unexpected keys.
    if attribute not in INPUT_JSON.get("properties", {}):
        raise ValueError(f"Attribute '{attribute}' is not a valid key in the defined schema.")

    # Validate file existence
    if not os.path.exists(file_path):
        raise ValueError(f"File does not exist at path: {file_path}")

    try:
        # Open and load the JSON file safely; 'with' ensures the file is closed properly.
        with open(file_path, 'r', encoding='utf-8') as json_file:
            try:
                data = json.load(json_file)
            except json.JSONDecodeError as jde:
                raise ValueError("The file does not contain valid JSON.") from jde
    except Exception as e:
        # Reraise any unexpected exceptions as ValueError for consistency.
        raise ValueError("Error reading the file.") from e

    # Validate that all required fields exist and are of the expected type.
    required_fields = INPUT_JSON.get("required", [])
    properties = INPUT_JSON.get("properties", {})
    for key in required_fields:
        if key not in data:
            raise ValueError(f"Missing required attribute: '{key}'.")
        expected_type = properties[key]["type"]
        # Check if the type of the value matches the expected type.
        if not isinstance(data[key], expected_type):
            raise ValueError(
                f"Attribute '{key}' is expected to be of type '{expected_type.__name__}', "
                f"but got type '{type(data[key]).__name__}'."
            )

    # Additional check: Validate the 'email' field format using the provided regular expression.
    email_value = data.get("email", "")
    if not isinstance(email_value, str) or not re.fullmatch(EMAIL_REGEX, email_value.lower()):
        raise ValueError("The email format is invalid.")

    # After all validations, retrieve the specified attribute.
    if attribute not in data:
        raise ValueError(f"The attribute '{attribute}' is not present in the JSON data.")

    return data[attribute]

# Example usage:
if __name__ == "__main__":
    # Suppose we have a sample JSON file 'user.json' with valid contents:
    # {
    #   "name": "John Doe",
    #   "age": 30,
    #   "email": "john.doe@example.com"
    # }
    sample_file_path = "user.json"  # Ensure this file exists with appropriate content for testing.
    try:
        result = task_func(sample_file_path, "email")
        print("Retrieved attribute:", result)
    except ValueError as ve:
        print("Validation error occurred:", ve)

