from flask import Flask, render_template_string, redirect, url_for, request, flash, session
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash
from datetime import datetime, timedelta

# Define the login form with Flask-WTF
class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

# Initialize the LoginManager from Flask-Login
login_manager = LoginManager()

# A simple User class
class User(UserMixin):
    def __init__(self, id, username, password_hash):
        self.id = id
        self.username = username
        self.password_hash = password_hash

# In-memory user "database"
# For demonstration purposes, we create one user: username "admin" with password "SuperSecret1"
users = {
    "admin": User(id="1", username="admin", password_hash=generate_password_hash("SuperSecret1"))
}

# For brute-force protection: maintain a dictionary that tracks failed login attempts per username.
# For each username, we store a dict with:
#   'attempts': number of failed attempts,
#   'last_attempt': datetime of the last failed attempt,
#   'locked_until': datetime until which the account is locked (if applicable)
login_attempts = {}

# Settings for brute-force protections
MAX_ATTEMPTS = 5          # Maximum allowed failed attempts
LOCKOUT_DURATION = 300    # Lockout period in seconds (e.g., 5 minutes)

@login_manager.user_loader
def load_user(user_id):
    # Since our user "database" is keyed by username, iterate to find by id.
    for user in users.values():
        if user.id == user_id:
            return user
    return None

def task_func(secret_key, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    app.secret_key = secret_key

    # Initialize LoginManager with this app
    login_manager.init_app(app)
    login_manager.login_view = 'login'

    # Define basic inline templates for demonstration.
    base_template = """
    <!doctype html>
    <html>
      <head>
        <title>{{ title }}</title>
      </head>
      <body>
        {% with messages = get_flashed_messages(with_categories=true) %}
          {% if messages %}
            <ul style="color: red;">
              {% for category, message in messages %}
                <li>{{ message }}</li>
              {% endfor %}
            </ul>
          {% endif %}
        {% endwith %}
        {% block content %}{% endblock %}
      </body>
    </html>
    """

    login_template = """
    {% extends "base.html" %}
    {% block content %}
      <h2>Login</h2>
      <form method="POST" action="{{ url_for('login') }}">
          {{ form.hidden_tag() }}
          <p>
              {{ form.username.label }}<br>
              {{ form.username(size=32) }}
          </p>
          <p>
              {{ form.password.label }}<br>
              {{ form.password(size=32) }}
          </p>
          <p>{{ form.submit() }}</p>
      </form>
    {% endblock %}
    """

    protected_template = """
    {% extends "base.html" %}
    {% block content %}
      <h2>Protected Page</h2>
      <p>Hello, {{ current_user.username }}! You have successfully logged in.</p>
      <p><a href="{{ url_for('logout') }}">Logout</a></p>
    {% endblock %}
    """

    # If a user accesses a non-existent template file, use render_template_string on our inline templates.
    # Preload the inline base template
    app.jinja_loader.mapping = {
        "base.html": base_template,
        "login.html": login_template,
        "protected.html": protected_template,
    }

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        form = LoginForm()
        # If already logged in, redirect to protected page
        if current_user.is_authenticated:
            return redirect(url_for('protected'))
        if form.validate_on_submit():
            username = form.username.data.strip()
            password = form.password.data.strip()

            now = datetime.now()
            # Initialize tracking for the username if not exists
            attempts_data = login_attempts.get(username, {"attempts": 0, "locked_until": None})
            locked_until = attempts_data.get("locked_until")
            # Check if account is currently locked out
            if locked_until and now < locked_until:
                wait_time = int((locked_until - now).total_seconds())
                flash(f"Account locked due to multiple failed attempts. Please try again in {wait_time} seconds.", "error")
                return render_template_string(login_template, form=form, title="Login")

            user = users.get(username)
            # If user does not exist or password check fails, increment the attempt count.
            if not user or not check_password_hash(user.password_hash, password):
                # Update login attempts
                attempts_data["attempts"] = attempts_data.get("attempts", 0) + 1
                attempts_data["last_attempt"] = now
                # If failed attempts exceed threshold, lock account for defined duration
                if attempts_data["attempts"] >= MAX_ATTEMPTS:
                    attempts_data["locked_until"] = now + timedelta(seconds=LOCKOUT_DURATION)
                    flash("Too many failed login attempts. Account locked. Please try again later.", "error")
                else:
                    remaining = MAX_ATTEMPTS - attempts_data["attempts"]
                    flash(f"Invalid username or password. {remaining} attempt(s) remaining before lockout.", "error")
                login_attempts[username] = attempts_data
                return render_template_string(login_template, form=form, title="Login")
            else:
                # Successful login: reset the failed attempts record.
                if username in login_attempts:
                    del login_attempts[username]
                login_user(user)
                flash("Logged in successfully.", "info")
                return redirect(url_for('protected'))
        return render_template_string(login_template, form=form, title="Login")

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        flash("You have been logged out.", "info")
        return redirect(url_for('login'))

    @app.route('/protected')
    @login_required
    def protected():
        return render_template_string(protected_template, title="Protected Page")

    return app

# For testing the Flask application directly.
if __name__ == '__main__':
    # Dynamically set secret key and template folder path.
    app = task_func(secret_key='ThisIsASecretKeyForEncryption', template_folder='templates')
    app.run(debug=True)

