import random
import pandas as pd
import collections

# Constants
VEGETABLES = ['Carrot', 'Potato', 'Tomato', 'Cabbage', 'Spinach']

def task_func(vegetable_dict, seed=0):
    # Set the seed to ensure reproducibility.
    random.seed(seed)

    # Handle the case of an empty input dictionary.
    if not vegetable_dict:
        return pd.DataFrame(columns=['Vegetable', 'Count', 'Percentage'])

    # Reverse the dictionary so that vegetables are keys and persons are values.
    # In case multiple persons share the same vegetable preference, we simply pick the first one.
    reversed_dict = {}
    for person, veg in vegetable_dict.items():
        if veg not in reversed_dict:
            reversed_dict[veg] = person

    # For the vegetables that actually appear in the input dictionary,
    # assign a random count between 1 and 10. This simulates varying popularity or availability.
    veg_counts = {}
    for veg in reversed_dict.keys():
        veg_counts[veg] = random.randint(1, 10)

    # Calculate the total count to be used for percentage calculations.
    total_count = sum(veg_counts.values())

    # Compute the percentage occurrence for each vegetable.
    veg_percentage = {}
    for veg, count in veg_counts.items():
        veg_percentage[veg] = (count / total_count * 100) if total_count > 0 else 0

    # Create a DataFrame, ensuring rows correspond to individual vegetables and columns reflect
    # the vegetable name, its random count, and its percentage occurrence.
    data = {
        'Vegetable': list(veg_counts.keys()),
        'Count': [veg_counts[veg] for veg in veg_counts],
        'Percentage': [veg_percentage[veg] for veg in veg_counts]
    }

    df_result = pd.DataFrame(data)
    return df_result

# Example usage:
if __name__ == '__main__':
    # Test input: dictionary mapping persons to their preferred vegetables.
    test_dict = {
        'Alice': 'Carrot',
        'Bob': 'Tomato',
        'Charlie': 'Spinach',
        'Diana': 'Carrot',
        'Evan': 'Potato'
    }

    result = task_func(test_dict, seed=42)
    print(result)

