import re
import socket

def task_func(ip_addresses: list) -> dict:
    # Regular expression to validate an IPv4 address
    ip_regex = re.compile(
        r'^((25[0-5]|2[0-4]\d|[0-1]?\d?\d)\.){3}(25[0-5]|2[0-4]\d|[0-1]?\d?\d)$'
    )

    result = {}

    for ip in ip_addresses:
        # Validate the IP address
        if not ip_regex.fullmatch(ip):
            continue  # Skip invalid IP addresses

        # Attempt to resolve the hostname from the IP address
        try:
            hostname, _, _ = socket.gethostbyaddr(ip)
        except (socket.herror, socket.gaierror):
            hostname = None

        result[ip] = hostname

    return result

# Example usage:
if __name__ == '__main__':
    test_ips = [
        "8.8.8.8",       # valid (Google DNS)
        "256.256.256.256", # invalid IP
        "127.0.0.1",     # local host
        "192.0.2.1"      # reserved for documentation; typically may not resolve
    ]
    resolved = task_func(test_ips)
    for ip, hostname in resolved.items():
        print(f"{ip}: {hostname}")

