import re
import requests

def task_func(input):
    # Step 1: Sanitize the input by removing characters that are not alphanumeric, whitespace,
    # or commonly found in URLs. This helps reduce the risk of injection attacks.
    safe_input = re.sub(r'[^\w\s:/\.\-?&=%]', '', input)

    # Step 2: Extract the API endpoint from the sanitized input.
    # The regex below looks for common URL patterns (starting with http:// or https://).
    url_match = re.search(r'(https?://[^\s]+)', safe_input)
    if not url_match:
        return {"error": "No valid URL found in input."}
    endpoint = url_match.group(1)

    # Optional: Further validate the extracted endpoint (here checking if it properly starts with http or https).
    if not endpoint.startswith(("http://", "https://")):
        return {"error": "Extracted URL does not have a valid scheme."}

    # Step 3: Send a GET request using the requests library.
    try:
        response = requests.get(endpoint)
    except Exception as e:
        return {"error": f"An error occurred while making the request: {str(e)}"}

    # Step 4: Check if the response status code is 200 (OK).
    if response.status_code != 200:
        return {"error": f"Request failed with status code {response.status_code}.", 
                "status_code": response.status_code}

    # Step 5: Try to parse the response data as JSON. If unsuccessful, package the raw text into a JSON-friendly dict.
    try:
        data = response.json()
    except ValueError:
        data = {"text": response.text}

    return data

# Example testing (if needed, remove or comment out when deploying):
if __name__ == "__main__":
    # provide an input string containing an API endpoint
    sample_input = "Please use the following endpoint: https://jsonplaceholder.typicode.com/todos/1 for testing."
    result = task_func(sample_input)
    print("dict:", result)

