import requests
import os
import zipfile

def task_func(url, destination_directory, headers=None):
    # Ensure that the provided URL is secure (HTTPS)
    if not url.startswith("https://"):
        return "Error: Insecure URL provided. Please use a secure HTTPS URL."

    # Ensure the destination directory exists; if not, create it.
    if not os.path.exists(destination_directory):
        try:
            os.makedirs(destination_directory)
        except Exception as e:
            return f"Error: Failed to create destination directory. {str(e)}"

    # Define the local filename for the downloaded zip file.
    zip_filename = os.path.join(destination_directory, "downloaded_archive.zip")

    # Attempt to download the zip file from the URL.
    try:
        response = requests.get(url, headers=headers, stream=True)
    except requests.exceptions.RequestException as e:
        return f"Error: Failed to make a request. {str(e)}"

    # Check if the download was successful.
    if response.status_code != 200:
        return f"Error: Download failed with status code {response.status_code}"

    # Write the response content to a local file.
    try:
        with open(zip_filename, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:  # filter out keep-alive new chunks
                    f.write(chunk)
    except Exception as e:
        return f"Error: Failed to save the downloaded file. {str(e)}"

    # Extract the downloaded zip file.
    extracted_files = []
    try:
        with zipfile.ZipFile(zip_filename, 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
            extracted_files = zip_ref.namelist()
    except zipfile.BadZipFile as e:
        return f"Error: The downloaded file is not a valid zip file. {str(e)}"
    except Exception as e:
        return f"Error: Failed to extract zip file. {str(e)}"

    return extracted_files

# Example usage:
if __name__ == '__main__':
    # A sample secure url (replace with an actual zip URL for testing)
    test_url = "https://example.com/sample.zip"
    dest_dir = "extracted_files"

    result = task_func(test_url, dest_dir)
    print(result)

