import re
from collections import Counter

def task_func(sentence):
    # If the sentence is empty, return an empty dictionary
    if not sentence:
        return {}

    # Use a regular expression to extract alphanumeric words
    words = re.findall(r'\b\w+\b', sentence)

    # Count the occurrences of each word using Counter
    word_counts = Counter(words)

    # Return the result as a regular dictionary
    return dict(word_counts)

# Example usage:
if __name__ == "__main__":
    test_sentence = "Hello, world! Hello... zee world? 123-456 123"
    print(task_func(test_sentence))
    # Expected output (actual counts depending on the extraction):
    # {'Hello': 2, 'world': 2, 'zee': 1, '123': 2, '456': 1}

