import collections
import json
import os

def task_func(directory_path: str) -> dict:
    # Check if the directory exists and is indeed a directory.
    if not os.path.isdir(directory_path):
        raise FileNotFoundError(f"Directory not found: {directory_path}")

    # Helper function to recursively count keys in nested JSON objects.
    def count_keys_in_obj(obj):
        counter = collections.Counter()
        if isinstance(obj, dict):
            for key, value in obj.items():
                counter[key] += 1  # count this key occurrence
                counter.update(count_keys_in_obj(value))  # count keys in the value recursively
        elif isinstance(obj, list):
            for item in obj:
                counter.update(count_keys_in_obj(item))
        # Other types (e.g., int, str, None) are ignored.
        return counter

    # Initialize a counter for all keys.
    total_key_counts = collections.Counter()

    # Iterate over all files in the directory.
    for filename in os.listdir(directory_path):
        # Process only files with a '.json' extension.
        if filename.lower().endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            # Ensure it's a file before processing
            if os.path.isfile(file_path):
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                except json.JSONDecodeError:
                    # If a JSON file is malformed, return an empty dictionary.
                    return {}
                except Exception:
                    # For any other exceptions related to reading the file, re-raise.
                    raise

                # Count keys in the loaded JSON object.
                total_key_counts.update(count_keys_in_obj(data))

    # Return the counts as a standard dictionary.
    return dict(total_key_counts)

