import subprocess
import os
import signal
import time
import re

def task_func(process_name: str) -> int:
    # Validate the process name to prevent command injection.
    # Only allow alphanumeric characters, underscores, dashes, or dots.
    if not process_name or not re.fullmatch(r"[a-zA-Z0-9_.-]+", process_name):
        raise ValueError("Invalid process name provided.")

    # Use 'pgrep' with the '-x' flag to match the exact process name.
    try:
        output = subprocess.check_output(
            ["pgrep", "-x", process_name],
            stderr=subprocess.DEVNULL  # suppress error output if no process found
        )
        # The output is a set of newline separated PIDs.
        pids = [int(pid) for pid in output.decode().split()]
    except subprocess.CalledProcessError:
        # pgrep returns a non-zero exit code if no process is found.
        return 0

    # Send termination signals to each process.
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            # The process might have already terminated.
            pass
        except Exception as e:
            # You could log or handle any other exceptions here if needed.
            pass

    # Wait for 1 second.
    time.sleep(1)

    # Return the number of processes that received the termination signal.
    return len(pids)


# Example usage:
if __name__ == "__main__":
    try:
        stopped_count = task_func("example_process")  # Replace with the actual process name.
        print(f"Stopped {stopped_count} process(es).")
    except ValueError as e:
        print(f"Error: {e}")

