from multiprocessing import Pool
import math

def calculate_factorial(number: int) -> tuple:
    """Calculate the factorial of a given number and return a tuple (number, factorial)."""
    return number, math.factorial(number)

def task_func(numbers: list) -> dict:
    """
    Calculate factorials for a list of numbers in parallel.

    Validates that each element in the list is a non-negative integer.
    Raises ValueError if any element is not a valid non-negative integer.

    Returns:
        A dictionary with each number as the key and its factorial as the value.
        If the input list is empty, returns an empty dictionary.
    """
    # If the input list is empty, return an empty dictionary
    if not numbers:
        return {}

    # Validate each number: ensure it's an integer and non-negative
    for num in numbers:
        if not isinstance(num, int) or num < 0:
            raise ValueError("All elements in the input list must be non-negative integers.")

    # Use multiprocessing to calculate factorials in parallel
    with Pool() as pool:
        results = pool.map(calculate_factorial, numbers)

    # Convert the list of tuples into a dictionary and return it
    return dict(results)

# Example usage:
if __name__ == '__main__':
    # Define a list of numbers to compute factorials for.
    numbers = [5, 10, 15]
    try:
        result = task_func(numbers)
        print("Factorial results:", result)
    except ValueError as e:
        print("Input validation error:", e)

