Below is one possible solution that uses Django REST Framework, JWT authentication, and the official Elasticsearch Python client. In this example we assume that your signals and status messages have been indexed using mappings that match the fields referenced (for example, a created_at date field, a state field, and an active boolean). We also assume that (1) a SignalDocument “model” exists that knows how to serialize/deserialize the ES documents for signals, and (2) a StatusMessagesSearch “model” (or helper) exists for status messages. The solution uses two API views:

• SearchSignalsView – performs a fuzzy search on signals, sorts the result by created_at, supports pagination, and handles ES “service unavailable” errors.
• SearchStatusMessagesView – performs a fuzzy search on status messages with additional filtering (by state and active), supports pagination, and handles errors.

The following code snippet shows one complete design implementation:

────────────────────────────────────────────
# views.py

import logging
from elasticsearch import Elasticsearch, ElasticsearchException
from elasticsearch.exceptions import ConnectionError as ESConnectionError
from rest_framework import status
from rest_framework.response import Response
from rest_framework.views import APIView
from rest_framework.permissions import IsAuthenticated
from rest_framework.pagination import PageNumberPagination
from rest_framework_jwt.authentication import JSONWebTokenAuthentication

# Assume these are your document “serializers” that know how to serialize the ES hit (_source).
# In a real project, you might use a library such as django-elasticsearch-dsl or write your own classes.
from .documents import SignalDocument, StatusMessagesSearch

# Logger setup
logger = logging.getLogger(__name__)

# Create an instance of the Elasticsearch client. In production, you might want to do this in a centralized place.
es_client = Elasticsearch(hosts=["http://localhost:9200"])

# Optional: A common pagination class.
class StandardResultsSetPagination(PageNumberPagination):
    page_size = 10
    page_size_query_param = "limit"
    max_page_size = 100


class SearchSignalsView(APIView):
    """
    API endpoint that allows users to search for signals.
    The view uses fuzzy searching, sorts by created_at and supports pagination.
    """
    authentication_classes = [JSONWebTokenAuthentication]
    permission_classes = [IsAuthenticated]
    pagination_class = StandardResultsSetPagination()

    def get(self, request):
        # Validate and sanitize the input to prevent injection. Here we only accept a search_term string.
        search_term = request.query_params.get("search_term", "").strip()
        page = request.query_params.get("page", 1)
        sort_order = request.query_params.get("sort_order", "desc")

        if not search_term:
            return Response({"error": "search_term parameter is required."}, status=status.HTTP_400_BAD_REQUEST)

        # Build the elasticsearch query for signals.
        # We use a fuzzy match query across a few example fields.
        query = {
            "bool": {
                "must": [
                    {
                        "multi_match": {
                            "query": search_term,
                            "fuzziness": "AUTO",
                            "fields": ["title", "description"]  # adjust depending on your mapping
                        }
                    }
                ]
            }
        }

        # Build sort clause.
        sort_clause = [{"created_at": {"order": sort_order}}]

        # Define pagination parameters
        try:
            page = int(page)
        except ValueError:
            page = 1

        limit = int(request.query_params.get("limit", self.pagination_class.page_size))
        start = (page - 1) * limit

        try:
            response = es_client.search(
                index="signals-index",  # adjust index name accordingly
                body={
                    "query": query,
                    "sort": sort_clause,
                    "from": start,
                    "size": limit,
                },
            )
        except ESConnectionError:
            logger.error("Elasticsearch service unavailable for signals search.")
            return Response({"error": "Search service unavailable."},
                            status=status.HTTP_503_SERVICE_UNAVAILABLE)
        except ElasticsearchException as e:
            logger.error("Elasticsearch exception: %s", str(e))
            return Response({"error": "An error occurred during searching signals."},
                            status=status.HTTP_500_INTERNAL_SERVER_ERROR)

        # Process the hits. Assume SignalDocument has a from_es_hit method.
        hits = response.get("hits", {}).get("hits", [])
        results = [SignalDocument.from_es_hit(hit) for hit in hits]

        # Optionally include the total count in the paginated response.
        total = response.get("hits", {}).get("total", {}).get("value", 0)

        return Response({"results": results, "total": total})


class SearchStatusMessagesView(APIView):
    """
    API endpoint that allows users to search for status messages.
    The view supports fuzzy search by search term, filtering by state and active,
    and supports pagination.
    """
    authentication_classes = [JSONWebTokenAuthentication]
    permission_classes = [IsAuthenticated]
    pagination_class = StandardResultsSetPagination()

    def get(self, request):
        search_term = request.query_params.get("search_term", "").strip()
        # Get additional filters.
        state_filter = request.query_params.get("state", None)
        active_filter = request.query_params.get("active", None)
        page = request.query_params.get("page", 1)

        # Validate search_term if needed; in this example it is optional.
        if not search_term:
            return Response({"error": "search_term parameter is required."},
                            status=status.HTTP_400_BAD_REQUEST)

        try:
            page = int(page)
        except ValueError:
            page = 1

        limit = int(request.query_params.get("limit", self.pagination_class.page_size))
        start = (page - 1) * limit

        # Build the elasticsearch query with filtering.
        query_filters = []
        if state_filter:
            query_filters.append({"term": {"state": state_filter}})
        if active_filter is not None:
            # Convert active_filter to boolean.
            if active_filter.lower() in ("true", "1"):
                active_filters_bool = True
            elif active_filter.lower() in ("false", "0"):
                active_filters_bool = False
            else:
                return Response({"error": "Invalid active filter value."},
                                status=status.HTTP_400_BAD_REQUEST)
            query_filters.append({"term": {"active": active_filters_bool}})

        # Fuzzy match on search_term in one or more fields.
        fuzzy_query = {
            "multi_match": {
                "query": search_term,
                "fuzziness": "AUTO",
                "fields": ["message", "description"]  # adjust fields according to your mapping
            }
        }

        query = {
            "bool": {
                "must": [fuzzy_query],
                "filter": query_filters
            }
        }

        try:
            response = es_client.search(
                index="status-messages-index",  # adjust index name accordingly
                body={
                    "query": query,
                    "from": start,
                    "size": limit,
                },
            )
        except ESConnectionError:
            logger.error("Elasticsearch service unavailable for status messages search.")
            return Response({"error": "Search service unavailable."},
                            status=status.HTTP_503_SERVICE_UNAVAILABLE)
        except ElasticsearchException as e:
            logger.error("Elasticsearch exception: %s", str(e))
            return Response({"error": "An error occurred during searching status messages."},
                            status=status.HTTP_500_INTERNAL_SERVER_ERROR)

        hits = response.get("hits", {}).get("hits", [])
        # Assume StatusMessagesSearch has a helper for converting hits.
        results = [StatusMessagesSearch.from_es_hit(hit) for hit in hits]
        total = response.get("hits", {}).get("total", {}).get("value", 0)

        return Response({"results": results, "total": total})

