# These helper classes illustrate how you might transform an Elasticsearch hit into a Python dictionary.
# In production you might use proper serializers to validate the data.

class SignalDocument:
    @classmethod
    def from_es_hit(cls, hit):
        src = hit.get("_source", {})
        # Optionally, format created_at and other fields.
        return {
            "id": hit.get("_id"),
            "title": src.get("title"),
            "description": src.get("description"),
            "created_at": src.get("created_at"),
            # add other fields as needed
        }


class StatusMessagesSearch:
    @classmethod
    def from_es_hit(cls, hit):
        src = hit.get("_source", {})
        return {
            "id": hit.get("_id"),
            "message": src.get("message"),
            "description": src.get("description"),
            "state": src.get("state"),
            "active": src.get("active"),
            # add other fields as needed
        }

