Below is one way to implement such a parser and evaluator in Python. In the example below we define a Runtime class that maintains dictionaries for variables and functions (both built‐in and user–defined). We also implement a simple recursive–descent parser for arithmetic expressions (supporting +, −, ×, ÷, parentheses, and function calls) plus special handling for assignment statements (e.g. “x = 3.5”) and function definitions (e.g. “f(x,y):x+y”). Errors like referencing undefined variables or functions are caught and displayed. (In a production implementation you might wish to use a more robust lexer/parser but this example shows one simple design.)

Below is the complete code:

------------------------------------------------
#!/usr/bin/env python3
import math
import sys

# ----------------------------------------------------------------
# AST node classes
# ----------------------------------------------------------------
class Number:
    def __init__(self, value):
        self.value = value

class Variable:
    def __init__(self, name):
        self.name = name

class BinaryOp:
    def __init__(self, left, op, right):
        self.left = left
        self.op = op   # '+', '-', '*', '/'
        self.right = right

class UnaryOp:
    def __init__(self, op, expr):
        self.op = op   # '+' or '-'
        self.expr = expr

class FuncCall:
    def __init__(self, name, args):
        self.name = name
        self.args = args  # list of AST nodes

# ----------------------------------------------------------------
# The Recursive Descent Parser
# ----------------------------------------------------------------
class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def error(self, msg):
        raise Exception("Parse error: " + msg)

    def advance(self):
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def parse_number(self):
        num_str = ""
        dot_count = 0
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char=='.'):
            if self.current_char == '.':
                dot_count += 1
                if dot_count > 1:
                    self.error("Invalid number format")
            num_str += self.current_char
            self.advance()
        return Number(float(num_str))

    def parse_identifier(self):
        ident = ""
        while self.current_char is not None and (self.current_char.isalnum() or self.current_char=="_"):
            ident += self.current_char
            self.advance()
        return ident

    # factor : ('+'|'-') factor | NUMBER | IDENTIFIER [ '(' expr (',' expr)* ')' ] | '(' expr ')'
    def parse_factor(self):
        self.skip_whitespace()
        char = self.current_char
        if char is None:
            self.error("Unexpected end of input")
        if char in '+-':
            op = char
            self.advance()
            node = self.parse_factor()
            return UnaryOp(op, node)
        elif char.isdigit() or char=='.':
            return self.parse_number()
        elif char.isalpha():
            ident = self.parse_identifier()
            self.skip_whitespace()
            # Check if it is a function call
            if self.current_char == '(':
                self.advance()  # skip '('
                args = []
                self.skip_whitespace()
                if self.current_char == ')':
                    self.advance()
                    return FuncCall(ident, args)
                while True:
                    arg = self.parse_expr()
                    args.append(arg)
                    self.skip_whitespace()
                    if self.current_char == ')':
                        self.advance()
                        break
                    elif self.current_char == ',':
                        self.advance()
                        self.skip_whitespace()
                    else:
                        self.error("Expected ',' or ')' in function arguments")
                return FuncCall(ident, args)
            else:
                return Variable(ident)
        elif char == '(':
            self.advance()
            node = self.parse_expr()
            self.skip_whitespace()
            if self.current_char != ')':
                self.error("Expected ')'")
            self.advance()
            return node
        else:
            self.error("Unexpected character: " + char)

    # term : factor (('*'|'/') factor)*
    def parse_term(self):
        node = self.parse_factor()
        while True:
            self.skip_whitespace()
            if self.current_char in ('*', '/'):
                op = self.current_char
                self.advance()
                right = self.parse_factor()
                node = BinaryOp(node, op, right)
            else:
                break
        return node

    # expr : term (('+'|'-') term)*
    def parse_expr(self):
        node = self.parse_term()
        while True:
            self.skip_whitespace()
            if self.current_char in ('+', '-'):
                op = self.current_char
                self.advance()
                right = self.parse_term()
                node = BinaryOp(node, op, right)
            else:
                break
        return node

    def parse(self):
        node = self.parse_expr()
        self.skip_whitespace()
        if self.current_char is not None:
            self.error("Unexpected character: " + self.current_char)
        return node

# ----------------------------------------------------------------
# User-defined function container
# ----------------------------------------------------------------
class UserFunction:
    def __init__(self, param_names, body_ast):
        self.param_names = param_names
        self.body_ast = body_ast

# ----------------------------------------------------------------
# The Runtime class: holds variables, functions, and the REPL
# ----------------------------------------------------------------
class Runtime:
    def __init__(self):
        self.vars = {}   # variable dictionary
        self.funcs = {}  # user-defined functions dictionary

        # Built-in functions from math module
        self.builtin_funcs = {
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'asin': math.asin,
            'acos': math.acos,
            'atan': math.atan,
        }

    # Evaluate an AST node in the given scope (a dict of variable values).
    def eval_ast(self, node, local_scope=None):
        if local_scope is None:
            local_scope = {}
        if isinstance(node, Number):
            return node.value
        elif isinstance(node, Variable):
            # first check local scope, then global vars
            name = node.name
            if name in local_scope:
                return local_scope[name]
            elif name in self.vars:
                return self.vars[name]
            else:
                raise Exception("Undefined variable: " + name)
        elif isinstance(node, UnaryOp):
            val = self.eval_ast(node.expr, local_scope)
            if node.op == '+':
                return +val
            elif node.op == '-':
                return -val
            else:
                raise Exception("Unknown unary operator: " + node.op)
        elif isinstance(node, BinaryOp):
            left = self.eval_ast(node.left, local_scope)
            right = self.eval_ast(node.right, local_scope)
            if node.op == '+':
                return left + right
            elif node.op == '-':
                return left - right
            elif node.op == '*':
                return left * right
            elif node.op == '/':
                if right == 0:
                    raise Exception("Division by zero")
                return left / right
            else:
                raise Exception("Unknown binary operator: " + node.op)
        elif isinstance(node, FuncCall):
            func_name = node.name
            # Evaluate argument expressions
            args = [self.eval_ast(arg, local_scope) for arg in node.args]
            # Check built-in functions first
            if func_name in self.builtin_funcs:
                try:
                    return self.builtin_funcs[func_name](*args)
                except Exception as e:
                    raise Exception("Error in built-in function {}: {}".format(func_name, e))
            # Then check user-defined functions
            elif func_name in self.funcs:
                func = self.funcs[func_name]
                if len(args) != len(func.param_names):
                    raise Exception("Function {} expects {} arguments, got {}".format(
                        func_name, len(func.param_names), len(args)))
                new_scope = dict(zip(func.param_names, args))
                # Evaluate function body AST in the new scope
                return self.eval_ast(func.body_ast, new_scope)
            else:
                raise Exception("Undefined function: " + func_name)
        else:
            raise Exception("Unknown AST node")

    # Process a full line of input. It can be:
    #   - a variable assignment: var = expression
    #   - a function definition: f(x,y): expression
    #   - otherwise, an expression to evaluate.
    def execute(self, line):
        line = line.strip()
        if not line:
            return None
        # exit command
        if line == "exit()":
            sys.exit(0)

        # List variables or functions
        if line == "vars":
            return "\n".join(f"{k} = {v}" for k, v in self.vars.items())
        if line == "funcs":
            funcs_list = list(self.funcs.keys()) + list(self.builtin_funcs.keys())
            return "\n".join(funcs_list)

        # Function definition: look for pattern: identifier(params): body
        if ':' in line:
            # We decide that if there is a colon and a "(" in the header before colon,
            # treat as a function definition.
            parts = line.split(':', 1)
            header = parts[0].strip()
            body_str = parts[1].strip()
            if '(' in header and header.endswith(')'):
                # extract function name and parameter list
                func_name, params = header.split('(', 1)
                func_name = func_name.strip()
                params = params[:-1]  # remove closing )
                param_names = [p.strip() for p in params.split(',') if p.strip()]
                try:
                    parser = Parser(body_str)
                    body_ast = parser.parse()
                except Exception as e:
                    return "Error in function body: " + str(e)
                self.funcs[func_name] = UserFunction(param_names, body_ast)
                return "Function {} defined with parameters {}".format(func_name, param_names)
            else:
                # Otherwise treat as: var: expr  (could be used in a different DSL)
                return "Invalid function definition syntax."
        # Variable assignment: look for '=' character, but not inside an expression.
        # For simplicity we use split on '=', but only if there's exactly one '='.
        if '=' in line:
            parts = line.split('=', 1)
            var_name = parts[0].strip()
            expr_str = parts[1].strip()

            # Disallow assignment to something that is not a valid identifier:
            if not var_name.isidentifier():
                return "Invalid variable name: " + var_name
            try:
                parser = Parser(expr_str)
                ast = parser.parse()
                value = self.eval_ast(ast)
            except Exception as e:
                return "Error evaluating assignment: " + str(e)
            self.vars[var_name] = value
            return "{} = {}".format(var_name, value)
        else:
            # Evaluate the expression
            try:
                parser = Parser(line)
                ast = parser.parse()
                result = self.eval_ast(ast)
                return result
            except Exception as e:
                return "Error: " + str(e)

    # Start the interactive shell
    def repl(self):
        print("Welcome to the math expression REPL. Type 'exit()' to exit.")
        while True:
            try:
                line = input(">>> ")
                output = self.execute(line)
                if output is not None:
                    print(output)
            except Exception as e:
                print("Unexpected error:", e)

# ----------------------------------------------------------------
# When run directly, start the interactive shell.
# ----------------------------------------------------------------
if __name__ == '__main__':
    runtime = Runtime()
    runtime.repl()

------------------------------------------------

Explanation of main parts:

1. The Parser class 
   • Implements a recursive descent parser. The parse_expr() method handles addition and subtraction while parse_term() handles multiplication/division.
   • The parse_factor() method recognizes numbers, variables, parenthesized expressions, unary operators and function calls.

2. The AST node classes (Number, Variable, BinaryOp, UnaryOp, FuncCall) represent the different types of nodes in our expression language.

3. The Runtime class:
   • Stores variables (in self.vars) and user-defined functions (in self.funcs). It also defines some built–in functions in self.builtin_funcs.
   • The eval_ast() method recursively evaluates an AST node.
   • The execute() method distinguishes among assignments, function definitions, and expressions. For example:
     – For an assignment like "x = 3.5" it will parse and evaluate the right–hand side and then assign it to x.
     – For a function definition like "f(x,y):x+y", it will parse the function body and store the function for later calls.
     – If the line is an expression (possibly with function calls, e.g. "sin(x) + 2"), it will be parsed and then evaluated.
   • The repl() method provides an interactive shell. Typing "vars" lists variables, "funcs" lists built–in and user–defined functions, and "exit()" quits.

4. Error handling is done with try/except blocks. When undefined variables or functions are encountered, or when syntax errors occur, an error message is printed instead of crashing.

You can run this script and test commands like:
  • x = 3.5
  • y = 4
  • f(a,b):a*b + sin(a)
  • f(x,y)
  • vars
  • funcs
  • exit()

This implementation meets the requirements for a simple mathematical expression parser and evaluator with variable assignments, function definitions (both built–in and user–defined), basic arithmetic, parentheses handling, and error handling.

