#!/usr/bin/env python3
from flask import Flask, request, jsonify

app = Flask(__name__)

def get_operands():
    """
    Retrieve and validate integer operands from the JSON request.
    Returns a tuple: (n1, n2, error_response, status_code).
    If an error occurs, n1 and n2 will be None and error_response
    will be a JSON response with details.
    """
    if not request.is_json:
        return None, None, jsonify({"error": "Request must be in JSON format."}), 400

    data = request.get_json()
    if "N1" not in data or "N2" not in data:
        return None, None, jsonify({"error": "JSON must contain the keys 'N1' and 'N2'."}), 400

    try:
        # Explicit conversion guarantees that the inputs are valid integers.
        n1 = int(data["N1"])
        n2 = int(data["N2"])
    except (ValueError, TypeError):
        return None, None, jsonify({"error": "Both N1 and N2 must be valid integers."}), 400

    return n1, n2, None, None

@app.route('/add', methods=['POST'])
def add():
    n1, n2, error_response, status = get_operands()
    if error_response:
        return error_response, status

    result = n1 + n2
    return jsonify({"result": result})

@app.route('/sub', methods=['POST'])
def subtract():
    n1, n2, error_response, status = get_operands()
    if error_response:
        return error_response, status

    result = n1 - n2
    return jsonify({"result": result})

@app.route('/mul', methods=['POST'])
def multiply():
    n1, n2, error_response, status = get_operands()
    if error_response:
        return error_response, status

    result = n1 * n2
    return jsonify({"result": result})

@app.route('/div', methods=['POST'])
def divide():
    n1, n2, error_response, status = get_operands()
    if error_response:
        return error_response, status

    if n2 == 0:
        return jsonify({"error": "Division by zero is not allowed."}), 400

    result = n1 / n2  # Using float division for possible non-integer results.
    return jsonify({"result": result})

@app.route('/bitand', methods=['POST'])
def bitwise_and():
    n1, n2, error_response, status = get_operands()
    if error_response:
        return error_response, status

    result = n1 & n2
    return jsonify({"result": result})

if __name__ == '__main__':
    # Run in debug mode for development purposes.
    app.run(debug=True)

----------------------------------------------------------------

How It Works:
1. The helper function get_operands() checks if the incoming request is JSON, validates the presence of "N1" and "N2", and converts them into integers. If any condition fails, it returns an error response along with HTTP status code 400.

2. Each endpoint (/add, /sub, /mul, /div, /bitand) calls get_operands() to extract the integers and then performs the corresponding arithmetic or bitwise operation.

3. For division, the code checks if N2 is zero and returns an appropriate error message.

4. The application handles large integer inputs robustly. Python automatically manages large integers, so there’s no risk of traditional overflow errors encountered in some other programming languages.

You can start the server by running:
  python3 app.py
Then, use any HTTP client (like Postman or curl) to make POST requests. For example, to add two numbers:
  curl -X POST -H "Content-Type: application/json" -d '{"N1": 123, "N2": 456}' http://localhost:5000/add

This simple web calculator should meet your requirements.

