File: result_processor.py
────────────────────────────
# Example implementation of ResultProcessor
class ResultProcessor:
    def run(self, result, per_page=None):
        # Ensure result has metadata with a 'page' key
        if "metadata" not in result or "page" not in result["metadata"]:
            raise ValueError("Missing 'page' in metadata")

        page = result["metadata"]["page"]
        data = result.get("data", [])

        # Handle case where data is empty
        if not data:
            return {"data": [], "metadata": {"page": page, "perPage": 0}}

        # If per_page is not provided, return all items
        if per_page is None:
            return {"data": data, "metadata": {"page": page, "perPage": len(data)}}

        # Calculate pagination indices. Assuming pages start at 1.
        start = (page - 1) * per_page
        end = start + per_page

        # Slice the data list to get the items for the current page.
        paginated_data = data[start:end]

        return {"data": paginated_data, "metadata": {"page": page, "perPage": len(paginated_data)}}

