File: test_result_processor.py
────────────────────────────
import pytest
from result_processor import ResultProcessor

# Define a fixture that returns a common result dictionary.
@pytest.fixture
def base_result():
    # A sample dataset with 10 items.
    return {
        "data": list(range(1, 11)),  # Items 1 through 10
        "metadata": {"page": 1}
    }

# Test when metadata is missing the 'page' key.
def test_missing_page_key():
    result_without_page = {
        "data": [1, 2, 3],
        "metadata": {}  # 'page' missing here
    }
    processor = ResultProcessor()
    with pytest.raises(ValueError, match="Missing 'page' in metadata"):
        processor.run(result_without_page)

# Test when the data list is empty
def test_empty_data():
    result_empty = {
        "data": [],
        "metadata": {"page": 1}
    }
    processor = ResultProcessor()
    output = processor.run(result_empty, per_page=5)
    assert output == {"data": [], "metadata": {"page": 1, "perPage": 0}}

# Test when per_page is not provided (should return all data)
def test_no_per_page_parameter(base_result):
    processor = ResultProcessor()
    output = processor.run(base_result)
    # Since no per_page, it should return all 10 items.
    assert output["data"] == list(range(1, 11))
    assert output["metadata"] == {"page": 1, "perPage": 10}

# Parametrized tests with different page numbers and per_page values.
@pytest.mark.parametrize("data, page, per_page, expected", [
    # Single page only (page 1, per page greater than total)
    (list(range(1, 6)), 1, 10, list(range(1, 6))),
    # First page of multiple pages
    (list(range(1, 11)), 1, 3, [1, 2, 3]),
    # Middle page
    (list(range(1, 11)), 2, 3, [4, 5, 6]),
    # Last page, not filling complete per_page count
    (list(range(1, 11)), 4, 3, [10]),
    # Page number exceeds available data, should return empty list.
    (list(range(1, 11)), 5, 3, []),
])
def test_pagination(data, page, per_page, expected):
    result = {
        "data": data,
        "metadata": {"page": page}
    }
    processor = ResultProcessor()
    output = processor.run(result, per_page=per_page)
    assert output["data"] == expected
    assert output["metadata"]["page"] == page
    assert output["metadata"]["perPage"] == len(expected)

# Additional test: when per_page exactly divides the total items.
def test_exact_division():
    data = list(range(1, 9))  # 8 items.
    result = {"data": data, "metadata": {"page": 2}}  # Request second page.
    processor = ResultProcessor()
    output = processor.run(result, per_page=4)
    # Second page should return items 5 to 8.
    assert output["data"] == [5, 6, 7, 8]
    assert output["metadata"] == {"page": 2, "perPage": 4}

