#!/usr/bin/env python3
"""
This module contains a QueueDelta class to compare two lists of queue objects
and an OnAgentUpdatedManager class that uses these differences to invoke action handlers.
"""

from dataclasses import dataclass
from typing import Any, Callable, List, Dict


@dataclass
class DeltaResult:
    added: List[Dict[str, Any]]
    removed: List[Dict[str, Any]]
    penalty_updated: List[Dict[str, Any]]


class QueueDelta:
    @staticmethod
    def calculate(old_queues: List[Any], new_queues: List[Any]) -> DeltaResult:
        # Validate that both inputs are lists
        if not isinstance(old_queues, list) or not isinstance(new_queues, list):
            raise ValueError("Both old_queues and new_queues must be lists.")

        # For performance, build lookup dictionaries using the queue ID (assumed to be unique)
        # We expect each queue object to be a dictionary with at least "id" and "penalty" keys.
        old_lookup = {}
        for queue in old_queues:
            if not isinstance(queue, dict):
                raise ValueError("Queue objects must be dictionaries.")
            if "id" not in queue or "penalty" not in queue:
                raise ValueError("Each queue must have an 'id' and a 'penalty' key.")
            old_lookup[queue["id"]] = queue

        new_lookup = {}
        for queue in new_queues:
            if not isinstance(queue, dict):
                raise ValueError("Queue objects must be dictionaries.")
            if "id" not in queue or "penalty" not in queue:
                raise ValueError("Each queue must have an 'id' and a 'penalty' key.")
            new_lookup[queue["id"]] = queue

        added = []
        penalty_updated = []
        # Check new queues for added and penalty updates
        for qid, new_q in new_lookup.items():
            if qid not in old_lookup:
                added.append(new_q)
            else:
                # If the penalty value has changed
                old_q = old_lookup[qid]
                if new_q["penalty"] != old_q["penalty"]:
                    penalty_updated.append(new_q)

        removed = []
        # Check old queues for removal
        for qid, old_q in old_lookup.items():
            if qid not in new_lookup:
                removed.append(old_q)

        return DeltaResult(added=added, removed=removed, penalty_updated=penalty_updated)


class OnAgentUpdatedManager:
    def __init__(self,
                 add_to_queue_action: Callable[[Any, Any], None],
                 remove_from_queue_action: Callable[[Any, Any], None],
                 update_penalty_action: Callable[[Any, Any], None]) -> None:
        """
        Initialize using the provided action handlers.
        Each action handler takes (agent, queue) as arguments.
        """
        self.add_to_queue_action = add_to_queue_action
        self.remove_from_queue_action = remove_from_queue_action
        self.update_penalty_action = update_penalty_action

    def on_agent_updated(self, agent: Any) -> None:
        """
        Validate the agent object and then process updated queue associations.
        We expect the agent object to have:
          - "id": a unique identifier,
          - "old_queues": a list of queue objects (each a dict with "id" and "penalty"),
          - "new_queues": a list of queue objects.
        """
        # Validate agent; raise errors if required attributes are missing.
        if not isinstance(agent, dict):
            raise ValueError("Agent must be provided as a dictionary.")
        if "id" not in agent:
            raise ValueError("Agent must have an 'id' attribute.")
        if "old_queues" not in agent or "new_queues" not in agent:
            raise ValueError("Agent must contain 'old_queues' and 'new_queues' attributes.")

        old_queues = agent["old_queues"]
        new_queues = agent["new_queues"]

        # Calculate queue deltas
        delta = QueueDelta.calculate(old_queues, new_queues)

        # Process each type of delta using corresponding action handlers.
        for queue in delta.added:
            self.add_to_queue_action(agent, queue)
        for queue in delta.removed:
            self.remove_from_queue_action(agent, queue)
        for queue in delta.penalty_updated:
            self.update_penalty_action(agent, queue)


# The following are mock implementations of the action handlers.

def add_to_queue_action(agent: Any, queue: Any) -> None:
    print(f"[ADD] Agent {agent['id']} added to queue {queue['id']} (penalty: {queue['penalty']}).")

def remove_from_queue_action(agent: Any, queue: Any) -> None:
    print(f"[REMOVE] Agent {agent['id']} removed from queue {queue['id']}.")

def update_penalty_action(agent: Any, queue: Any) -> None:
    print(f"[UPDATE] Agent {agent['id']} has updated penalty in queue {queue['id']} to {queue['penalty']}.")


# Simple tests to verify behavior.
if __name__ == '__main__':
    # Example agent data with old and new queues.
    agent = {
        "id": "agent123",
        "old_queues": [
            {"id": "q1", "penalty": 10},
            {"id": "q2", "penalty": 20},
            {"id": "q3", "penalty": 30}
        ],
        "new_queues": [
            {"id": "q1", "penalty": 10},      # unchanged
            {"id": "q2", "penalty": 25},      # penalty updated
            {"id": "q4", "penalty": 40}       # added
            # q3 removed
        ]
    }

    manager = OnAgentUpdatedManager(
        add_to_queue_action=add_to_queue_action,
        remove_from_queue_action=remove_from_queue_action,
        update_penalty_action=update_penalty_action
    )

    # Trigger the update which will print the corresponding actions.
    manager.on_agent_updated(agent)

    # Verify consistent behavior: running calculate again with the same inputs should yield the same results.
    first_result = QueueDelta.calculate(agent["old_queues"], agent["new_queues"])
    second_result = QueueDelta.calculate(agent["old_queues"], agent["new_queues"])
    assert first_result == second_result, "QueueDelta results are inconsistent across invocations."
    print("Consistency check passed.")

    # Additional error handling example:
    try:
        # This should raise an error because new_queues is not a list
        QueueDelta.calculate(agent["old_queues"], "not_a_list")
    except ValueError as e:
        print("Caught ValueError as expected:", e)

    try:
        # This should raise error because the agent object is missing required keys.
        manager.on_agent_updated({"id": "agent456", "old_queues": []})
    except ValueError as e:
        print("Caught ValueError for agent validation:", e)

------------------------------------------------------------

Explanation:

1. The QueueDelta.calculate method first verifies that the inputs are lists and that each queue object has the "id" and "penalty" keys. It then builds dictionaries (old_lookup and new_lookup) keyed by queue id for O(n) performance. It checks for queues that are added (present only in new), removed (present only in old) or have different penalty values.

2. The OnAgentUpdatedManager.on_agent_updated method validates the agent object (here assumed to be a dictionary with 'id', 'old_queues', and 'new_queues') and then calls QueueDelta.calculate to get the changes. It then calls the corresponding action handlers for each change (added, removed, penalty_updated).

3. The test cases at the bottom exercise the normal update flow as well as error conditions.

