                title
            }}
        }}
    ''', context_value={'user': user})
    assert 'errors' not in executed
    assert executed['data']['zipCityJobs'] is not None
    assert len(executed['data']['zipCityJobs']) == 1
    assert executed['data']['zipCityJobs'][0]['title'] == 'Test Job'
