        """
        Handles the success of a Weixin Pay payment.
        last_price: final price after discounts and other calculations.
        coupon_id: coupon used for the discount.
        """
        # You might update an order status, apply coupon discount etc.
        # Here we simply return a success message.
        return {'status': 'success', 'last_price': last_price, 'coupon_id': coupon_id, 'message': 'Payment successful.'}

    def weixin_pay_failure(self):
        """Handles the failure of a Weixin Pay payment."""
        return {'status': 'error', 'message': 'Payment failed. Please try again.'}

    def my_coffee_coupon(self, user_id):
        """
        Retrieves the coffee coupons for a user by their ID.
        """
        coupon_ids = self.user_coupons.get(user_id, [])
        coupons = [self.coupons[c_id] for c_id in coupon_ids if c_id in self.coupons]
        return {'status': 'success', 'user_id': user_id, 'data': coupons}

    def coupon(self, coupon_id):
        """Retrieves the details of a coupon by its ID."""
        coup = self.coupons.get(coupon_id)
        if coup:
            return {'status': 'success', 'data': coup}
        return {'status': 'error', 'message': f'Coupon with id {coupon_id} not found.'}

    def historical_order(self, user_id):
        """Retrieves the historical orders of a user by their ID."""
        order_ids = self.historical_orders.get(user_id, [])
        orders_list = [self.orders.get(o_id, {'order_id': o_id, 'info': 'Details not available.'}) for o_id in order_ids]
        return {'status': 'success', 'user_id': user_id, 'data': orders_list}

    def user_center(self, user_id):
        """Retrieves the user center details for a user by their ID."""
        user = self.user_centers.get(user_id)
        if user:
            return {'status': 'success', 'data': user}
        return {'status': 'error', 'message': f'User with id {user_id} not found.'}

    def edit_drinking(self, drinking_id, new_data):
        """Edits the details of a drinking item by its ID."""
        if drinking_id in self.drinking_items:
            self.drinking_items[drinking_id].update(new_data)
            return {'status': 'success', 'data': self.drinking_items[drinking_id]}
        return {'status': 'error', 'message': f'Drinking item with id {drinking_id} not found.'}

    def order_detail(self, order_id):
        """Retrieves the details of an order by its ID."""
        order = self.orders.get(order_id)
        if order:
            return {'status': 'success', 'data': order}
        return {'status': 'error', 'message': f'Order with id {order_id} not found.'}

    def dispatch_coupon(self, coupon_data):
        """
        Dispatches a coupon based on the given data.
        For simplicity, we assume coupon_data contains a coupon_id and a user_id to whom the coupon is dispatched.
        """
        coupon_id = coupon_data.get('coupon_id')
        user_id = coupon_data.get('user_id')
        if not coupon_id or not user_id:
            return {'status': 'error', 'message': 'coupon_id and user_id are required.'}

        # Check if coupon exists
        if coupon_id not in self.coupons:
            return {'status': 'error', 'message': f'Coupon with id {coupon_id} does not exist.'}

        # Dispatch coupon to user by adding to the user_coupons list
        if user_id in self.user_coupons:
            if coupon_id in self.user_coupons[user_id]:
                return {'status': 'error', 'message': f'User {user_id} already has coupon {coupon_id}.'}
            self.user_coupons[user_id].append(coupon_id)
        else:
            self.user_coupons[user_id] = [coupon_id]
        return {'status': 'success', 'message': f'Coupon {coupon_id} dispatched to user {user_id}.'}

    def add_coupon(self, coupon_data):
        """
        Adds a new coupon with the given data.
        The coupon_data should include necessary fields like discount and description.
        """
        new_id = max(self.coupons.keys(), default=0) + 1
        coupon_data['id'] = new_id
        self.coupons[new_id] = coupon_data
        return {'status': 'success', 'data': coupon_data, 'message': f'Coupon {new_id} added successfully.'}

    def edit_coupon(self, coupon_id, new_data):
        """Edits the details of a coupon by its ID."""
        if coupon_id in self.coupons:
            self.coupons[coupon_id].update(new_data)
            return {'status': 'success', 'data': self.coupons[coupon_id]}
        return {'status': 'error', 'message': f'Coupon with id {coupon_id} not found.'}

    def delete_coupon_operation(self, coupon_id):
        """Deletes a coupon by its ID."""
        if coupon_id in self.coupons:
            del self.coupons[coupon_id]
            # Also remove the coupon from any user's coupon list if present.
            for user, coup_list in self.user_coupons.items():
                if coupon_id in coup_list:
                    coup_list.remove(coupon_id)
            return {'status': 'success', 'message': f'Coupon with id {coupon_id} deleted successfully.'}
        return {'status': 'error', 'message': f'Coupon with id {coupon_id} not found.'}


