Below is an example AWS Lambda function written in Python that processes S3 object creation events with proper error handling, logging, tracing, and metric reporting using AWS Lambda Powertools. The code also includes unit tests for several scenarios (valid S3 event, missing object, and a Unicode decoding error). You can adjust the tests and configuration as needed.

────────────────────────────────────────────
File: lambda_function.py
────────────────────────────────────────────
#!/usr/bin/env python3
import boto3
import json
import os
from botocore.exceptions import ClientError
from aws_lambda_powertools import Logger, Tracer, Metrics
from aws_lambda_powertools.metrics import MetricUnit

# Initialize AWS SDK S3 client
s3 = boto3.client("s3")

# Initialize Powertools utilities
logger = Logger(service="S3Processor")
tracer = Tracer(service="S3Processor")
metrics = Metrics(namespace="MyApp", service="S3Processor")


@logger.inject_lambda_context
@tracer.capture_lambda_handler
def lambda_handler(event, context):
    """
    Lambda function to process S3 object creation events.
    It retrieves the new object's content (assumed to be UTF-8 text),
    logs details, and records a custom metric.
    """
    logger.info("Received event", extra={"event": event})
    details = {}
    content = None

    try:
        # For simplicity, process the first record in the event
        record = event["Records"][0]
        bucket = record["s3"]["bucket"]["name"]
        key = record["s3"]["object"]["key"]

        logger.info(f"Processing S3 object {key} from bucket {bucket}")

        try:
            response = s3.get_object(Bucket=bucket, Key=key)
        except ClientError as e:
            error_code = e.response["Error"]["Code"]
            logger.exception(f"Failed to retrieve object: {e}")
            if error_code == "NoSuchKey":
                return {
                    "error": f"Object {key} not found in bucket {bucket}",
                    "details": {"bucket": bucket, "key": key},
                }
            else:
                return {"error": "Error retrieving S3 object", "details": {"bucket": bucket, "key": key}}

        # Read and decode object content (UTF-8). Handle decoding errors.
        try:
            raw_body = response["Body"].read()
            content = raw_body.decode("utf-8")
        except UnicodeDecodeError as decode_err:
            logger.exception("Error decoding S3 object content.")
            return {"error": "Error decoding object content as UTF-8", "details": {"bucket": bucket, "key": key}}

        logger.debug("Retrieved S3 object content", extra={"content": content})
        details = {"bucket": bucket, "key": key}

    except Exception as e:
        logger.exception("An unexpected error occurred while processing the S3 event.")
        return {"error": "Unexpected error", "message": str(e)}

    # Record custom metric for processed S3 object creation event
    metrics.add_metric(name="S3ObjectProcessed", unit=MetricUnit.Count, value=1)
    metrics.publish()

    return {"content": content, "details": details}


# ─────────────────────────────────────────────
# Unit tests for the lambda function
# ─────────────────────────────────────────────
if __name__ == "__main__":
    import unittest
    from unittest.mock import patch, MagicMock

    class TestLambdaHandler(unittest.TestCase):
        def setUp(self):
            # Sample S3 event
            self.sample_event = {
                "Records": [
                    {
                        "s3": {
                            "bucket": {"name": "my-test-bucket"},
                            "object": {"key": "test.txt"},
                        }
                    }
                ]
            }
            # A fake context object
            self.context = type("LambdaContext", (), {"function_name": "test_func"})

        @patch("lambda_function.s3")
        def test_valid_object(self, mock_s3):
            # Mock S3 get_object response with valid UTF-8 content.
            fake_body = MagicMock()
            fake_body.read.return_value = b"Hello, world!"

            mock_s3.get_object.return_value = {"Body": fake_body}

            response = lambda_handler(self.sample_event, self.context)
            self.assertIn("content", response)
            self.assertEqual(response["content"], "Hello, world!")
            self.assertEqual(response["details"]["bucket"], "my-test-bucket")
            self.assertEqual(response["details"]["key"], "test.txt")

        @patch("lambda_function.s3")
        def test_object_not_found(self, mock_s3):
            # Simulate S3 object not found error.
            error_response = {"Error": {"Code": "NoSuchKey"}}
            mock_s3.get_object.side_effect = ClientError(error_response, "get_object")

            response = lambda_handler(self.sample_event, self.context)
            self.assertIn("error", response)
