# Begin Code

class FinancialTransactionProtocol:
    class Transaction:
        def __init__(self, sender, receiver, amount, currency, transaction_id):
            # Enforce message details for Transaction.
            if not transaction_id:
                raise ValueError("Transaction must have a non-empty unique transaction ID.")
            if amount < 0:
                raise ValueError("Transaction amount must be non-negative.")
            self._sender = sender
            self._receiver = receiver
            self._amount = amount
            self._currency = currency
            self._transaction_id = transaction_id

        # Properties to access message data.
        @property
        def sender(self):
            return self._sender

        @property
        def receiver(self):
            return self._receiver

        @property
        def amount(self):
            return self._amount

        @property
        def currency(self):
            return self._currency

        @property
        def transaction_id(self):
            return self._transaction_id

        def __repr__(self):
            return ("Transaction(sender={!r}, receiver={!r}, amount={!r}, currency={!r}, transaction_id={!r})"
                    .format(self.sender, self.receiver, self.amount, self.currency, self.transaction_id))

    class Confirmation:
        def __init__(self, transaction_id, success):
            # Enforce message details for Confirmation.
            if not transaction_id:
                raise ValueError("Confirmation must include a valid (non-empty) transaction ID.")
            if not isinstance(success, bool):
                raise ValueError("Confirmation 'success' field must be a boolean value.")
            self._transaction_id = transaction_id
            self._success = success

        # Properties to access message data.
        @property
        def transaction_id(self):
            return self._transaction_id

        @property
        def success(self):
            return self._success

        def __repr__(self):
            return "Confirmation(transaction_id={!r}, success={!r})".format(self.transaction_id, self.success)

    def __init__(self):
        # Keep a registry/dictionary of Transaction messages by transaction_id
        self._transactions = {}

    def create_transaction(self, sender, receiver, amount, currency, transaction_id):
        """
        Creates a Transaction message and stores it in the protocol registry.
        Raises an error if the transaction_id is already used.
        """
        if transaction_id in self._transactions:
            raise ValueError("A transaction with ID {} already exists.".format(transaction_id))
        transaction = FinancialTransactionProtocol.Transaction(sender, receiver, amount, currency, transaction_id)
        self._transactions[transaction_id] = transaction
        return transaction

    def create_confirmation(self, transaction_id, success):
        """
        Creates a Confirmation message.
        Raises an error if the transaction_id does not exist in the registry.
        """
        if transaction_id not in self._transactions:
            raise ValueError("No corresponding transaction found for transaction ID {}.".format(transaction_id))
        confirmation = FinancialTransactionProtocol.Confirmation(transaction_id, success)
        return confirmation

    def validate_message(self, message):
        """
        Checks if a message is consistent with the protocol rules:
          - For a Transaction message: verifies that the transaction_id is not empty,
            the amount is non-negative, and that this transaction is registered.
          - For a Confirmation message: verifies that the transaction_id is registered.
        Returns True if valid, otherwise False.
        """
        if isinstance(message, FinancialTransactionProtocol.Transaction):
            # Check for a valid transaction ID.
            if not message.transaction_id:
                return False
            # Check for non-negative amount.
            if message.amount < 0:
                return False
            # Optionally, check that the transaction id is known to the protocol.
            if message.transaction_id not in self._transactions:
                return False
            return True

        elif isinstance(message, FinancialTransactionProtocol.Confirmation):
            # For Confirmation messages, check that the transaction id exists.
            if message.transaction_id not in self._transactions:
                return False
            return True
        else:
            # Unknown message type.
            return False

# Example Usage:
if __name__ == "__main__":
    protocol = FinancialTransactionProtocol()

    # Create a Transaction message.
    try:
        txn = protocol.create_transaction(sender="Alice",
                                            receiver="Bob",
                                            amount=100.0,
                                            currency="USD",
                                            transaction_id="TXN12345")
        print("Created transaction:", txn)
    except ValueError as e:
        print("Error creating transaction:", e)

    # Validate the Transaction.
    is_valid_txn = protocol.validate_message(txn)
    print("Is transaction valid?", is_valid_txn)

    # Create a Confirmation message based on the existing transaction.
    try:
        conf = protocol.create_confirmation(transaction_id="TXN12345", success=True)
        print("Created confirmation:", conf)
    except ValueError as e:
        print("Error creating confirmation:", e)

    # Validate the Confirmation.
    is_valid_conf = protocol.validate_message(conf)
    print("Is confirmation valid?", is_valid_conf)

    # Attempt to create a confirmation for a non-existent transaction should fail.
    try:
        invalid_conf = protocol.create_confirmation(transaction_id="NON_EXISTENT", success=False)
    except ValueError as e:
        print("Error:", e)

------------------------------------------------
# End Code

Explanation:

1. The FinancialTransactionProtocol class maintains an internal registry (_transactions) for transactions with unique transaction IDs.

2. The nested Transaction and Confirmation classes are responsible for enforcing that their corresponding messages contain the proper fields. For example, Transaction enforces a non-empty transaction_id and a non-negative amount.

3. The create_transaction and create_confirmation methods create new messages, while ensuring that:
   - No duplicate transaction IDs are allowed for transactions.
   - A confirmation must reference an existing transaction.

4. The validate_message method examines a message instance to ensure it meets protocol rules:
   - For Transaction: checks that the transaction ID is non-empty, that the amount is non-negative, and that the transaction is registered.
   - For Confirmation: checks that the referenced transaction ID exists.

This design provides a clear structure, properties to access the message data, and protocol rule enforcement.

