Below is one complete solution that meets the requirements. In this example we:

• Create three models (City, Kind, SocialAccount) with the proper fields and relationships. City and Kind are defined by their “name” and “type” respectively, and SocialAccount holds a CSS style_class and FK links to a City and a Kind.  
• Create three serializers – CitySerializer, KindSerializer, and SocialAccountSerializer – with the SocialAccountSerializer using nested representation for city and kind. The serializer’s create() and update() methods look up (or create) the related City and Kind records. We also add a validate_style_class() method to return a clear error message when the input is invalid.  
• Provide separate endpoints for create (POST to /socialaccounts/) and for retrieve, update, and delete (GET, PUT, DELETE to /socialaccounts/pk/) using DRF’s APIView classes. Each endpoint returns the proper HTTP status code (e.g., 201 Created on creation, 404 Not Found when an object isn’t found).  
• Add authentication and authorization by requiring that the user be authenticated (for instance, using DRF’s IsAuthenticated permission – note that in a production project you might wire up token- or session-based authentication via your settings.py).  
• Provide unit tests for the serializers and endpoints, including edge cases (e.g., when the style_class is not a valid string).

Below are the complete code files:

──────────────────────────── Models (models.py) ────────────────────────────

from django.db import models

class City(models.Model):
    name = models.CharField(max_length=100, unique=True)

    def __str__(self):
        return self.name

class Kind(models.Model):
    type = models.CharField(max_length=100, unique=True)

    def __str__(self):
        return self.type

class SocialAccount(models.Model):
    style_class = models.CharField(max_length=100)
    city = models.ForeignKey(City, on_delete=models.CASCADE, related_name='social_accounts')
    kind = models.ForeignKey(Kind, on_delete=models.CASCADE, related_name='social_accounts')

    def __str__(self):
        return f"{self.kind.type} - {self.city.name}"

──────────────────────────── Serializers (serializers.py) ─────────────────────────────

from rest_framework import serializers
from .models import City, Kind, SocialAccount

class CitySerializer(serializers.ModelSerializer):
    class Meta:
        model = City
        fields = ['id', 'name']

class KindSerializer(serializers.ModelSerializer):
    class Meta:
        model = Kind
        fields = ['id', 'type']

class SocialAccountSerializer(serializers.ModelSerializer):
    # Nested serializers for city and kind
    city = CitySerializer()
    kind = KindSerializer()

    class Meta:
        model = SocialAccount
        fields = ['id', 'style_class', 'city', 'kind']

    def validate_style_class(self, value):
        if not isinstance(value, str):
            raise serializers.ValidationError("Style class must be a valid string representing the CSS class.")
        return value

    def create(self, validated_data):
        # Extract nested city and kind data.
        city_data = validated_data.pop('city')
        kind_data = validated_data.pop('kind')
        # Use get_or_create to either fetch or create new instances.
        city_obj, _ = City.objects.get_or_create(**city_data)
        kind_obj, _ = Kind.objects.get_or_create(**kind_data)
        social_account = SocialAccount.objects.create(city=city_obj, kind=kind_obj, **validated_data)
        return social_account

    def update(self, instance, validated_data):
        # Update style_class if provided
        instance.style_class = validated_data.get('style_class', instance.style_class)

        # Update nested city if provided.
        city_data = validated_data.get('city')
        if city_data:
            city_obj, _ = City.objects.get_or_create(**city_data)
            instance.city = city_obj

        # Update nested kind if provided.
        kind_data = validated_data.get('kind')
        if kind_data:
            kind_obj, _ = Kind.objects.get_or_create(**kind_data)
            instance.kind = kind_obj

        instance.save()
        return instance

──────────────────────────── Views (views.py) ─────────────────────────────

from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status, permissions
from .models import SocialAccount
from .serializers import SocialAccountSerializer

# Endpoint to create a social account.
class SocialAccountCreateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        serializer = SocialAccountSerializer(data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=status.HTTP_201_CREATED)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

# Endpoint for retrieve, update, and delete a social account.
class SocialAccountDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get_object(self, pk):
        try:
            return SocialAccount.objects.get(pk=pk)
        except SocialAccount.DoesNotExist:
            return None

    def get(self, request, pk):
        account = self.get_object(pk)
        if account is None:
            return Response({"detail": "Not found."}, status=status.HTTP_404_NOT_FOUND)
        serializer = SocialAccountSerializer(account)
        return Response(serializer.data, status=status.HTTP_200_OK)

    def put(self, request, pk):
        account = self.get_object(pk)
        if account is None:
            return Response({"detail": "Not found."}, status=status.HTTP_404_NOT_FOUND)
        serializer = SocialAccountSerializer(account, data=request.data)
        if serializer.is_valid():
            serializer.save()
            return Response(serializer.data, status=status.HTTP_200_OK)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

    def delete(self, request, pk):
        account = self.get_object(pk)
        if account is None:
            return Response({"detail": "Not found."}, status=status.HTTP_404_NOT_FOUND)
        account.delete()
        return Response(status=status.HTTP_204_NO_CONTENT)

──────────────────────────── URL Configuration (urls.py) ─────────────────────────────

