from django.urls import reverse
from rest_framework.test import APITestCase, APIClient
from rest_framework import status
from django.contrib.auth.models import User
from .models import City, Kind, SocialAccount

class SocialAccountAPITestCase(APITestCase):
    def setUp(self):
        # Create and authenticate a user to test that authentication is enforced.
        self.user = User.objects.create_user(username='testuser', password='password123')
        self.client = APIClient()
        self.client.login(username='testuser', password='password123')

    def test_create_social_account(self):
        url = reverse('socialaccount-create')
        data = {
            "style_class": "btn-primary",
            "city": {"name": "New York"},
            "kind": {"type": "Facebook"}
        }
        response = self.client.post(url, data, format='json')
        self.assertEqual(response.status_code, status.HTTP_201_CREATED)
        self.assertEqual(response.data['style_class'], "btn-primary")
        self.assertEqual(response.data['city']['name'], "New York")
        self.assertEqual(response.data['kind']['type'], "Facebook")

    def test_retrieve_social_account(self):
        city = City.objects.create(name="Los Angeles")
        kind = Kind.objects.create(type="Twitter")
        social = SocialAccount.objects.create(style_class="btn-info", city=city, kind=kind)
        url = reverse('socialaccount-detail', kwargs={'pk': social.pk})
        response = self.client.get(url, format='json')
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertEqual(response.data['style_class'], "btn-info")
        self.assertEqual(response.data['city']['name'], "Los Angeles")
        self.assertEqual(response.data['kind']['type'], "Twitter")

    def test_update_social_account(self):
        city = City.objects.create(name="Chicago")
        kind = Kind.objects.create(type="Instagram")
        social = SocialAccount.objects.create(style_class="btn-warning", city=city, kind=kind)
        url = reverse('socialaccount-detail', kwargs={'pk': social.pk})
        data = {
            "style_class": "btn-success",
            "city": {"name": "Boston"},
            "kind": {"type": "LinkedIn"}
        }
        response = self.client.put(url, data, format='json')
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        updated_social = SocialAccount.objects.get(pk=social.pk)
        self.assertEqual(updated_social.style_class, "btn-success")
        self.assertEqual(updated_social.city.name, "Boston")
        self.assertEqual(updated_social.kind.type, "LinkedIn")

    def test_delete_social_account(self):
        city = City.objects.create(name="San Francisco")
        kind = Kind.objects.create(type="Pinterest")
        social = SocialAccount.objects.create(style_class="btn-light", city=city, kind=kind)
        url = reverse('socialaccount-detail', kwargs={'pk': social.pk})
        response = self.client.delete(url, format='json')
        self.assertEqual(response.status_code, status.HTTP_204_NO_CONTENT)
        self.assertFalse(SocialAccount.objects.filter(pk=social.pk).exists())

    def test_invalid_style_class(self):
        url = reverse('socialaccount-create')
        # Passing a non-string value for style_class.
        data = {
            "style_class": 123,  
            "city": {"name": "Miami"},
            "kind": {"type": "Snapchat"}
        }
        response = self.client.post(url, data, format='json')
        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)
        self.assertIn('style_class', response.data)

