#!/usr/bin/env python3
"""
Employee Attendance Manager using MongoDB

This module provides functionalities to:
  1. Insert a new attendance record.
  2. Fetch all attendance records.
  3. Fetch attendance records by a specific date.
  4. Fetch attendance records by employee ID.
  5. Fetch attendance records by both employee ID and date.
  6. Get the contact phone number of an employee.

Data validations and error handling are implemented to ensure data integrity and
to protect sensitive employee information.

Dependencies: pymongo (Install via pip install pymongo)
"""

from pymongo import MongoClient, errors
from datetime import datetime

# Create a MongoDB client connection
def get_db():
    try:
        client = MongoClient("mongodb://localhost:27017/")
        db = client["employee_db"]
        return db
    except errors.ConnectionFailure as e:
        print("MongoDB connection failed:", e)
        return None

# Helper function to validate date format (expecting YYYY-MM-DD)
def validate_date(date_text):
    try:
        datetime.strptime(date_text, '%Y-%m-%d')
        return True
    except ValueError:
        return False

# Helper function to validate time format (expecting HH:MM:SS)
def validate_time(time_text):
    try:
        datetime.strptime(time_text, '%H:%M:%S')
        return True
    except ValueError:
        return False

# 1. Insert a new attendance record into the `attendance` collection.
def insert_attendance_record(emp_id, name, date, time, db):
    """
    Inserts a new attendance record.
    Input:
      emp_id: Employee ID (string or int)
      name: Employee name (string)
      date: Date of attendance (YYYY-MM-DD)
      time: Time of attendance (HH:MM:SS)
      db: Database handle
    Returns:
      dict with status and message, or inserted_id.
    """
    if not db:
        return {"status": "error", "message": "No database connection."}
    # Validate parameters
    if not emp_id or not name or not date or not time:
        return {"status": "error", "message": "Missing required parameters."}
    if not validate_date(date):
        return {"status": "error", "message": f"Date {date} is not in YYYY-MM-DD format."}
    if not validate_time(time):
        return {"status": "error", "message": f"Time {time} is not in HH:MM:SS format."}

    attendance_doc = {
        "emp_id": emp_id,
        "name": name,
        "date": date,
        "time": time
    }
    try:
        result = db.attendance.insert_one(attendance_doc)
        return {"status": "success", "inserted_id": str(result.inserted_id)}
    except Exception as e:
        return {"status": "error", "message": f"Failed to insert record: {e}"}

# 2. Fetch all attendance records.
def fetch_all_attendance(db):
    """
    Retrieves all attendance records.
    Input:
      db: Database handle
    Returns:
      List of attendance records or informative message.
    """
    if not db:
        return {"status": "error", "message": "No database connection."}
    try:
        records = list(db.attendance.find({}, {"_id": 0}))  # Excluding the Mongo _id field for clarity.
        if not records:
            return {"status": "success", "message": "No attendance records found.", "data": []}
        return {"status": "success", "data": records}
    except Exception as e:
        return {"status": "error", "message": f"Error fetching records: {e}"}

# 3. Fetch attendance records by a specific date.
def fetch_attendance_by_date(date, db):
    """
    Retrieves attendance records for a specific date.
    Input:
      date: Date in YYYY-MM-DD format.
      db: Database handle.
    Returns:
      List of records for the date or message.
    """
    if not db:
        return {"status": "error", "message": "No database connection."}
    if not date or not validate_date(date):
        return {"status": "error", "message": "Invalid or missing date parameter."}
    try:
        records = list(db.attendance.find({"date": date}, {"_id": 0}))
        if not records:
            return {"status": "success", "message": f"No attendance records found for date: {date}", "data": []}
        return {"status": "success", "data": records}
    except Exception as e:
        return {"status": "error", "message": f"Error fetching attendance records: {e}"}

# 4. Fetch attendance records by a specific employee ID.
def fetch_attendance_by_emp_id(emp_id, db):
    """
    Retrieves attendance records for a specific employee.
    Input:
      emp_id: Employee ID.
      db: Database handle.
    Returns:
      List of records for the employee or message.
    """
    if not db:
        return {"status": "error", "message": "No database connection."}
    if not emp_id:
        return {"status": "error", "message": "Employee ID is required."}
    try:
        records = list(db.attendance.find({"emp_id": emp_id}, {"_id": 0}))
        if not records:
            return {"status": "success", "message": f"No attendance records found for emp_id: {emp_id}", "data": []}
        return {"status": "success", "data": records}
    except Exception as e:
        return {"status": "error", "message": f"Error fetching records for employee: {e}"}

# 5. Fetch attendance records by both employee ID and date.
def fetch_attendance_by_emp_id_and_date(emp_id, date, db):
    """
    Retrieves attendance records filtered by employee ID and date.
    Input:
      emp_id: Employee ID.
      date: Date in YYYY-MM-DD format.
      db: Database handle.
    Returns:
      List of records or message.
    """
    if not db:
        return {"status": "error", "message": "No database connection."}
    if not emp_id or not date:
        return {"status": "error", "message": "Employee ID and date are required."}
    if not validate_date(date):
        return {"status": "error", "message": "Date is not in the valid 'YYYY-MM-DD' format."}

    try:
        query = {"emp_id": emp_id, "date": date}
        records = list(db.attendance.find(query, {"_id": 0}))
        if not records:
            return {"status": "success", 
                    "message": f"No attendance records found for emp_id: {emp_id} on date: {date}", 
                    "data": []}
        return {"status": "success", "data": records}
    except Exception as e:
        return {"status": "error", "message": f"Error fetching records: {e}"}

# 6. Get the contact phone number of an employee from the `emp` collection.
def get_employee_contact(emp_id, db):
    """
    Retrieves the contact phone number for the given employee.
    Sensitive information is handled carefully.
    Input:
      emp_id: Employee ID.
      db: Database handle.
    Returns:
      Phone number string or appropriate message.
    """
    if not db:
        return {"status": "error", "message": "No database connection."}
    if not emp_id:
        return {"status": "error", "message": "Employee ID is required."}

    try:
        # We project only the contact field to minimize exposure of other sensitive data.
        projection = {"_id": 0, "contact": 1}
        employee = db.emp.find_one({"emp_id": emp_id}, projection)
        if not employee:
            return {"status": "success", "message": f"No employee found with emp_id: {emp_id}"}
        # Assuming the employee document contains a dictionary 'contact' with key 'phone'
        contact = employee.get("contact", {})
        phone = contact.get("phone")
        if phone:
            return {"status": "success", "phone": phone}
        else:
            return {"status": "success", "message": "Phone number not found for the employee."}
    except Exception as e:
        return {"status": "error", "message": f"Error retrieving employee contact: {e}"}

# -------------------------
# Test Cases
# -------------------------
if __name__ == "__main__":
    # Connect to the database
    db = get_db()
    if not db:
        print("Cannot run tests without a database connection.")
    else:
        print("Database connection established.")

    # 1. Test Inserting a New Attendance Record
    print("\nTest: Insert a new attendance record")
    result = insert_attendance_record(emp_id="E001", 
                                      name="Alice Smith", 
                                      date="2023-10-15", 
                                      time="09:00:00", 
                                      db=db)
    print("Insert Result:", result)

    # 2. Test Fetching All Attendance Records
    print("\nTest: Fetch all attendance records")
    result = fetch_all_attendance(db)
    print("Fetch All Attendance:", result)

    # 3. Test Fetching Attendance Records by Specific Date
    print("\nTest: Fetch attendance records for date '2023-10-15'")
    result = fetch_attendance_by_date("2023-10-15", db)
    print("Attendance by Date:", result)

    # 4. Test Fetching Attendance Records by Employee ID
    print("\nTest: Fetch attendance records for employee ID 'E001'")
    result = fetch_attendance_by_emp_id("E001", db)
    print("Attendance by Employee ID:", result)

    # 5. Test Fetching Attendance Records by Employee ID and Date
    print("\nTest: Fetch attendance records for employee 'E001' on '2023-10-15'")
    result = fetch_attendance_by_emp_id_and_date("E001", "2023-10-15", db)
    print("Attendance by Employee ID & Date:", result)

    # 6. Test Getting Employee Contact
    print("\nTest: Get contact info for employee ID 'E001'")
    result = get_employee_contact("E001", db)
    print("Employee Contact:", result)

    # Additional test: Handling invalid date format:
    print("\nTest: Insert with invalid date format")
    result = insert_attendance_record(emp_id="E002", name="Bob Johnson", date="15-10-2023", time="09:00:00", db=db)
    print("Insert with Invalid Date:", result)

    # Additional test: Fetch for a date with no records
    print("\nTest: Fetch attendance records for date '2023-11-01'")
    result = fetch_attendance_by_date("2023-11-01", db)
    print("Attendance by Date (No records):", result)

    # Note: Ensure that test data is available in the `emp` collection for get_employee_contact.
    # For example, an employee document structure in the `emp` collection might be:
    # {
