response:
Below is an example Django application that meets the requirements. In this example the app is called “myapp” (you can change the name as needed). The application includes:

• A Django form (WallpaperForm) with a text field for the search phrase and a Boolean field for “random wallpapers”.  
• A view function “wallpaper” that handles GET and POST requests. On POST the view calls a helper function convert_images() which uses Wallhaven’s public API to search for wallpapers, downloads a “small” thumbnail image for each result, and returns a list of tuples (extension, base64‐encoded image data). When the POST is made via AJAX the view returns a JSON response containing the rendered thumbnails (as HTML) while a normal GET simply shows the form.  
• Two templates – “home.html” (which contains the form, an AJAX script (using jQuery) to submit the form asynchronously, and a spinner to show progress) and “search_results.html” (which renders the base64 images as thumbnails).  
• Basic error handling so that if Wallhaven is not reachable (or another error occurs) an appropriate message is displayed.

Below is the complete code:

─────────────────────────────  
1. forms.py  
─────────────────────────────

# In myapp/forms.py
from django import forms

class WallpaperForm(forms.Form):
    search_phrase = forms.CharField(
        label="Search",
        required=False,
        widget=forms.TextInput(attrs={'placeholder': 'Enter search phrase'}),
    )
    random_wallpapers = forms.BooleanField(
        label="Random Wallpapers",
        required=False,
        initial=False
    )

─────────────────────────────  
2. views.py  
─────────────────────────────

# In myapp/views.py
import os
import base64
import requests
from django.shortcuts import render
from django.http import JsonResponse
from .forms import WallpaperForm

def convert_images(search_phrase, random_flag):
    """
    Given a search phrase and a boolean flag for random images,
    fetches wallpaper results from the Wallhaven API, downloads the small thumbnails,
    and returns a list of tuples (extension, base64_encoded_image).
    If an error occurs during API calls, returns a tuple (None, error_message).
    """
    # Wallhaven API endpoint
    api_url = "https://wallhaven.cc/api/v1/search"
    params = {}

    if random_flag:
        params['sorting'] = 'random'
    if search_phrase:
        params['q'] = search_phrase
    else:
        # if no search phrase and not random, leave query empty
        params['q'] = ""

    try:
        response = requests.get(api_url, params=params, timeout=5)
        response.raise_for_status()
    except Exception as e:
        return None, "Error connecting to Wallhaven API."

    json_data = response.json()
    images = []

    for wallpaper in json_data.get("data", []):
        # Use the small thumbnail (if available) from the 'thumbs' dictionary.
        thumb_url = wallpaper.get("thumbs", {}).get("small")
        if not thumb_url:
            continue

        try:
            # Fetch the thumbnail image bytes
            img_resp = requests.get(thumb_url, timeout=5)
            img_resp.raise_for_status()
            img_data = img_resp.content
            # Base64 encode the image data
            encoded = base64.b64encode(img_data).decode('utf-8')

            # Extract the file extension (e.g., jpg, png)
            ext = os.path.splitext(thumb_url)[1].lstrip(".")
            images.append((ext, encoded))
        except Exception as e:
            # Skip this image if an error occurs
            continue

    return images, None

def wallpaper(request):
    """
    Handles both GET and POST requests.
    – On GET: Renders home.html with the wallpaper search form.
    – On POST: Processes the form, calls convert_images(), and returns:
      • a JSON response with rendered thumbnails (if AJAX),
      • or a full page re-render with the results.
    """
    if request.method == "POST":
        form = WallpaperForm(request.POST)
        if form.is_valid():
            # Cleaned and sanitized input thanks to Django forms
            search_phrase = form.cleaned_data.get("search_phrase")
            random_flag = form.cleaned_data.get("random_wallpapers")

            images, error = convert_images(search_phrase, random_flag)
            if error:
                context = {"form": form, "error": error}
                if request.headers.get("x-requested-with") == "XMLHttpRequest":
                    return JsonResponse({"error": error})
                return render(request, "myapp/home.html", context)

            context = {"images": images}
            if request.headers.get("x-requested-with") == "XMLHttpRequest":
                # Render the thumbnail HTML fragment using search_results.html
                html = render(request, "myapp/search_results.html", context).content.decode("utf-8")
                return JsonResponse({"html": html})
            else:
                # For non-AJAX POST requests render the full page
                context["form"] = form
                return render(request, "myapp/home.html", context)
        else:
            error = "Invalid input provided."
            if request.headers.get("x-requested-with") == "XMLHttpRequest":
                return JsonResponse({"error": error})
            return render(request, "myapp/home.html", {"form": form, "error": error})
    else:
        # GET request: simply show the search form
        form = WallpaperForm()
        return render(request, "myapp/home.html", {"form": form})

