<!-- In myapp/templates/myapp/home.html -->
<html>
  <head>
    <title>Wallpaper Search</title>
    <!-- jQuery is used for AJAX -->
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
    <style>
      /* Style for the loading spinner/message. */
      #spinner {
        display: none;
        margin: 10px 0;
        font-weight: bold;
      }
      .thumbnail {
        width: 200px;
        height: auto;
        margin: 5px;
      }
    </style>
  </head>
  <body>
    <h1>Wallpaper Search</h1>

    <form id="search-form" method="post" action="{% url 'wallpaper' %}">
      {% csrf_token %}
      {{ form.as_p }}
      <button type="submit">Search</button>
    </form>

    <div id="spinner">
      <p>Loading images...</p>
    </div>

    <div id="results">
      {% if error %}
        <p style="color:red;">{{ error }}</p>
      {% endif %}
      {% if images %}
        {% include "myapp/search_results.html" with images=images %}
      {% endif %}
    </div>

    <script>
      $(document).ready(function(){
          $("#search-form").on("submit", function(e) {
              e.preventDefault();  // Prevent the default form submission
              $("#spinner").show();
              $.ajax({
                  url: "{% url 'wallpaper' %}",
                  type: "POST",
                  data: $(this).serialize(),
                  headers: {
                      "X-Requested-With": "XMLHttpRequest"
                  },
                  success: function(response) {
                      $("#spinner").hide();
                      if (response.error) {
                          $("#results").html("<p style='color:red;'>" + response.error + "</p>");
                      } else if (response.html) {
                          $("#results").html(response.html);
                      }
                  },
                  error: function() {
                      $("#spinner").hide();
                      $("#results").html("<p style='color:red;'>An error occurred while loading images.</p>");
                  }
              });
          });
      });
    </script>
  </body>
</html>

