#!/usr/bin/env python3
from flask import Flask, request, jsonify, abort
from functools import wraps

app = Flask(__name__)

# In-memory store for leaks, with leak_id as key.
leaks_db = {}

# Sample users dictionary for demonstration purposes.
# In production, you would use a more robust authentication mechanism.
users = {
    "admin": {"password": "admin123", "role": "admin"},
    "user": {"password": "user123", "role": "user"},
}


# Simple decorator to simulate authentication. It looks for 'username' and 'password'
# in the request headers.
def require_auth(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        auth_username = request.headers.get("username")
        auth_password = request.headers.get("password")
        user = users.get(auth_username)
        if not user or user["password"] != auth_password:
            # 401 Unauthorized response
            return jsonify({
                "status": "error",
                "error": "Unauthorized access - Invalid or missing credentials."
            }), 401
        # Optionally, role based access could be further checked here:
        request.user = {"username": auth_username, "role": user["role"]}
        return fn(*args, **kwargs)
    return wrapper


# Endpoint: POST /api/v2/leak/general/
