    if not payload:
        return jsonify({
            "status": "error",
            "error": "Missing JSON payload."
        }), 400

    # Check for required parameters.
    url = payload.get("url")
    leak_id = payload.get("leak_id")
    if not url or not leak_id:
        return jsonify({
            "status": "error",
            "error": "Missing required parameters: 'url' and/or 'leak_id'."
        }), 400

    # Check if leak_id already exists.
    if leak_id in leaks_db:
        return jsonify({
            "status": "error",
            "error": "Leak with this leak_id already exists."
        }), 400

    # Create a new leak entry.
    leaks_db[leak_id] = {"leak_id": leak_id, "url": url}
    return jsonify({
        "status": "success",
        "message": "Leak entry created.",
        "data": leaks_db[leak_id]
    }), 201


# Endpoint: GET /api/v2/leak/general/
@app.route('/api/v2/leak/general/', methods=['GET'])
@require_auth
def get_all_leaks():
    leak_list = list(leaks_db.values())
    return jsonify({
        "status": "success",
        "message": "Leak entries retrieved",
        "data": leak_list
    }), 200


# Endpoint: GET /api/v2/leak/general/<leak_id>
@app.route('/api/v2/leak/general/<string:leak_id>', methods=['GET'])
@require_auth
def get_single_leak(leak_id):
    leak = leaks_db.get(leak_id)
    if not leak:
        return jsonify({
            "status": "error",
            "error": f"Leak entry with id {leak_id} not found."
        }), 404
    return jsonify({
        "status": "success",
        "message": "Leak entry retrieved.",
        "data": leak
    }), 200


# Endpoint: DELETE /api/v2/leak/general/<leak_id>
@app.route('/api/v2/leak/general/<string:leak_id>', methods=['DELETE'])
@require_auth
def delete_leak(leak_id):
    leak = leaks_db.get(leak_id)
    if not leak:
        return jsonify({
            "status": "error",
            "error": f"Leak entry with id {leak_id} not found."
        }), 404
    del leaks_db[leak_id]
    return jsonify({
        "status": "success",
        "message": f"Leak entry with id {leak_id} deleted."
    }), 200


