import java.util.List;

public class CustomerVerifier {
    private final List<Verification> verifications;

    /**
     * Creates a new verifier with a list of verifications.
     * 
     * @param verifications the list of Verification instances.
     */
    public CustomerVerifier(List<Verification> verifications) {
        // Defensive copy if necessary; here we simply assign.
        this.verifications = verifications;
    }

    /**
     * Runs all verifications on the given customer.
     *
     * Sensitive customer data is not logged; only generic messages are produced.
     *
     * @param customer the customer to verify.
     * @return a CustomerVerificationResult indicating overall pass or failure.
     */
    public CustomerVerificationResult verify(Customer customer) {
        // Check for null customer and basic data presence.
        if (customer == null) {
            return new CustomerVerificationResult(false, "Customer information is missing.");
        }

        // We can perform any additional minimal pre-checks
        if (customer.getId() == null || customer.getId().isEmpty() ||
            customer.getName() == null || customer.getName().isEmpty() ||
            customer.getEmail() == null || customer.getEmail().isEmpty()) {
            return new CustomerVerificationResult(false, "Customer has missing or malformed personal information.");
        }

        // Iterate over each verification and run it.
        for (Verification verification : verifications) {
            try {
                boolean result = verification.verify(customer);
                if (!result) {
                    // We don’t include sensitive information in our failure message.
                    return new CustomerVerificationResult(false, "Customer verification failed.");
