        Verification emailCheck = new EmailFormatVerification();
        Verification nameCheck = new NameNotEmptyVerification();

        // Create the verifier with all verifications.
        CustomerVerifier verifier = new CustomerVerifier(Arrays.asList(emailCheck, nameCheck));

        // Create a customer.
        Customer customer = new Customer("12345", "Alice", "alice@example.com");

        // Run the verifications.
