def flatten_list(input_list):
    # Ensure the input is a list; raise TypeError if not.
    if not isinstance(input_list, list):
        raise TypeError("Input must be a list.")

    # Initialize an empty list to hold the flattened elements.
    flattened = []

    # Iterate over each element in the input list.
    for item in input_list:
        # If the item is a list, extend the flattened list by the elements of that list.
        if isinstance(item, list):
            flattened.extend(item)
        else:
            flattened.append(item)

    return flattened

# Example usage:
if __name__ == "__main__":
    print(flatten_list([1, [2, 3], 4]))            # Output: [1, 2, 3, 4]
    print(flatten_list([['a', 'b'], 'c', ['d']]))    # Output: ['a', 'b', 'c', 'd']

