def contains_whitespace(iterable):
    if not isinstance(iterable, (str, list, tuple)):
        raise TypeError("Input must be a string, list, or tuple.")

    # Helper function to check if a string element is composed entirely of whitespace,
    # with the special case that empty strings should return False.
    def is_only_whitespace(s):
        # s is assumed to be a string; empty string returns False by definition.
        return bool(s) and s.strip() == ""

    result = []

    # When the input is a string, treat each individual character as an element.
    if isinstance(iterable, str):
        for char in iterable:
            result.append(is_only_whitespace(char))
    else:
        # iterable is list or tuple, check each element if it is a string.
        for elem in iterable:
            if isinstance(elem, str):
                result.append(is_only_whitespace(elem))
            else:
                result.append(False)
    return result

# Example test cases
print(contains_whitespace("hello world"))  # [False, False, False, False, False, True, False, False, False, False, False]
print(contains_whitespace(["hello", " ", "world"]))  # [False, True, False]
print(contains_whitespace(("   ", "\t", "text", 5)))  # [True, True, False, False]

