#!/usr/bin/env python3
"""
A Flask application providing RESTful statistical analysis services.
Each endpoint expects POSTed JSON data and returns results in JSON format.
"""

from flask import Flask, request, jsonify
import numpy as np
import scipy.stats as stats

app = Flask(__name__)

# ---------------------------
# Helper Functions
# ---------------------------
def validate_sample(data, key):
    """
    Validate that the JSON contains the given key and that its value is a non-empty list of numbers.
    Returns the sample numpy array if valid.
    """
    if key not in data:
        raise ValueError(f"Missing '{key}' field in JSON data.")
    sample = data[key]
    if not isinstance(sample, list) or len(sample) == 0:
        raise ValueError(f"'{key}' must be a non-empty list.")
    # Ensure each element is a number (float or int)
    try:
        sample = [float(x) for x in sample]
    except Exception:
        raise ValueError(f"All elements in '{key}' must be numbers.")
    return np.array(sample)

def validate_two_samples(data):
    """
    Validate and return two samples (sample1 and sample2) from the JSON.
    """
    sample1 = validate_sample(data, "sample1")
    sample2 = validate_sample(data, "sample2")
    return sample1, sample2

# ---------------------------
# Endpoints
# ---------------------------

@app.route('/ztest', methods=['POST'])
def ztest():
    """
    - For one-sample Z-test: Use sample1 and optionally a population mean "mu" (default 0).
      Also, sample1 must have >30 unique values, otherwise advise use T-test.
    - For two-sample Z-test: Use both sample1 and sample2, each must have >30 unique values,
      otherwise advise using a T-test.

    The test calculates the Z statistic and two-tailed p-value based on the assumption that
    either the population variance is approximated by the sample variance (large sample),
    or that sample sizes are big.
    """
    try:
        data = request.get_json(force=True)
        # Check whether sample2 is provided.
        if "sample2" in data:
            # Two-sample Z-test
            sample1, sample2 = validate_two_samples(data)

            if len(np.unique(sample1)) <= 30 or len(np.unique(sample2)) <= 30:
                return jsonify({"error": "For two-sample Z-test, each sample should have more than 30 unique values. Consider using a T-test."}), 400

            n1, n2 = len(sample1), len(sample2)
            mean1, mean2 = np.mean(sample1), np.mean(sample2)
            # Use sample standard deviations as approximations of population std dev
            std1, std2 = np.std(sample1, ddof=1), np.std(sample2, ddof=1)
            # calculate standard error of difference 
            se = np.sqrt(std1**2 / n1 + std2**2 / n2)
            if se == 0:
                raise ValueError("Standard error is zero; check your data.")
            z_stat = (mean1 - mean2) / se
            # compute two-tailed p-value
            p_value = 2 * (1 - stats.norm.cdf(abs(z_stat)))
            return jsonify({"test": "two-sample Z-test", "z_statistic": z_stat, "p_value": p_value})
        else:
            # One-sample Z-test
            sample = validate_sample(data, "sample1")
            if len(np.unique(sample)) <= 30:
                return jsonify({"error": "For one-sample Z-test, the sample should have more than 30 unique values. Consider using a T-test."}), 400

            # Optional population mean parameter, default = 0.
            mu = float(data.get("mu", 0))
            n = len(sample)
            sample_mean = np.mean(sample)
            sample_std = np.std(sample, ddof=1)
            if sample_std == 0:
                raise ValueError("Standard deviation is zero; cannot perform Z-test.")
            z_stat = (sample_mean - mu) / (sample_std / np.sqrt(n))
            p_value = 2 * (1 - stats.norm.cdf(abs(z_stat)))
            return jsonify({"test": "one-sample Z-test", "z_statistic": z_stat, "p_value": p_value})
    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route('/ttest-equalvariance', methods=['POST'])
def ttest_equalvariance():
    """
    Perform a T-test assuming equal variances; returns the T statistic and p-value.
    """
    try:
        data = request.get_json(force=True)
        sample1, sample2 = validate_two_samples(data)
        t_stat, p_value = stats.ttest_ind(sample1, sample2, equal_var=True)
        return jsonify({"test": "T-test (equal variance)", "t_statistic": t_stat, "p_value": p_value})
    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route('/ttest-unequalvariance', methods=['POST'])
def ttest_unequalvariance():
    """
    Perform a T-test assuming unequal variances (Welch’s t-test).
    """
    try:
        data = request.get_json(force=True)
        sample1, sample2 = validate_two_samples(data)
        t_stat, p_value = stats.ttest_ind(sample1, sample2, equal_var=False)
        return jsonify({"test": "T-test (unequal variance)", "t_statistic": t_stat, "p_value": p_value})
    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route('/normaltest', methods=['POST'])
def normaltest():
    """
    Perform a normality test (D'Agostino and Pearson’s test) on a single sample.
    """
    try:
        data = request.get_json(force=True)
        sample = validate_sample(data, "sample")
        stat, p_value = stats.normaltest(sample)
        return jsonify({"test": "Normality test", "statistic": stat, "p_value": p_value})
    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route('/outliertest', methods=['POST'])
def outliertest():
    """
    Identify outliers in a sample using the IQR method.
    Returns the outlier values.
    """
    try:
        data = request.get_json(force=True)
        sample = validate_sample(data, "sample")
        q1 = np.percentile(sample, 25)
        q3 = np.percentile(sample, 75)
        iqr = q3 - q1
        lower_bound = q1 - 1.5 * iqr
