------------------------------------------------
# BEGIN SOLUTION

# File: app.py

import threading
from flask import Flask, render_template, request, jsonify
from flask_socketio import SocketIO, emit
import logging

# Create a simple in-memory vote store, with a thread lock for safety.
class VoteStore:
    def __init__(self):
        self.votes = {"yes": 0, "no": 0, "maybe": 0}
        self.lock = threading.Lock()

    def update_vote(self, vote):
        """Update the vote count for a valid vote.
           Returns a tuple (success, message). If success is False, message contains an error message.
        """
        if vote not in self.votes:
            return (False, "Invalid vote option.")
        with self.lock:
            self.votes[vote] += 1
        return (True, "Vote recorded successfully.")

    def get_votes(self):
        """Return a copy of the current votes."""
        with self.lock:
            return dict(self.votes)


def create_app():
    """Create and configure the Flask application."""
    app = Flask(__name__)
    # Secret key is used for securely signing the session cookie.
    app.config["SECRET_KEY"] = "mysecret"
    return app


def create_socketio(app):
    """Create and return the SocketIO server instance."""
    socketio = SocketIO(app, cors_allowed_origins="*")
    return socketio


def register_routes(app, vote_store):
    """Register HTTP routes for the application."""

    @app.route("/")
    def index():
        votes = vote_store.get_votes()
        # The template auto-escapes content, protecting against XSS.
        return render_template("index.html", votes=votes)

    # You can add more HTTP API routes if needed.
    return app


def register_socketio_events(socketio, vote_store):
    """Register SocketIO event handlers."""
    # The 'submit_vote' event expects data in the form {'vote': 'yes'/'no'/'maybe'}
    @socketio.on("submit_vote")
    def handle_submit_vote(data):
        vote = data.get("vote", "")
        success, message = vote_store.update_vote(vote)
        if success:
            # Broadcast updated votes to all connected clients.
            updated_votes = vote_store.get_votes()
            emit("update_votes", updated_votes, broadcast=True)
            # Also send a personal acknowledgement.
            emit("vote_ack", {"status": "success", "message": message})
        else:
            # Send an error message back to the client.
            emit("vote_ack", {"status": "error", "message": message})

    # Documenting the Socket.IO events:
    #
    # Event: "submit_vote"
    #   Client sends: {"vote": "yes"/"no"/"maybe"}
    #   Server response:
    #       On success: emits "vote_ack" with {"status": "success", "message": "Vote recorded successfully."}
    #                    and broadcasts "update_votes" with the updated vote counts.
    #       On error: emits "vote_ack" with {"status": "error", "message": "<error message>"}
    return socketio


# Unit tests for the vote processing logic
def run_tests():
    import unittest

    class VoteStoreTests(unittest.TestCase):

        def setUp(self):
            self.vote_store = VoteStore()

        def test_valid_vote(self):
            success, message = self.vote_store.update_vote("yes")
            self.assertTrue(success)
            self.assertEqual(message, "Vote recorded successfully.")
            self.assertEqual(self.vote_store.get_votes()["yes"], 1)

        def test_invalid_vote(self):
            success, message = self.vote_store.update_vote("maybee")
            self.assertFalse(success)
            self.assertEqual(message, "Invalid vote option.")
            # Ensure that vote counts remain unchanged.
            self.assertEqual(self.vote_store.get_votes(), {"yes": 0, "no": 0, "maybe": 0})

        def test_multiple_votes(self):
            self.vote_store.update_vote("no")
            self.vote_store.update_vote("maybe")
            self.vote_store.update_vote("no")
            votes = self.vote_store.get_votes()
            self.assertEqual(votes["no"], 2)
            self.assertEqual(votes["maybe"], 1)
            self.assertEqual(votes["yes"], 0)

    suite = unittest.TestLoader().loadTestsFromTestCase(VoteStoreTests)
    unittest.TextTestRunner(verbosity=2).run(suite)


# Main execution block
if __name__ == "__main__":
    import sys

    # If "test" is passed as a command line argument, run the unit tests.
    if len(sys.argv) > 1 and sys.argv[1] == "test":
        run_tests()
    else:
        app = create_app()
        vote_store = VoteStore()
        register_routes(app, vote_store)
        socketio = create_socketio(app)
        register_socketio_events(socketio, vote_store)
        # Set up logging for Socket.IO to see real-time events on the console.
        logging.basicConfig(level=logging.INFO)
        # Start the Flask app with Socket.IO support.
        socketio.run(app, debug=True)

