"""
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <title>Vote on the Question</title>
    <style>
      body { font-family: Arial, sans-serif; margin: 20px; }
      .vote-container { margin-top: 20px; }
      .feedback { color: green; margin-top: 10px; }
      .error { color: red; margin-top: 10px; }
    </style>
    <!-- Include Socket.IO client library -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/socket.io/4.6.1/socket.io.min.js" integrity="sha512-3+fP4JSwzF5Oe1CDRR/QMeJowg9KjL6CPxI9gS8UlDpJZ+VbYEazF5O9rlM/nTRr94/7Y4W1d/XxY3Ebp3Ip3A==" crossorigin="anonymous" referrerpolicy="no-referrer"></script>
  </head>
  <body>
    <h1>Vote on the Question</h1>
    <form id="voteForm">
      <label><input type="radio" name="vote" value="yes"> Yes</label>
      <label><input type="radio" name="vote" value="no"> No</label>
      <label><input type="radio" name="vote" value="maybe"> Maybe</label>
      <button type="submit">Submit Vote</button>
    </form>
    <div class="feedback" id="feedback"></div>
    <h2>Current Vote Totals</h2>
    <div id="voteTotals">
      <ul>
        <li>Yes: <span id="yesTotal">{{ votes['yes'] }}</span></li>
        <li>No: <span id="noTotal">{{ votes['no'] }}</span></li>
        <li>Maybe: <span id="maybeTotal">{{ votes['maybe'] }}</span></li>
      </ul>
    </div>

    <script>
      document.addEventListener("DOMContentLoaded", function() {
        var socket = io();

        // When the form is submitted, send the vote via Socket.IO.
        document.getElementById("voteForm").addEventListener("submit", function(e) {
          e.preventDefault();
          var voteInputs = document.getElementsByName("vote");
          var selectedVote = "";
          for (var i = 0; i < voteInputs.length; i++) {
              if (voteInputs[i].checked) {
                  selectedVote = voteInputs[i].value;
                  break;
              }
          }
          // If no option is selected, inform the user.
          if (!selectedVote) {
              document.getElementById("feedback").innerHTML = "<span class='error'>Please select an option.</span>";
              return;
          }
          socket.emit("submit_vote", { vote: selectedVote });
        });

        // Listen for vote acknowledgement messages.
        socket.on("vote_ack", function(data) {
          if (data.status === "success") {
              document.getElementById("feedback").innerHTML = "<span class='feedback'>" + data.message + "</span>";
          } else {
              document.getElementById("feedback").innerHTML = "<span class='error'>" + data.message + "</span>";
          }
        });

        // Listen for vote total updates and update the DOM accordingly.
        socket.on("update_votes", function(data) {
          document.getElementById("yesTotal").textContent = data.yes;
          document.getElementById("noTotal").textContent = data.no;
          document.getElementById("maybeTotal").textContent = data.maybe;
        });
      });
    </script>
  </body>
</html>
"""

