#!/usr/bin/env python3

class News:
    def __init__(self, title, content):
        self.title = title
        self.content = content

    def __str__(self):
        return f"News: {self.title}"


class Author:
    def __init__(self, name, email):
        self.name = name
        self.email = email

    def __str__(self):
        return f"Author: {self.name}"


class AdminSite:
    def __init__(self):
        # The registry dictionary holds model class names as keys and model classes as values.
        self.registry = {}

    def register(self, model):
        """
        Registers a model class to the admin site.
        If the model is not a valid type or is already registered, handle accordingly.
        """
        try:
            # Check if the provided model is indeed a class.
            if not isinstance(model, type):
                raise TypeError("Only classes can be registered as models.")

            model_name = model.__name__

            # Check if the model is already registered.
            if model_name in self.registry:
                print(f"Model '{model_name}' is already registered.")
                return

            # Register the model.
            self.registry[model_name] = model
            print(f"Model '{model_name}' registered successfully.")

        except Exception as e:
            print(f"Error during registration of {model}: {e}")

    def get_registered_models(self):
        """
        Returns a list of the names of all registered models.
        """
        return list(self.registry.keys())


# Example usage:
if __name__ == '__main__':
