• Validates the year (must be > 0), month (must be between 1 and 12), and day (must be between 1 and the maximum allowed for the given month and year).  
• Provides setters (set_day, set_month, set_year) that perform validation and raise a ValueError with an appropriate message if an invalid value is provided.  
• Implements a __str__ method that returns the date in the “dd-mm-yyyy” format.  
• Implements an add_days method that adds a number of days to the date while taking into account month lengths and leap years.

Here is the complete code:

-------------------------------------------------
class Date:
    def __init__(self, day, month, year):
        # Set the year, month, and day sequentially.
        # Order is important because the valid range for day depends on the month and year.
        self.set_year(year)
        self.set_month(month)
        self.set_day(day)

    def __str__(self):
        # Returns the string representation in dd-mm-yyyy format.
        return f"{self.day:02d}-{self.month:02d}-{self.year}"

    def is_leap(self, year):
        # Returns True if the specified year is a leap year.
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def days_in_month(self, month, year):
        # Returns the number of days in the given month and year.
        if month == 2:
            return 29 if self.is_leap(year) else 28
        elif month in (1, 3, 5, 7, 8, 10, 12):
            return 31
        elif month in (4, 6, 9, 11):
            return 30
        else:
            # This condition should not occur due to earlier validation.
            raise ValueError("Invalid month provided.")

    def set_day(self, day):
        if not isinstance(day, int):
            raise ValueError("Day must be an integer.")
        # If month and year are already set, use them for proper day validation.
        max_day = 31
        if hasattr(self, "month") and hasattr(self, "year"):
            max_day = self.days_in_month(self.month, self.year)
        if 1 <= day <= max_day:
            self.day = day
        else:
            raise ValueError(f"Invalid day: {day}. Day must be between 1 and {max_day} for month {self.month} in year {self.year}.")

    def set_month(self, month):
        if not isinstance(month, int):
            raise ValueError("Month must be an integer.")
        if 1 <= month <= 12:
            self.month = month
        else:
            raise ValueError(f"Invalid month: {month}. Month must be between 1 and 12.")

    def set_year(self, year):
        if not isinstance(year, int):
            raise ValueError("Year must be an integer.")
        if year > 0:
            self.year = year
        else:
            raise ValueError(f"Invalid year: {year}. Year must be a positive integer.")

    def add_days(self, n):
        if not isinstance(n, int):
            raise ValueError("Number of days to add must be an integer.")
        if n < 0:
            raise ValueError("Number of days to add must be non-negative.")

        while n > 0:
            # Calculate remaining days in current month.
            days_remaining = self.days_in_month(self.month, self.year) - self.day
            if n <= days_remaining:
                self.day += n
                n = 0
            else:
                # Move to the first day of the next month.
                n -= (days_remaining + 1)
                self.day = 1
                if self.month == 12:
                    self.month = 1
                    self.year += 1
                else:
                    self.month += 1

# Example usage:
if __name__ == "__main__":
    try:
        d = Date(28, 2, 2020)
        print("Initial date:", d)  # Expected: 28-02-2020

        # Testing add_days with leap year:
        d.add_days(1)
        print("After adding 1 day:", d)  # Expected: 29-02-2020 (leap year)

