def extract_date(url: str):
    import re
    # Pattern to match /YYYY/MM/DD/ where MM and DD can be 1 or 2 digits.
    pattern = re.compile(r'/(\d{4})/(\d{1,2})/(\d{1,2})/')
    match = pattern.search(url)
    if match:
        year, month, day = match.groups()
        return (year, month, day)
    return None

# Example usage:
if __name__ == '__main__':
    print(extract_date("https://example.com/2023/03/15/article-title"))  # Expected: ('2023', '03', '15')
    print(extract_date("https://example.com/archive/1999/12"))  # Expected: None

