    album2 = Album("Bad", "1987-08-31", ["Pop", "Rock", "Funk"], "Follow-up to Thriller.")
    album1.setAlbumsSimilares([album2])
    album1.setPlaysCanciones({"Billie Jean": 500000000, "Beat It": 350000000})
