#!/usr/bin/env python3
import re

class Album:
    DATE_REGEX = r"^\d{4}-\d{2}-\d{2}$"

    def __init__(self, nombre, fechaPublicacion, generos=None, descripcion="", albumsSimilares=None, playsCanciones=None):
        # Validate nombre
        if not isinstance(nombre, str):
            raise TypeError("El nombre del album debe ser una cadena de texto.")
        self.nombre = nombre

        # Validate fechaPublicacion with regex (YYYY-MM-DD)
        if not isinstance(fechaPublicacion, str):
            raise TypeError("La fecha de publicación debe ser una cadena de texto en el formato 'YYYY-MM-DD'.")
        if not re.match(Album.DATE_REGEX, fechaPublicacion):
            raise ValueError("La fecha de publicación debe tener el formato 'YYYY-MM-DD'.")
        self.fechaPublicacion = fechaPublicacion

        # For generos, if not provided initialize as empty list
        if generos is None:
            self.generos = []
        else:
            if not isinstance(generos, list):
                raise TypeError("Los géneros deben proporcionarse como una lista de cadenas.")
            for gen in generos:
                if not isinstance(gen, str):
                    raise TypeError("Cada género debe ser una cadena de texto.")
            # Eliminate duplicates if any
            self.generos = list(dict.fromkeys(generos))

        # Validate descripcion is string.
        if not isinstance(descripcion, str):
            raise TypeError("La descripción debe ser una cadena de texto.")
        self.descripcion = descripcion

        # albumsSimilares is either provided or an empty list. Validate that all are Album instances.
        if albumsSimilares is None:
            self.albumsSimilares = []
        else:
            if not isinstance(albumsSimilares, list):
