            for album in albumsSimilares:
                if not isinstance(album, Album):
                    raise TypeError("Cada elemento de albumsSimilares debe ser una instancia de Album.")
            self.albumsSimilares = albumsSimilares

        # playsCanciones is either provided or an empty dictionary. Validate type.
        if playsCanciones is None:
            self.playsCanciones = {}
        else:
            if not isinstance(playsCanciones, dict):
