            for song, plays in playsCanciones.items():
                if not isinstance(song, str):
                    raise TypeError("El nombre de la canción debe ser una cadena de texto.")
                if not (isinstance(plays, int) and plays >= 0):
                    raise ValueError("El número de reproducciones para cada canción debe ser un entero no negativo.")
            self.playsCanciones = playsCanciones

    def agregarGenero(self, genero):
        """
        Agrega un nuevo género a la lista de géneros del álbum.
        Evita agregar géneros duplicados.
        """
        if not isinstance(genero, str):
            raise TypeError("El género debe ser una cadena de texto.")
        if genero not in self.generos:
            self.generos.append(genero)
        else:
            print(f"El género '{genero}' ya existe en la lista.")

    def getAlbumsSimilares(self):
        """
        Retorna la lista de álbumes similares.
        """
        return self.albumsSimilares

    def setAlbumsSimilares(self, albums):
        """
        Establece la lista de álbumes similares.
        albums debe ser una lista de instancias de Album.
        """
        if not isinstance(albums, list):
            raise TypeError("albumsSimilares debe ser una lista de instancias de Album.")
        for album in albums:
            if not isinstance(album, Album):
                raise TypeError("Cada elemento de la lista debe ser una instancia de Album.")
        self.albumsSimilares = albums

    def getPlaysCanciones(self):
        """
        Retorna el diccionario de reproducciones de canciones.
        """
        return self.playsCanciones

    def setPlaysCanciones(self, plays):
        """
        Establece el diccionario de reproducciones de canciones.
        Verifica que las claves sean cadenas y los valores enteros no negativos.
        """
        if not isinstance(plays, dict):
            raise TypeError("plays debe ser un diccionario con nombres de canciones y sus reproducciones.")
        for canción, count in plays.items():
            if not isinstance(canción, str):
                raise TypeError("El nombre de la canción debe ser una cadena de texto.")
            if not (isinstance(count, int) and count >= 0):
                raise ValueError("El número de reproducciones debe ser un entero no negativo.")
        self.playsCanciones = plays

