syntax = "proto3";

package calendar;

// The reminder message contains all the reminder fields.
message Reminder {
  string id = 1;
  string email = 2;
  string note = 3;
  string date_remind = 4; // ISO 8601 string format of date and time when the reminder should be sent.
  string date_note = 5;   // ISO 8601 string format for the note creation time.
}

// The status response returns a status code and optional message.
message ReminderResponse {
  bool success = 1;
  string message = 2;
}

// The calendar service definition.
service CalendarService {
  rpc RecieveData(Reminder) returns (ReminderResponse);
}
