# Global in-memory store for scheduled reminders.
# We use a priority queue sorted by the reminder time.
scheduled_reminders = queue.PriorityQueue()

# Regular expression for basic email validation.
EMAIL_REGEX = re.compile(r"[^@]+@[^@]+\.[^@]+")

# Dummy function to simulate an email sending service.
def send_email(email, note):
