        return False
    return True

# Dummy function representing an error handling service.
def report_error(error_message):
    # In production, you might push the error to an error handling service (e.g., Sentry).
    print(f"ERROR: {error_message}")

# The producer function that schedules a reminder.
def schedule_reminder(reminder):
    """
    Validates that the reminder time is in the future and then schedules the reminder.
    The reminder is added to a priority queue with its scheduled time as priority.
    """
    try:
        remind_time = datetime.fromisoformat(reminder.date_remind)
    except Exception as e:
        raise ValueError("Invalid date_remind format. Use ISO 8601 format.")

    now = datetime.now()
    if remind_time <= now:
        raise ValueError("The reminder time must be in the future.")
    # The PriorityQueue uses the first tuple element for priority.
    scheduled_reminders.put((remind_time, reminder))
    print(f"Reminder {reminder.id} scheduled for {reminder.date_remind}")
    return True

# The CalendarServicer that implements the RecieveData RPC.
class CalendarServicer(CalendarServiceServicer):
    def RecieveData(self, request, context):
        # Validate incoming reminder data.
        # Validate email format.
        if not EMAIL_REGEX.fullmatch(request.email):
            msg = "Invalid email format."
            print(msg)
            return ReminderResponse(success=False, message=msg)
        # Validate that required fields exist and dates are in the correct format.
        try:
            datetime.fromisoformat(request.date_remind)
            datetime.fromisoformat(request.date_note)
        except Exception:
            msg = "Invalid date format. Please use ISO 8601 format for date_remind and date_note."
            print(msg)
            return ReminderResponse(success=False, message=msg)

        # Try to schedule the reminder.
        try:
            schedule_reminder(request)
        except ValueError as ve:
            print(str(ve))
            return ReminderResponse(success=False, message=str(ve))
        except Exception as e:
            print(f"Unexpected error: {str(e)}")
            return ReminderResponse(success=False, message="Internal error during scheduling.")
        return ReminderResponse(success=True, message="Reminder scheduled successfully.")

# A background thread function that continuously checks the scheduled reminders and sends emails.
def reminder_dispatcher():
    while True:
        try:
            if scheduled_reminders.empty():
                # Sleep briefly if there is no reminder scheduled.
                time.sleep(1)
                continue
            # Peek at the next scheduled reminder.
            next_time, next_reminder = scheduled_reminders.queue[0]  # peek without removing
            now = datetime.now()
            if now >= next_time:
                # If it's time, remove the reminder and process it.
                _, reminder = scheduled_reminders.get()
                print(f"Time reached for reminder {reminder.id} scheduled at {reminder.date_remind}.")
                # Simulate email sending.
                if not send_email(reminder.email, reminder.note):
                    report_error(f"Failed to send reminder email for reminder id {reminder.id}.")
            else:
                # Sleep until the next reminder is due (or a short interval, whichever is shorter).
                sleep_time = (next_time - now).total_seconds()
                time.sleep(min(sleep_time, 1))
        except Exception as e:
            report_error(f"Error in reminder dispatcher: {str(e)}")
            time.sleep(1)

