    calendar_servicer = CalendarServicer()
    add_CalendarServiceServicer_to_server(calendar_servicer, server)
    server.add_insecure_port('[::]:50051')
    server.start()
    print("gRPC server started on port 50051.")

    # Start the reminder dispatcher thread.
    dispatcher_thread = threading.Thread(target=reminder_dispatcher, daemon=True)
    dispatcher_thread.start()
    print("Reminder dispatcher started.")

    try:
        # Keep the main thread alive to keep the server running.
        while True:
            time.sleep(86400)
    except KeyboardInterrupt:
        print("Shutting down server...")
        server.stop(0)

