• Read and validate the input parameters (ensuring the required fields exist)  
• Use Django’s ORM to create and save new objects (helping protect against SQL injection)  
• Return a JSON response indicating success (with details of the created object) or a suitable error message in case of missing parameters or invalid input.

Additionally, example test cases using Django’s TestCase are provided to verify that the views work as expected.

────────────────────────────
File: views.py
────────────────────────────

from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_http_methods
import json
from AppCoder.models import Curso, Entregable

@csrf_exempt
@require_http_methods(["POST"])
def curso(request):
    """
    Creates a new Curso object.
    Expects JSON body with 'nombre' and 'camada'.
    """
    try:
        data = json.loads(request.body)
    except json.JSONDecodeError:
        return JsonResponse({"error": "Invalid JSON"}, status=400)

    nombre = data.get("nombre")
    camada = data.get("camada")

    if not nombre or not camada:
        return JsonResponse({"error": "Missing required fields: 'nombre' and 'camada'"}, status=400)

    try:
        new_course = Curso(nombre=nombre, camada=camada)
        new_course.save()
        return JsonResponse({
            "success": True,
            "curso": {
                "id": new_course.id,
                "nombre": new_course.nombre,
                "camada": new_course.camada,
            }
        })
    except Exception as e:
        return JsonResponse({"error": str(e)}, status=500)

@csrf_exempt
@require_http_methods(["POST"])
def entregables(request):
    """
    Creates a new Entregable object.
    Expects JSON body with 'nombre' and 'fechaEntrega'.
    """
    try:
        data = json.loads(request.body)
    except json.JSONDecodeError:
        return JsonResponse({"error": "Invalid JSON"}, status=400)

    nombre = data.get("nombre")
    fechaEntrega = data.get("fechaEntrega")

    if not nombre or not fechaEntrega:
        return JsonResponse({"error": "Missing required fields: 'nombre' and 'fechaEntrega'"}, status=400)

    try:
        new_entregable = Entregable(nombre=nombre, fechaEntrega=fechaEntrega)
        new_entregable.save()
        return JsonResponse({
            "success": True,
            "entregable": {
                "id": new_entregable.id,
                "nombre": new_entregable.nombre,
                "fechaEntrega": new_entregable.fechaEntrega,
            }
        })
    except Exception as e:
        return JsonResponse({"error": str(e)}, status=500)

