Below are example tests using Django’s built‐in TestCase. These tests assume you have defined proper URL patterns for the views with the names "curso" and "entregables".

from django.urls import reverse
from django.test import TestCase
import json
from AppCoder.models import Curso, Entregable

class CursoViewTestCase(TestCase):
    def test_create_curso_success(self):
        url = reverse("curso")
        payload = {"nombre": "Computer Science", "camada": "2023"}
        response = self.client.post(url, data=json.dumps(payload), content_type="application/json")

        self.assertEqual(response.status_code, 200)
        json_response = response.json()
        self.assertTrue(json_response.get("success"))
        self.assertEqual(json_response["curso"]["nombre"], "Computer Science")
        self.assertEqual(json_response["curso"]["camada"], "2023")
        self.assertEqual(Curso.objects.count(), 1)

    def test_create_curso_missing_fields(self):
        url = reverse("curso")
        payload = {"nombre": "Mathematics"}  # Missing 'camada'
        response = self.client.post(url, data=json.dumps(payload), content_type="application/json")

        self.assertEqual(response.status_code, 400)
        json_response = response.json()
        self.assertIn("error", json_response)

class EntregableViewTestCase(TestCase):
    def test_create_entregable_success(self):
        url = reverse("entregables")
        payload = {"nombre": "Assignment 1", "fechaEntrega": "2023-12-31"}
        response = self.client.post(url, data=json.dumps(payload), content_type="application/json")

        self.assertEqual(response.status_code, 200)
        json_response = response.json()
        self.assertTrue(json_response.get("success"))
        self.assertEqual(json_response["entregable"]["nombre"], "Assignment 1")
        self.assertEqual(json_response["entregable"]["fechaEntrega"], "2023-12-31")
        self.assertEqual(Entregable.objects.count(), 1)

    def test_create_entregable_missing_fields(self):
        url = reverse("entregables")
        payload = {"nombre": "Assignment 2"}  # Missing 'fechaEntrega'
        response = self.client.post(url, data=json.dumps(payload), content_type="application/json")

        self.assertEqual(response.status_code, 400)
        json_response = response.json()
        self.assertIn("error", json_response)

