Below is one example solution written in Node.js using Express and Mongoose. The following implementation covers local and Google OAuth2 user authentication, JWT token generation, real‐time monitoring of MongoDB collections via change streams, permission checking based on database rules, role determination based on group membership, and proper error handling. You’ll also find examples of unit testing for authentication and authorization functions. (Note that in a production system you would want to add additional error handling, security improvements, logging, environment‐based configuration, and so on.) 

──────────────────────────────
1. Project Structure

For clarity, the project structure is organized as follows:

    project/
    ├── app.js
    ├── config/
    │   ├── db.js
    │   └── passport.js
    ├── controllers/
    │   └── authController.js
    ├── middleware/
    │   └── authMiddleware.js
    ├── models/
    │   ├── Permission.js
    │   └── User.js
    ├── routes/
    │   └── authRoutes.js
    ├── tests/
    │   └── auth.test.js
    ├── package.json
    └── .env

──────────────────────────────
2. Environment Variables (.env)

Keep secret keys and configuration in an environment file. For example:

-------------------------------------------------
PORT=3000
MONGODB_URI=mongodb://localhost:27017/authDemo
JWT_SECRET=ReplaceThisWithAStrongKey
JWT_ACCESS_EXPIRATION=15m
JWT_REFRESH_EXPIRATION=7d

GOOGLE_CLIENT_ID=your_google_client_id
GOOGLE_CLIENT_SECRET=your_google_client_secret
GOOGLE_CALLBACK_URL=http://localhost:3000/auth/google/callback
-------------------------------------------------

──────────────────────────────
3. Database Connection (config/db.js)

This file connects to MongoDB and exports the connection for use in change streams.

-------------------------------------------------
const mongoose = require('mongoose');

mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

const db = mongoose.connection;
db.on('error', console.error.bind(console, 'MongoDB connection error:'));

module.exports = db;
-------------------------------------------------

──────────────────────────────
4. User and Permission Models (models/User.js and models/Permission.js)

User Model – stores the user credentials, groups, and additional details.

-------------------------------------------------
// models/User.js
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');

const UserSchema = new mongoose.Schema({
  email: { type: String, unique: true, index: true },
  password: { type: String }, // hashed with bcrypt
  googleId: { type: String },
  groups: [String], // used for role determination
});

// Pre-save hook to hash the password if modified
UserSchema.pre('save', async function(next) {
  if (this.isModified('password')) {
    const saltRounds = 10;
    this.password = await bcrypt.hash(this.password, saltRounds);
  }
  next();
});

UserSchema.methods.comparePassword = async function(password) {
  return bcrypt.compare(password, this.password);
};

module.exports = mongoose.model('User', UserSchema);
-------------------------------------------------

Permission Model – holds resource names and rules associated with users or roles.

-------------------------------------------------
// models/Permission.js
const mongoose = require('mongoose');

const PermissionSchema = new mongoose.Schema({
  resource: { type: String, required: true },
  allowedUsers: [String],   // array of emails or user IDs
  allowedGroups: [String],  // groups/roles that can access the resource
  adminOnly: { type: Boolean, default: false } // if true, only admins can modify
});

// Create indexes to optimize queries
PermissionSchema.index({ resource: 1 });

module.exports = mongoose.model('Permission', PermissionSchema);
-------------------------------------------------

──────────────────────────────
5. Google OAuth2 Passport Strategy (config/passport.js)

Set up Passport to use Google OAuth2. In this case, we use the google-oauth20 strategy.

-------------------------------------------------
const passport = require('passport');
const GoogleStrategy = require('passport-google-oauth20').Strategy;
const User = require('../models/User');

passport.use(new GoogleStrategy({
  clientID: process.env.GOOGLE_CLIENT_ID,
  clientSecret: process.env.GOOGLE_CLIENT_SECRET,
  callbackURL: process.env.GOOGLE_CALLBACK_URL,
},
async (accessToken, refreshToken, profile, done) => {
  try {
    // Find or create the user based on the profile info
    let user = await User.findOne({ googleId: profile.id });
    if (!user) {
      user = new User({
        email: profile.emails[0].value,
        googleId: profile.id,
        // You could assign default groups here if needed.
      });
      await user.save();
    }
    return done(null, user);
  } catch (error) {
    return done(error);
  }
}));

// Serialize and de-serialize for session support (if needed)
passport.serializeUser((user, done) => {
  done(null, user.id);
});
passport.deserializeUser(async (id, done) => {
  try {
    const user = await User.findById(id);
    done(null, user);
  } catch (error) {
    done(error);
  }
});

module.exports = passport;
-------------------------------------------------

──────────────────────────────
6. Auth Controller and JWT Generation (controllers/authController.js)

This controller handles login, JWT token generation (access and refresh tokens), and triggers error feedback.

-------------------------------------------------
const jwt = require('jsonwebtoken');
const User = require('../models/User');

function generateTokens(user) {
  const accessToken = jwt.sign(
    { id: user._id, email: user.email, groups: user.groups },
    process.env.JWT_SECRET,
    { expiresIn: process.env.JWT_ACCESS_EXPIRATION }
  );

  const refreshToken = jwt.sign(
    { id: user._id },
    process.env.JWT_SECRET,
    { expiresIn: process.env.JWT_REFRESH_EXPIRATION }
  );
  return { accessToken, refreshToken };
}

exports.localLogin = async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await User.findOne({ email });
    if (!user) {
      return res.status(401).json({ message: 'Authentication failed: user not found.' });
    }

    const isMatch = await user.comparePassword(password);
    if (!isMatch) {
      return res.status(401).json({ message: 'Authentication failed: invalid password.' });
    }

    const tokens = generateTokens(user);
    return res.json(tokens);
  } catch (error) {
    console.error('Local Login Error:', error);
    return res.status(500).json({ message: 'Internal server error' });
  }
};

exports.googleLogin = (req, res) => {
  // This function is called after the Google OAuth callback.
  const tokens = generateTokens(req.user);
  // You might redirect the user or simply send a JSON response.
  res.json(tokens);
};

exports.refreshToken = async (req, res) => {
  const { refreshToken } = req.body;
  if (!refreshToken) {
    return res.status(400).json({ message: 'Refresh Token is required.' });
  }
  try {
    const payload = jwt.verify(refreshToken, process.env.JWT_SECRET);
    const user = await User.findById(payload.id);
    if (!user) {
      return res.status(401).json({ message: 'User not found.' });
    }
    const tokens = generateTokens(user);
    return res.json(tokens);
  } catch (error) {
    return res.status(401).json({ message: 'Invalid or expired refresh token.' });
  }
};
-------------------------------------------------

──────────────────────────────
7. Authorization Middleware (middleware/authMiddleware.js)

This middleware checks the JWT token, extracts user details, and can be extended to check permissions for specific resources.

-------------------------------------------------
const jwt = require('jsonwebtoken');
const Permission = require('../models/Permission');

// Middleware to authenticate JWT token
exports.authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization']; 
  const token = authHeader && authHeader.split(' ')[1];
  if (token == null) return res.status(401).json({ message: 'Access token required' });

  jwt.verify(token, process.env.JWT_SECRET, (err, userPayload) => {
    if (err) return res.status(403).json({ message: 'Invalid or expired token' });
    req.user = userPayload;
    next();
  });
};

// Middleware to check if user has permission to access a given resource (pvname)
exports.authorizeResourceAccess = (resourceName) => {
  return async (req, res, next) => {
    try {
      const permission = await Permission.findOne({ resource: resourceName });
      if (!permission) {
        // If no permission is defined, default deny.
        return res.status(403).json({ message: 'Access denied: no permission setting.' });
      }
      const { email, groups } = req.user;
      const userHasExplicitAccess = permission.allowedUsers.includes(email);
      const groupAccess = permission.allowedGroups.some(group => groups.includes(group));
      if (userHasExplicitAccess || groupAccess) {
        return next();
      }
      return res.status(403).json({ message: 'Access denied.' });
    } catch (error) {
      console.error('Permission verification error:', error);
      return res.status(500).json({ message: 'Internal server error' });
    }
  };
};

// Middleware to check for admin privileges based on a user group (e.g., “admin” group).
exports.requireAdmin = (req, res, next) => {
  if (req.user && req.user.groups && req.user.groups.includes('admin')) {
    return next();
  }
  return res.status(403).json({ message: 'Admin privileges required' });
};
-------------------------------------------------

──────────────────────────────
8. Real-time MongoDB Change Stream Monitoring

In the main app file (app.js), set up change streams to update your application’s internal cache or state when there are changes to “User” or “Permission” collections.

-------------------------------------------------
const express = require('express');
const passport = require('./config/passport');
const db = require('./config/db');
const User = require('./models/User');
const Permission = require('./models/Permission');

const app = express();
app.use(express.json());
app.use(passport.initialize());

// Example: Set up change stream monitors for User and Permission collections
db.once('open', () => {
  console.log('Connected to MongoDB, setting up change streams...');

  const userChangeStream = User.watch();
  userChangeStream.on('change', (change) => {
    console.log('User Collection Change Detected:', change);
    // Update internal state or cache here as needed.
  });

  const permissionChangeStream = Permission.watch();
  permissionChangeStream.on('change', (change) => {
    console.log('Permission Collection Change Detected:', change);
    // Update internal state or cache here as needed.
  });
});
-------------------------------------------------

──────────────────────────────
9. Route Definitions (routes/authRoutes.js)

Define endpoints for login, Google OAuth callbacks, token refresh, etc.

-------------------------------------------------
const express = require('express');
const router = express.Router();
const authController = require('../controllers/authController');
const { authenticateToken, authorizeResourceAccess, requireAdmin } = require('../middleware/authMiddleware');
const passport = require('passport');

// Route for local authentication login
router.post('/login', authController.localLogin);

// Route for token refresh
router.post('/refresh-token', authController.refreshToken);

// Google OAuth routes
router.get('/google', passport.authenticate('google', { scope: ['profile', 'email'] }));
router.get('/google/callback', passport.authenticate('google', { session: false }), authController.googleLogin);

// Protected resource example route:
router.get('/resource/:pvname', authenticateToken, (req, res, next) => {
  // Dynamically generate middleware based on the resource parameter.
  authorizeResourceAccess(req.params.pvname)(req, res, next);
}, (req, res) => {
  res.json({ message: `Access granted to resource ${req.params.pvname}` });
});

// Admin only endpoint example
router.get('/admin', authenticateToken, requireAdmin, (req, res) => {
  res.json({ message: 'Welcome, admin!' });
});

module.exports = router;
-------------------------------------------------

──────────────────────────────
10. Main Application File (app.js)

Combine all components to start the server.

-------------------------------------------------
require('dotenv').config();
const express = require('express');
const passport = require('./config/passport'); // initializes passport strategies
const authRoutes = require('./routes/authRoutes');
const app = express();

app.use(express.json());
app.use(passport.initialize());

app.use('/auth', authRoutes);

// Default route for testing
app.get('/', (req, res) => {
  res.send('User Authentication and Authorization System is running');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
-------------------------------------------------

──────────────────────────────
11. Unit Tests (tests/auth.test.js)

Here’s an example using Mocha and Chai for testing authentication functions. In production, you might use a tool like Jest.

-------------------------------------------------
const chai = require('chai');
const chaiHttp = require('chai-http');
const app = require('../app'); // assuming your app exports the Express app
const User = require('../models/User');
const mongoose = require('mongoose');

chai.use(chaiHttp);
const { expect } = chai;

describe('Authentication API', () => {
  before(async () => {
    // Connect to test database or setup mocks
    await mongoose.connect(process.env.MONGODB_URI, { useNewUrlParser: true, useUnifiedTopology: true });
    // Optionally, clear the test database
    await User.deleteMany({});
  });

  after(async () => {
    await mongoose.connection.close();
  });

  describe('Local Login', () => {
    let testUser;
    before(async () => {
      // Create a test user
      testUser = new User({ email: 'test@example.com', password: 'Test@1234', groups: ['user'] });
      await testUser.save();
    });

    it('should authenticate with valid credentials', (done) => {
      chai.request(app)
        .post('/auth/login')
        .send({ email: 'test@example.com', password: 'Test@1234' })
        .end((err, res) => {
          expect(res).to.have.status(200);
          expect(res.body).to.have.property('accessToken');
          expect(res.body).to.have.property('refreshToken');
          done();
        });
    });

    it('should reject invalid password', (done) => {
      chai.request(app)
        .post('/auth/login')
        .send({ email: 'test@example.com', password: 'wrongpassword' })
        .end((err, res) => {
          expect(res).to.have.status(401);
          expect(res.body).to.have.property('message');
          done();
        });
    });
  });
});
-------------------------------------------------

──────────────────────────────
12. Summary

This implementation provides:

• Local user authentication with bcrypt-based password hashing and verification.
• Google OAuth2 integration using Passport.
• JWT-based access and refresh token generation.
• Real-time monitoring of user and permission changes using MongoDB change streams.
• Permission checks on routed resources using middleware.
• Role determination through group membership (e.g., the “admin” group).
• Clear error handling and logging for troubleshooting.
• Unit tests for authentication endpoints.

This design is extendable—you can add additional authorization rules, enhance caching for permission checks, or refine error handling/logging as your application grows.

By following this example, you can build a secure, efficient authentication and authorization system integrating MongoDB and Google OAuth2.

