import csv

def main():
    try:
        with open("people.csv", mode="r", newline='') as file:
            reader = csv.reader(file)

            # Skip the header row
            next(reader, None)

            for row in reader:
                if len(row) != 3:
                    continue  # Skip any malformed rows
                name, age_str, occupation = row
                try:
                    age = int(age_str)
                except ValueError:
                    print(f"Could not convert age '{age_str}' for {name} to an integer. Skipping.")
                    continue
                print(f"Hello, {name}! You are {age} years old and work as a {occupation}.")
    except FileNotFoundError:
        print("Error: The file 'people.csv' was not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

