def evaluate_operations(s):
    # Remove leading/trailing spaces and split the string by whitespace.
    tokens = s.strip().split()

    # Use a list to simulate the stack.
    stack = []

    # Process each token.
    for token in tokens:
        if token == 'Z':
            # If stack is not empty, pop the last element.
            if stack:
                stack.pop()
        else:
            # Convert the token to an integer and push onto the stack.
            # Assuming valid input as per specification.
            try:
                number = int(token)
                stack.append(number)
            except ValueError:
                # If conversion fails, ignore this token or handle error as needed.
                # For this implementation, we'll simply pass.
                continue

    # Return the sum of the numbers left in the stack.
    return sum(stack)


