Below is one complete Python example that uses PySimpleGUI for a simple banking interface along with a basic “backend” bank‐class and unit tests. In this example the bank “database” is stored in a dictionary (so that the application remains simple) and passwords are hashed with SHA‑256. You can run the application normally to see the graphical interface or run the unit tests (for example, by invoking the script with a “test” argument).

IMPORTANT: This demo code is for educational purposes and is not production‐ready.

────────────────────────────
Code (bank_app.py):
────────────────────────────
#!/usr/bin/env python3
import PySimpleGUI as sg
import re
import hashlib
import unittest

# -------------------------------
# Bank Back-End and Validation
# -------------------------------

class Bank:
    def __init__(self):
        # Store accounts using the account number as the key.
        # Each account is a dict with keys:
        #  "account_number", "holder_name", "hashed_password", "initial_deposit", "credit_limit", "balance"
        self.accounts = {}

    def _hash_password(self, password):
        return hashlib.sha256(password.encode()).hexdigest()

    def validate_account_number(self, account_number):
        # For example: must be digits and at least 1 digit long.
        if re.fullmatch(r"\d+", account_number):
            return True
        return False

    def validate_holder_name(self, name):
        # Name must only contain letters and spaces (at least one character)
        if re.fullmatch(r"[A-Za-z ]+", name) and name.strip() != "":
            return True
        return False

    def validate_amount(self, amount):
        try:
            a = float(amount)
            # amount must be nonnegative; you might add further constraints
            if a >= 0:
                return True
        except ValueError:
            return False
        return False

    def open_account(self, account_number, holder_name, password, initial_deposit, credit_limit):
        # Validate inputs
        if not self.validate_account_number(account_number):
            return (False, "Invalid account number format.")
        if not self.validate_holder_name(holder_name):
            return (False, "Invalid account holder name.")
        if not self.validate_amount(initial_deposit):
            return (False, "Invalid initial deposit.")
        if not self.validate_amount(credit_limit):
            return (False, "Invalid credit limit amount.")
        if account_number in self.accounts:
            return (False, "Account already exists.")

        hashed_pwd = self._hash_password(password)
        # For demonstration, we set a fixed balance of $2,000.00
        account_data = {
            "account_number": account_number,
            "holder_name": holder_name,
            "hashed_password": hashed_pwd,
            "initial_deposit": float(initial_deposit),
            "credit_limit": float(credit_limit),
            "balance": 2000.00
        }
        self.accounts[account_number] = account_data
        return (True, "Account opened successfully.")

    def access_account(self, account_number, holder_name, password):
        if account_number not in self.accounts:
            return (False, "Account not found.", None)
        account = self.accounts[account_number]
        if account["holder_name"] != holder_name:
            return (False, "Account holder name does not match.", None)
        hashed_pwd = self._hash_password(password)
        if account["hashed_password"] != hashed_pwd:
            return (False, "Incorrect password.", None)
        return (True, "Access granted.", account)

    def view_balance(self, account):
        # For demonstration, balance is fixed (or coming from the account data)
        bal = account.get("balance", 0)
        return (True, f"Your account balance is ${bal:,.2f}")

    def make_transfer(self, account, bank_code, target_account_number, target_name, transfer_amount):
        # Validate transfer inputs
        if not self.validate_account_number(target_account_number):
            return (False, "Invalid target account number.")
        if not self.validate_holder_name(target_name):
            return (False, "Invalid target account holder name.")
        if not self.validate_amount(transfer_amount):
            return (False, "Invalid transfer amount.")

        amount = float(transfer_amount)
        if amount > account["balance"]:
            return (False, "Transfer amount exceeds available balance.")

        # For simplicity we assume the transfer is accepted
        # In a real scenario, this would contact the target bank. Here we simply subtract from our demo balance.
        account["balance"] -= amount
        return (True, f"Transferred ${amount:,.2f} to {target_name} (Account: {target_account_number}, Bank: {bank_code}).")

    def request_credit_limit(self, account, new_credit_limit):
        if not self.validate_amount(new_credit_limit):
            return (False, "Invalid credit limit.")
        new_limit = float(new_credit_limit)
        account["credit_limit"] = new_limit
        return (True, f"New credit limit of ${new_limit:,.2f} has been set.")

# -------------------------------
# PySimpleGUI Banking Interface
# -------------------------------

bank = Bank()

def main_window():
    sg.theme("LightBlue")
    layout = [
        [sg.Text("Welcome to Simple Banking App")],
        [sg.Button("Open Account", key="open"), sg.Button("Access Account", key="access"), sg.Button("Exit", key="exit")]
    ]
    return sg.Window("Banking App", layout, finalize=True)

def open_account_window():
    layout = [
        [sg.Text("Open a New Account")],
        [sg.Text("Account Number:"), sg.Input(key="account_number")],
        [sg.Text("Account Holder's Name:"), sg.Input(key="holder_name")],
        [sg.Text("Password:"), sg.Input(password_char="*", key="password")],
        [sg.Text("Initial Deposit:"), sg.Input(key="initial_deposit")],
        [sg.Text("Credit Limit:"), sg.Input(key="credit_limit")],
        [sg.Button("Submit"), sg.Button("Cancel")]
    ]
    return sg.Window("Open Account", layout, modal=True, finalize=True)

def access_account_window():
    layout = [
        [sg.Text("Access Existing Account")],
        [sg.Text("Account Number:"), sg.Input(key="account_number")],
        [sg.Text("Account Holder's Name:"), sg.Input(key="holder_name")],
        [sg.Text("Password:"), sg.Input(password_char="*", key="password")],
        [sg.Button("Login"), sg.Button("Cancel")]
    ]
    return sg.Window("Access Account", layout, modal=True, finalize=True)

def account_operations_window(account):
    layout = [
        [sg.Text(f"Welcome {account['holder_name']} (Account: {account['account_number']})")],
        [sg.Button("View Balance", key="balance")],
        [sg.Button("Make Transfer", key="transfer")],
        [sg.Button("Request New Credit Limit", key="credit")],
        [sg.Button("Logout", key="logout")]
    ]
    return sg.Window("Account Operations", layout, modal=True, finalize=True)

def transfer_window():
    layout = [
        [sg.Text("Make a Transfer")],
        [sg.Text("Bank Code:"), sg.Input(key="bank_code")],
        [sg.Text("Target Account Number:"), sg.Input(key="target_account_number")],
        [sg.Text("Target Account Holder's Name:"), sg.Input(key="target_name")],
        [sg.Text("Transfer Amount:"), sg.Input(key="transfer_amount")],
        [sg.Button("Submit"), sg.Button("Cancel")]
    ]
    return sg.Window("Transfer Funds", layout, modal=True, finalize=True)

def credit_limit_window():
    layout = [
        [sg.Text("Request New Credit Limit")],
        [sg.Text("New Credit Limit:"), sg.Input(key="new_limit")],
        [sg.Button("Submit"), sg.Button("Cancel")]
    ]
    return sg.Window("Credit Limit", layout, modal=True, finalize=True)

# -------------------------------
# GUI Event Loop
# -------------------------------
def run_app():
    window_main = main_window()
    current_account = None
    window_ops = None

    while True:
        window, event, values = sg.read_all_windows()
        if event == sg.WINDOW_CLOSED or event == "exit":
            window.close()
            if window == window_main:
                break
        # -------- Main Window Buttons --------
        if window == window_main:
            if event == "open":
                window_open = open_account_window()
            elif event == "access":
                window_access = access_account_window()
        # -------- Open Account Window --------
        if window.Title == "Open Account":
            if event == "Cancel" or event == sg.WINDOW_CLOSED:
                window.close()
            elif event == "Submit":
                ac_num = values["account_number"].strip()
                holder = values["holder_name"].strip()
                pwd = values["password"]
                init_dep = values["initial_deposit"].strip()
                credit_lim = values["credit_limit"].strip()
                success, msg = bank.open_account(ac_num, holder, pwd, init_dep, credit_lim)
                sg.popup(msg)
                if success:
                    window.close()
        # -------- Access Account Window --------
        if window.Title == "Access Account":
            if event == "Cancel" or event == sg.WINDOW_CLOSED:
                window.close()
            elif event == "Login":
                ac_num = values["account_number"].strip()
                holder = values["holder_name"].strip()
                pwd = values["password"]
                success, msg, account = bank.access_account(ac_num, holder, pwd)
                sg.popup(msg)
                if success:
                    current_account = account
                    window_ops = account_operations_window(current_account)
                    window.close()  # close access window
        # -------- Account Operations Window --------
        if window.Title == "Account Operations":
            if event == "logout" or event == sg.WINDOW_CLOSED:
                window.close()
                current_account = None
            elif event == "balance":
                success, msg = bank.view_balance(current_account)
                sg.popup(msg)
            elif event == "transfer":
                window_transfer = transfer_window()
            elif event == "credit":
                window_credit = credit_limit_window()
        # -------- Transfer Window --------
        if window.Title == "Transfer Funds":
            if event == "Cancel" or event == sg.WINDOW_CLOSED:
                window.close()
            elif event == "Submit":
                bank_code = values["bank_code"].strip()
                target_acc = values["target_account_number"].strip()
                target_name = values["target_name"].strip()
                transfer_amt = values["transfer_amount"].strip()
                success, msg = bank.make_transfer(current_account, bank_code, target_acc, target_name, transfer_amt)
                sg.popup(msg)
                if success:
                    window.close()
        # -------- Credit Limit Window --------
        if window.Title == "Credit Limit":
            if event == "Cancel" or event == sg.WINDOW_CLOSED:
                window.close()
            elif event == "Submit":
                new_lim = values["new_limit"].strip()
                success, msg = bank.request_credit_limit(current_account, new_lim)
                sg.popup(msg)
                if success:
                    window.close()

    sg.close_all_windows()


