class TestBankOperations(unittest.TestCase):
    def setUp(self):
        # Create a new bank instance for every test.
        self.bank = Bank()
        # Create an account that will be useful for testing.
        res, msg = self.bank.open_account("123456", "Alice Smith", "securepwd", "500", "1000")
        self.assertTrue(res, msg)

    # Test open_account validations
    def test_open_account_invalid_number(self):
        res, msg = self.bank.open_account("abc", "Bob Jones", "pass", "100", "500")
        self.assertFalse(res)
        self.assertEqual(msg, "Invalid account number format.")

    def test_open_account_invalid_name(self):
        res, msg = self.bank.open_account("654321", "Bob123", "pass", "100", "500")
        self.assertFalse(res)
        self.assertEqual(msg, "Invalid account holder name.")

    def test_open_account_invalid_deposit(self):
        res, msg = self.bank.open_account("654321", "Bob Jones", "pass", "invalid", "500")
        self.assertFalse(res)
        self.assertEqual(msg, "Invalid initial deposit.")

    def test_open_account_duplicate(self):
        res, msg = self.bank.open_account("123456", "Alice Smith", "anotherpwd", "500", "1000")
        self.assertFalse(res)
        self.assertEqual(msg, "Account already exists.")

    # Test account access
    def test_access_account_wrong_password(self):
        success, msg, account = self.bank.access_account("123456", "Alice Smith", "wrongpwd")
        self.assertFalse(success)
        self.assertEqual(msg, "Incorrect password.")

    def test_access_account_wrong_name(self):
        success, msg, account = self.bank.access_account("123456", "Alice", "securepwd")
        self.assertFalse(success)
        self.assertEqual(msg, "Account holder name does not match.")

    def test_access_account_success(self):
        success, msg, account = self.bank.access_account("123456", "Alice Smith", "securepwd")
        self.assertTrue(success)
        self.assertEqual(msg, "Access granted.")
        self.assertIsNotNone(account)

    # Test viewing balance
    def test_view_balance(self):
        success, msg = self.bank.view_balance(self.bank.accounts["123456"])
        self.assertTrue(success)
        self.assertIn("$2,000.00", msg)

    # Test transfer (with sufficient funds)
    def test_make_transfer_success(self):
        account = self.bank.accounts["123456"]
        success, msg = self.bank.make_transfer(account, "001", "789012", "Charlie Brown", "1000")
        self.assertTrue(success)
        # Balance should be reduced by 1000: from 2000 -> 1000 now.
        self.assertAlmostEqual(account["balance"], 1000.00)

    # Test transfer amount exceeding balance
    def test_make_transfer_insufficient_funds(self):
        account = self.bank.accounts["123456"]
        success, msg = self.bank.make_transfer(account, "001", "789012", "Charlie Brown", "3000")
        self.assertFalse(success)
        self.assertEqual(msg, "Transfer amount exceeds available balance.")

    # Test credit limit request
    def test_request_credit_limit(self):
        account = self.bank.accounts["123456"]
        success, msg = self.bank.request_credit_limit(account, "2000")
        self.assertTrue(success)
        self.assertEqual(account["credit_limit"], 2000.0)

