import os
import requests

def post_message_to_slack_channel(channel_id, message):
    """
    Posts a message to a specified Slack channel using the Slack API.

    Args:
        channel_id (str): The ID of the Slack channel.
        message (str): The text message to be posted.

    Returns:
        dict: A dictionary containing the Slack API response. On success, includes a field indicating success.
              On error, includes an 'error' key with an appropriate error message.
    """

    # Validate parameters: they must be non-empty strings.
    if not isinstance(channel_id, str) or not channel_id.strip():
        return {"success": False, "error": "Invalid channel_id. It must be a non-empty string."}

    if not isinstance(message, str) or not message.strip():
        return {"success": False, "error": "Invalid message. It must be a non-empty string."}

    # Retrieve the Slack bot token from environment variables.
    slack_token = os.environ.get("SLACK_BOT_TOKEN")
    if not slack_token:
        return {"success": False, "error": "SLACK_BOT_TOKEN environment variable not found."}

    # Build the API endpoint and header.
    url = "https://slack.com/api/chat.postMessage"
    headers = {
        "Content-Type": "application/json;charset=utf-8",
        "Authorization": f"Bearer {slack_token}"
    }

    # Construct the payload with the channel ID and the message text.
    payload = {
        "channel": channel_id,
        "text": message
    }

    try:
        # Execute the HTTP POST request to Slack.
        response = requests.post(url, json=payload, headers=headers, timeout=10)
        response.raise_for_status()  # Raise an error for bad HTTP statuses

        # Parse the response JSON.
        response_data = response.json()

        # Check if the Slack API indicates success.
        if response_data.get("ok"):
            return {"success": True, "data": response_data}
        else:
            # Slack API returned an error.
            error_msg = response_data.get("error", "Unknown error from Slack API.")
            return {"success": False, "error": error_msg, "data": response_data}

    except requests.exceptions.RequestException as e:
        # Catch exceptions related to the HTTP request.
        return {"success": False, "error": f"RequestException occurred: {str(e)}"}
    except ValueError:
        # If response JSON parsing fails.
        return {"success": False, "error": "Failed to parse JSON response from Slack."}
    except Exception as e:
        # Catch any other unexpected exceptions.
        return {"success": False, "error": f"An unexpected error occurred: {str(e)}"}

# Example usage:
# result = post_message_to_slack_channel("C1234567890", "Hello Slack!")
