Below is an example Python script that fulfills the requirements. Save this code as (for example) change_permissions.py and run it using Python, passing the root directory as an argument.

-------------------------------------------------
#!/usr/bin/env python3
import os
import sys
import stat

def change_permissions(root_dir):
    # Check if the specified root_dir exists and is a directory
    if not os.path.isdir(root_dir):
        print(f"Error: The specified path '{root_dir}' is not a directory or does not exist.")
        sys.exit(1)

    # Use os.walk to walk through directory tree
    for dirpath, dirnames, filenames in os.walk(root_dir):
        # Change permissions for the current directory
        try:
            # Set directory permission to 755 (owner: rwx, group: rx, others: rx)
            os.chmod(dirpath, 0o755)
        except Exception as e:
            print(f"Failed to change permissions for directory '{dirpath}': {e}")

        # Change permissions for all subdirectories (the walk will reach these later, but we can change here too)
        for dirname in dirnames:
            directory = os.path.join(dirpath, dirname)
            try:
                os.chmod(directory, 0o755)
            except Exception as e:
                print(f"Failed to change permissions for directory '{directory}': {e}")

        # Change permissions for all files in the current directory
        for filename in filenames:
            filepath = os.path.join(dirpath, filename)
            try:
                # Set file permission to 666 (r/w for owner, group, others)
                os.chmod(filepath, 0o666)
            except Exception as e:
                print(f"Failed to change permissions for file '{filepath}': {e}")

    # Confirmation message
    print("Permissions successfully updated for all directories and files.")

def main():
    if len(sys.argv) != 2:
        print("Usage: python change_permissions.py <root_directory>")
        sys.exit(1)

    root_dir = sys.argv[1]
    change_permissions(root_dir)

if __name__ == "__main__":
    main()
-------------------------------------------------

