Below is one example implementation in Python. In this design each layer class (Input, Convolution, Pooling, FullConnection) is responsible for:

• Converting its parameters to a dictionary (via its to_dict method).  
• Re‐instantiating itself from a dictionary (via its class method from_dict), raising a ValueError if required fields are missing.  
• Computing its “output shape” given its initialization parameters. (For some layers the output shape is computed from an “input_shape” stored with the layer.)  
• Reporting its “output size” (for example, the total number of neurons produced, computed as the product of dimensions in the output shape or simply a 1D count).

A helper function, layer_from_dict, selects the appropriate layer subclass based on the “type” field in the serialized dictionary. Unit tests with the built–in unittest module then verify that each layer can be serialized to a dictionary and then deserialized back into an equivalent layer object.

Below is the complete code:

------------------------------------------------------------
#!/usr/bin/env python3
"""
Neural network layer serialization/deserialization system.
"""

import math
import unittest


# -------------------------- Layer Classes --------------------------

class Input:
    def __init__(self, shape):
        # shape is a tuple, e.g. (height, width, channels)
        self.shape = shape

    def to_dict(self):
        return {
            "type": "Input",
            "shape": self.shape,
        }

    @classmethod
    def from_dict(cls, d):
        if "shape" not in d:
            raise ValueError("Missing parameter 'shape' for Input layer")
        return cls(tuple(d["shape"]))  # Ensure tuple

    def get_output_shape(self):
        return self.shape

    def get_output_size(self):
        prod = 1
        for dim in self.shape:
            prod *= dim
        return prod

    def __eq__(self, other):
        return isinstance(other, Input) and self.shape == other.shape

    def __repr__(self):
        return f"Input(shape={self.shape})"


class Convolution:
    def __init__(self, num_filters, kernel_size, stride, padding, input_shape):
        # num_filters: int
        # kernel_size, stride, padding: tuples or ints convertible to tuples
        # input_shape: (height, width, channels)
        self.num_filters = num_filters
        self.kernel_size = kernel_size if isinstance(kernel_size, tuple) else (kernel_size, kernel_size)
        self.stride = stride if isinstance(stride, tuple) else (stride, stride)
        self.padding = padding if isinstance(padding, tuple) else (padding, padding)
        self.input_shape = input_shape

    def to_dict(self):
        return {
            "type": "Convolution",
            "num_filters": self.num_filters,
            "kernel_size": self.kernel_size,
            "stride": self.stride,
            "padding": self.padding,
            "input_shape": self.input_shape,
        }

    @classmethod
    def from_dict(cls, d):
        required = ["num_filters", "kernel_size", "stride", "padding", "input_shape"]
        for key in required:
            if key not in d:
                raise ValueError(f"Missing parameter '{key}' for Convolution layer")
        return cls(
            num_filters=d["num_filters"],
            kernel_size=tuple(d["kernel_size"]),
            stride=tuple(d["stride"]),
            padding=tuple(d["padding"]),
            input_shape=tuple(d["input_shape"])
        )

    def get_output_shape(self):
        # Use the standard convolution output dimension formula:
        # out_dim = floor((in_dim + 2*pad - kernel_dim)/stride) + 1
        in_height, in_width, _ = self.input_shape
        pad_h, pad_w = self.padding
        k_h, k_w = self.kernel_size
        s_h, s_w = self.stride

        out_height = math.floor((in_height + 2 * pad_h - k_h) / s_h) + 1
        out_width = math.floor((in_width + 2 * pad_w - k_w) / s_w) + 1
        # number of channels becomes num_filters
        return (out_height, out_width, self.num_filters)

    def get_output_size(self):
        out_shape = self.get_output_shape()
        prod = 1
        for dim in out_shape:
            prod *= dim
        return prod

    def __eq__(self, other):
        return (isinstance(other, Convolution) and
                self.num_filters == other.num_filters and
                self.kernel_size == other.kernel_size and
                self.stride == other.stride and
                self.padding == other.padding and
                self.input_shape == other.input_shape)

    def __repr__(self):
        return (f"Convolution(num_filters={self.num_filters}, kernel_size={self.kernel_size}, "
                f"stride={self.stride}, padding={self.padding}, input_shape={self.input_shape})")


class Pooling:
    def __init__(self, pool_size, stride, input_shape, mode='max'):
        # pool_size and stride: tuples or ints
        # mode: pooling mode (max or average)
        self.pool_size = pool_size if isinstance(pool_size, tuple) else (pool_size, pool_size)
        self.stride = stride if isinstance(stride, tuple) else (stride, stride)
        self.input_shape = input_shape  # (height, width, channels)
        self.mode = mode

    def to_dict(self):
        return {
            "type": "Pooling",
            "pool_size": self.pool_size,
            "stride": self.stride,
            "input_shape": self.input_shape,
            "mode": self.mode,
        }

    @classmethod
    def from_dict(cls, d):
        required = ["pool_size", "stride", "input_shape", "mode"]
        for key in required:
            if key not in d:
                raise ValueError(f"Missing parameter '{key}' for Pooling layer")
        return cls(
            pool_size=tuple(d["pool_size"]),
            stride=tuple(d["stride"]),
            input_shape=tuple(d["input_shape"]),
            mode=d["mode"]
        )

    def get_output_shape(self):
        # Assuming no padding for pooling, similar formula (but typically padding=0)
        in_height, in_width, channels = self.input_shape
        pool_h, pool_w = self.pool_size
        s_h, s_w = self.stride

        out_height = math.floor((in_height - pool_h) / s_h) + 1
        out_width = math.floor((in_width - pool_w) / s_w) + 1
        return (out_height, out_width, channels)

    def get_output_size(self):
        out_shape = self.get_output_shape()
        prod = 1
        for dim in out_shape:
            prod *= dim
        return prod

    def __eq__(self, other):
        return (isinstance(other, Pooling) and
                self.pool_size == other.pool_size and
                self.stride == other.stride and
                self.input_shape == other.input_shape and
                self.mode == other.mode)

    def __repr__(self):
        return (f"Pooling(pool_size={self.pool_size}, stride={self.stride}, "
                f"input_shape={self.input_shape}, mode='{self.mode}')")


class FullConnection:
    def __init__(self, input_units, output_units):
        # Full connection: from input_units to output_units.
        self.input_units = input_units
        self.output_units = output_units

    def to_dict(self):
        return {
            "type": "FullConnection",
            "input_units": self.input_units,
            "output_units": self.output_units,
        }

    @classmethod
    def from_dict(cls, d):
        required = ["input_units", "output_units"]
        for key in required:
            if key not in d:
                raise ValueError(f"Missing parameter '{key}' for FullConnection layer")
        return cls(
            input_units=d["input_units"],
            output_units=d["output_units"]
        )

    def get_output_shape(self):
        # In fully connected layer, the output is a 1D vector.
        return (self.output_units,)

    def get_output_size(self):
        return self.output_units

    def __eq__(self, other):
        return (isinstance(other, FullConnection) and
                self.input_units == other.input_units and
                self.output_units == other.output_units)

    def __repr__(self):
        return f"FullConnection(input_units={self.input_units}, output_units={self.output_units})"


# -------------------------- Serialization Function --------------------------

def layer_from_dict(d):
    if "type" not in d:
        raise ValueError("Missing 'type' in layer dictionary.")
    layer_type = d["type"]
    if layer_type == "Input":
        return Input.from_dict(d)
    elif layer_type == "Convolution":
        return Convolution.from_dict(d)
    elif layer_type == "Pooling":
        return Pooling.from_dict(d)
    elif layer_type == "FullConnection":
        return FullConnection.from_dict(d)
    else:
        raise ValueError(f"Unknown layer type: {layer_type}")


# -------------------------- Unit Tests --------------------------

class TestLayerSerialization(unittest.TestCase):

    def test_input_layer(self):
        input_layer = Input(shape=(28, 28, 1))
        serialized = input_layer.to_dict()
        self.assertEqual(serialized, {"type": "Input", "shape": (28, 28, 1)})
        deserialized = Input.from_dict(serialized)
        self.assertEqual(input_layer, deserialized)
        # Check output shape & output size.
        self.assertEqual(input_layer.get_output_shape(), (28, 28, 1))
        self.assertEqual(input_layer.get_output_size(), 28 * 28 * 1)

    def test_convolution_layer(self):
        conv_layer = Convolution(
            num_filters=32,
            kernel_size=(3, 3),
            stride=(1, 1),
            padding=(1, 1),
            input_shape=(28, 28, 1)
        )
        serialized = conv_layer.to_dict()
        expected_dict = {
            "type": "Convolution",
            "num_filters": 32,
            "kernel_size": (3, 3),
            "stride": (1, 1),
            "padding": (1, 1),
            "input_shape": (28, 28, 1)
        }
        self.assertEqual(serialized, expected_dict)
        deserialized = Convolution.from_dict(serialized)
        self.assertEqual(conv_layer, deserialized)
        # With padding of (1,1), output spatial dimensions should be same as input
        self.assertEqual(conv_layer.get_output_shape(), (28, 28, 32))
        self.assertEqual(conv_layer.get_output_size(), 28 * 28 * 32)

    def test_pooling_layer(self):
        pooling_layer = Pooling(
            pool_size=(2, 2),
            stride=(2, 2),
            input_shape=(28, 28, 32),
            mode="max"
        )
        serialized = pooling_layer.to_dict()
        expected_dict = {
            "type": "Pooling",
            "pool_size": (2, 2),
            "stride": (2, 2),
            "input_shape": (28, 28, 32),
            "mode": "max",
        }
        self.assertEqual(serialized, expected_dict)
        deserialized = Pooling.from_dict(serialized)
        self.assertEqual(pooling_layer, deserialized)
        # Pooling output shape: floor((28-2)/2)+1 = 14, so: (14, 14, 32)
        self.assertEqual(pooling_layer.get_output_shape(), (14, 14, 32))
        self.assertEqual(pooling_layer.get_output_size(), 14 * 14 * 32)

    def test_full_connection_layer(self):
        fc_layer = FullConnection(input_units=7 * 7 * 64, output_units=128)
        serialized = fc_layer.to_dict()
        expected_dict = {
            "type": "FullConnection",
            "input_units": 7 * 7 * 64,
            "output_units": 128,
        }
        self.assertEqual(serialized, expected_dict)
        deserialized = FullConnection.from_dict(serialized)
        self.assertEqual(fc_layer, deserialized)
        self.assertEqual(fc_layer.get_output_shape(), (128,))
        self.assertEqual(fc_layer.get_output_size(), 128)

    def test_layer_from_dict(self):
        # Try with a convolution layer dictionary.
        conv_dict = {
            "type": "Convolution",
            "num_filters": 64,
            "kernel_size": (3, 3),
            "stride": (1, 1),
            "padding": (0, 0),
            "input_shape": (32, 32, 3)
        }
        layer_obj = layer_from_dict(conv_dict)
        expected = Convolution(
            num_filters=64,
            kernel_size=(3, 3),
            stride=(1, 1),
            padding=(0, 0),
            input_shape=(32, 32, 3)
        )
        self.assertEqual(layer_obj, expected)
        # Also verify round-trip serialization
        self.assertEqual(layer_obj.to_dict(), conv_dict)

    def test_missing_parameters(self):
        # Test that missing required fields raises an error.
        missing_dict = {"type": "Pooling", "pool_size": (2, 2), "stride": (2, 2), "input_shape": (28, 28, 32)}
        with self.assertRaises(ValueError) as cm:
            Pooling.from_dict(missing_dict)
        self.assertIn("Missing parameter", str(cm.exception))


if __name__ == '__main__':
    unittest.main()

------------------------------------------------------------

Explanation:

1. Each class defines a to_dict method that returns a dictionary containing a "type" field and all parameters needed to re–create the layer. The from_dict class method checks that all required keys exist and then instantiates the object.

2. The get_output_shape method for:
   • Input returns its shape.
   • Convolution computes the output height and width using the formula:  
     output = floor((input + 2*padding – kernel_size) / stride) + 1  
     and sets the number of output channels equal to num_filters.
   • Pooling computes the output dimensions assuming zero–padding.
   • FullConnection’s output shape is a 1D vector (tuple with a single element).

3. The layer_from_dict function examines the "type" field in the input dictionary and calls the appropriate from_dict method.

4. The unit tests in TestLayerSerialization verify that:
   • Serialization produces the correct dictionary.
   • Deserialization re–produces an equivalent layer object.
   • The computed output shape and output size are correct.
   • Missing parameters in the dictionary lead to a ValueError.

This design meets the requirements to serialize and deserialize different neural network layer configurations while maintaining separation of concerns for each layer type.

